 31→export function Chat({
 32→  connected,
 33→  loading,
 34→  status,
 35→  messages,
 36→  rawMessages,
 37→  onSendMessage,
 38→  onSpawnAgent,
 39→  onRespondToControl,
 40→  onRespondToUserQuestion,
 41→  showTasks,
 42→  onToggleTasks,
 43→  onToggleSidebar,
 44→}: {
 45→  connected: boolean;
 46→  loading?: boolean;
 47→  status: AgentStatus;
 48→  messages: ChatMessage[];
 49→  rawMessages: ClaudeMessage[];
 50→  onSendMessage: (content: string) => void;
 51→  onSpawnAgent: (prompt: string) => void;
 52→  onRespondToControl: (requestId: string, allow: boolean) => void;
 53→  onRespondToUserQuestion: (requestId: string, answers: Record<string, string>) => void;
 54→  onClearHistory?: () => void;
 55→  showTasks?: boolean;
 56→  onToggleTasks?: () => void;
 57→  onToggleSidebar?: () => void;
 58→}) {
 59→  const [input, setInput] = useState("");
 60→  const [showRaw, setShowRaw] = useState(false);
 61→  const [showSlashMenu, setShowSlashMenu] = useState(false);
 62→  const [slashQuery, setSlashQuery] = useState("");
 63→  const [slashHighlight, setSlashHighlight] = useState(0);
 64→  const scrollRef = useRef<HTMLDivElement>(null);
 65→  const inputRef = useRef<HTMLInputElement>(null);
 66→
 67→  useEffect(() => {
 68→    scrollRef.current?.scrollTo({
 69→      top: scrollRef.current.scrollHeight,
 70→      behavior: "smooth",
 71→    });
 72→  }, [messages, rawMessages, showRaw]);
 73→
 74→  const displayItems = useMemo(() => condenseMessages(messages), [messages]);
 75→  const isActive = status === "connected" || status === "thinking";
 76→  const isArchived = status === "done" || status === "disconnected" || status === "error";
 77→
 78→  function handleSubmit(e: React.FormEvent) {
 79→    e.preventDefault();
 80→    const trimmed = input.trim();
 81→    if (!trimmed) return;
 82→
 83→    if (isActive) {
 84→      onSendMessage(trimmed);
 85→    } else {
 86→      onSpawnAgent(trimmed);
 87→    }
 88→    setInput("");
 89→    setShowSlashMenu(false);
 90→  }
 91→
 92→  function handleInputChange(e: React.ChangeEvent<HTMLInputElement>) {
 93→    const value = e.target.value;
 94→    setInput(value);
 95→
 96→    if (value.startsWith("/")) {
 97→      setShowSlashMenu(true);
 98→      setSlashQuery(value.slice(1));
 99→      setSlashHighlight(0);
100→    } else {
101→      setShowSlashMenu(false);
102→      setSlashQuery("");
103→    }
104→  }
105→
106→  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
107→    if (!showSlashMenu) return;
108→    const filtered = filterCommands(slashQuery);
109→    if (filtered.length === 0) return;
110→
111→    if (e.key === "ArrowDown") {
112→      e.preventDefault();
113→      setSlashHighlight((i) => (i + 1) % filtered.length);
114→    } else if (e.key === "ArrowUp") {
115→      e.preventDefault();
116→      setSlashHighlight((i) => (i - 1 + filtered.length) % filtered.length);
117→    } else if (e.key === "Enter") {
118→      e.preventDefault();
119→      handleCommandSelect(filtered[slashHighlight]);
120→    } else if (e.key === "Escape") {
121→      e.preventDefault();
122→      setShowSlashMenu(false);
123→    } else if (e.key === "Tab") {
124→      e.preventDefault();
125→      setInput(`/${filtered[slashHighlight].name} `);
126→      setShowSlashMenu(false);
127→    }
128→  }
129→
130→  function handleCommandSelect(command: SlashCommand) {
131→    setShowSlashMenu(false);
132→    setSlashQuery("");
133→    setInput("");
134→
135→    if (command.clientSide) {
136→      if (command.name === "clear") {
137→        onClearHistory?.();
138→      }
139→      return;
140→    }
141→
142→    const commandText = `/${command.name}`;
143→    if (isActive) {
144→      onSendMessage(commandText);
145→    } else {
146→      onSpawnAgent(commandText);
147→    }
148→  }
149→
150→  return (
151→    <div className="flex h-full flex-col">
152→      <StatusBar
153→        connected={connected}
154→        status={status}
155→        showRaw={showRaw}
156→        onToggleRaw={() => setShowRaw((v) => !v)}
157→        showTasks={showTasks}
158→        onToggleTasks={onToggleTasks}
159→        onToggleSidebar={onToggleSidebar}
160→      />
161→      <AgentSummary rawMessages={rawMessages} />
162→
163→      <div ref={scrollRef} className="flex-1 overflow-y-auto p-2 md:p-4 space-y-2">
164→        {loading ? (
165→          <div className="flex h-full flex-col items-center justify-center gap-3">
166→            <div className="flex gap-1">
167→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse" />
168→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:150ms]" />
169→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:300ms]" />
170→            </div>
171→            <span className="text-xs text-muted-foreground">
172→              {connected ? "Loading messages..." : "Connecting..."}
173→            </span>
174→          </div>
175→        ) : showRaw ? (
176→          rawMessages.length === 0 ? (
177→            <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
178→              No raw messages yet
179→            </div>
180→          ) : (
181→            <div className="space-y-1">
182→              {rawMessages.map((msg, i) => (
183→                <RawMessage key={i} message={msg} index={i} />
184→              ))}
185→            </div>
186→          )
187→        ) : (
188→          <>
189→            {messages.length === 0 && (
190→              <div className="flex h-full items-center justify-center">
191→                <div className="flex max-w-sm flex-col items-center gap-6 text-center">
192→                  <div className="flex size-12 items-center justify-center rounded-xl border bg-muted/50">
193→                    <Terminal className="size-6 text-muted-foreground" />
194→                  </div>
195→                  <div className="space-y-2">
196→                    <h2 className="text-base font-medium">Spawn an agent</h2>
197→                    <p className="text-sm text-muted-foreground">
198→                      Enter a prompt below to start a new Claude Code session. The agent runs in your terminal and streams results here in real time.
199→                    </p>
200→                  </div>
201→                  <div className="w-full space-y-2 text-left text-[13px]">
202→                    <div className="flex items-start gap-3 rounded-lg border px-3 py-2.5">
203→                      <MessageSquare className="mt-0.5 size-4 shrink-0 text-muted-foreground" />
204→                      <div>
205→                        <span className="font-medium">Chat</span>
206→                        <span className="text-muted-foreground"> — send follow-up messages to a running agent</span>
207→                      </div>
208→                    </div>
209→                    <div className="flex items-start gap-3 rounded-lg border px-3 py-2.5">
210→                      <ListTodo className="mt-0.5 size-4 shrink-0 text-muted-foreground" />
211→                      <div>
212→                        <span className="font-medium">Tasks</span>
213→                        <span className="text-muted-foreground"> — create tasks and delegate them to agents</span>
214→                      </div>
215→                    </div>
216→                  </div>
217→                </div>
218→              </div>
219→            )}
220→            {displayItems.map((item) => {
221→              if (item.kind === "condensed") {
222→                return <CondensedToolGroup key={item.id} group={item} />;
223→              }
224→              const msg = item.message;
225→              return msg.userQuestion ? (
226→                <UserQuestion
227→                  key={msg.id}
228→                  message={msg}
229→                  onRespond={onRespondToUserQuestion}
230→                />
231→              ) : msg.controlRequest ? (
232→                <ControlRequest
233→                  key={msg.id}
234→                  message={msg}
235→                  onRespond={onRespondToControl}
236→                />
237→              ) : (
238→                <Message key={msg.id} message={msg} />
239→              );
240→            })}
241→          </>
242→        )}
243→      </div>
244→
245→      {isArchived && messages.length > 0 ? (
246→        <div className="border-t px-4 py-2 text-center text-xs text-muted-foreground">
247→          This session has ended
248→        </div>
249→      ) : (
250→        <form
251→          onSubmit={handleSubmit}
252→          className="relative flex gap-2 border-t px-2 py-2 md:px-4 md:py-3"
253→        >
254→          {showSlashMenu && (
255→            <SlashCommandMenu
256→              query={slashQuery}
257→              highlightedIndex={slashHighlight}
258→              onSelect={handleCommandSelect}
259→              onHighlight={setSlashHighlight}
260→            />
261→          )}
262→          <input
263→            ref={inputRef}
264→            type="text"
265→            value={input}
266→            onChange={handleInputChange}
267→            onKeyDown={handleKeyDown}
268→            placeholder={isActive ? "Send a follow-up..." : "Enter a prompt to spawn agent..."}
269→            className="flex-1 rounded-md border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
270→          />
271→          <Button type="submit" disabled={!connected || !input.trim()}>
272→            {isActive ? "Send" : "Spawn"}
273→          </Button>
274→        </form>
275→      )}
276→    </div>
277→  );
278→}
