  3→/**
  4→ * Dashboard route (`/dashboard`).
  5→ *
  6→ * Orchestrates the multi-agent WebSocket hook, sidebar, chat panel, and
  7→ * task panel. Clicking "+" or selecting "New Agent" sets `activeAgentId`
  8→ * to `null`, which shows the spawn input. On spawn, the server responds
  9→ * with `spawned` and the hook auto-selects the new agent.
 10→ *
 11→ * ## Loading states
 12→ *
 13→ * Two loading flags from the hook control the UI:
 14→ * - `initialLoadDone` — false until the first `agent_list` arrives from
 15→ *   the server. While false, the sidebar shows skeleton rows.
 16→ * - `historyLoading` — true when the active agent's message history has
 17→ *   not been fetched yet (lazy loading). The chat shows a "Loading
 18→ *   messages..." indicator until the server responds.
 19→ *
 20→ * Sidebar uses `!initialLoadDone`, chat uses `!initialLoadDone || historyLoading`.
 21→ */
 22→
 23→import { useEffect, useRef, useState } from "react";
 24→import { toast } from "sonner";
 25→import { useWebSocket } from "@/hooks/use-websocket";
 26→import { AgentSidebar } from "@/components/dashboard/agent-sidebar";
 27→import { Chat } from "@/components/dashboard/chat";
 28→import { TaskPanel } from "@/components/dashboard/kanban-board";
 29→import type { TaskViewMode } from "@/components/dashboard/kanban-board";
 30→import { Toaster } from "@/components/ui/sonner";
 31→import { cn } from "@/lib/utils";
 32→
 33→export default function DashboardPage() {
 34→  const {
 35→    connected,
 36→    initialLoadDone,
 37→    historyLoading,
 38→    agents,
 39→    agentOrder,
 40→    activeAgentId,
 41→    setActiveAgentId,
 42→    activeStatus,
 43→    activeMessages,
 44→    activeRawMessages,
 45→    spawnAgent,
 46→    sendMessage,
 47→    respondToControl,
 48→    respondToUserQuestion,
 49→    killAgent,
 50→    deleteAgent,
 51→    renameAgent,
 52→    clearHistory,
 53→    tasks,
 54→    createTask,
 55→    updateTask,
 56→    deleteTask,
 57→    delegateTask,
 58→  } = useWebSocket();
 59→
 60→  const [taskView, setTaskView] = useState<TaskViewMode | "hidden">("hidden");
 61→  const [sidebarOpen, setSidebarOpen] = useState(false);
 62→
 63→  const showTasks = taskView !== "hidden";
 64→
 65→  // Connection toast: skip initial load, only fire on transitions after first connect
 66→  const hasConnectedRef = useRef(false);
 67→  useEffect(() => {
 68→    if (connected) {
 69→      if (hasConnectedRef.current) {
 70→        toast.success("Reconnected", { description: "WebSocket connection restored" });
 71→      }
 72→      hasConnectedRef.current = true;
 73→    } else if (hasConnectedRef.current) {
 74→      toast.error("Connection lost", { description: "Attempting to reconnect..." });
 75→    }
 76→  }, [connected]);
 77→
 78→  useEffect(() => {
 79→    document.title = "thos — dashboard";
 80→  }, []);
 81→
 82→  return (
 83→    <>
 84→    <div className="relative flex h-dvh overflow-hidden">
 85→      {/* Sidebar backdrop (mobile only) */}
 86→      {sidebarOpen && (
 87→        <div
 88→          className="fixed inset-0 z-40 bg-black/50 md:hidden"
 89→          onClick={() => setSidebarOpen(false)}
 90→        />
 91→      )}
 92→
 93→      {/* Sidebar drawer */}
 94→      <div
 95→        className={cn(
 96→          "fixed inset-y-0 left-0 z-50 w-56 transition-transform duration-200 ease-in-out md:relative md:z-auto md:translate-x-0 md:transition-none",
 97→          sidebarOpen ? "translate-x-0" : "-translate-x-full"
 98→        )}
 99→      >
100→        <AgentSidebar
101→          agents={agents}
102→          agentOrder={agentOrder}
103→          activeAgentId={activeAgentId}
104→          loading={!initialLoadDone}
105→          onSelect={(id) => {
106→            setActiveAgentId(id);
107→            setSidebarOpen(false);
108→          }}
109→          onNewAgent={() => {
110→            setActiveAgentId(null);
111→            setSidebarOpen(false);
112→          }}
113→          onKill={killAgent}
114→          onDelete={deleteAgent}
115→          onRename={renameAgent}
116→          onClearHistory={clearHistory}
117→        />
118→      </div>
119→
120→      {/* Main content: chat + optional task panel */}
121→      <div className="flex min-w-0 flex-1">
122→        {/* Chat — hidden only in board mode */}
123→        <div className={cn("flex min-w-0 flex-1 flex-col", taskView === "board" && "hidden")}>
124→          <Chat
125→            connected={connected}
126→            loading={!initialLoadDone || historyLoading}
127→            status={activeStatus}
128→            messages={activeMessages}
129→            rawMessages={activeRawMessages}
130→            onSendMessage={sendMessage}
131→            onSpawnAgent={spawnAgent}
132→            onRespondToControl={respondToControl}
133→            onRespondToUserQuestion={respondToUserQuestion}
134→            onClearHistory={() => { if (activeAgentId) clearHistory(activeAgentId); }}
135→            showTasks={showTasks}
136→            onToggleTasks={() => setTaskView((v) => v === "hidden" ? "list" : "hidden")}
137→            onToggleSidebar={() => setSidebarOpen((v) => !v)}
138→          />
139→        </div>
140→
141→        {/* Task panel — list: right sidebar, board: full width */}
142→        {showTasks && (
143→          <div
144→            className={cn(
145→              "flex flex-col border-l bg-background",
146→              taskView === "list"
147→                ? "w-80 max-w-[calc(100vw-3rem)]"
148→                : "min-w-0 flex-1"
149→            )}
150→          >
151→            <TaskPanel
152→              tasks={tasks}
153→              mode={taskView as TaskViewMode}
154→              onModeChange={setTaskView}
155→              onCreateTask={createTask}
156→              onUpdateTask={updateTask}
157→              onDeleteTask={deleteTask}
158→              onDelegateTask={delegateTask}
159→              onSelectAgent={(agentId) => {
160→                setActiveAgentId(agentId);
161→              }}
162→              onClose={() => setTaskView("hidden")}
163→            />
164→          </div>
165→        )}
166→      </div>
167→    </div>
168→    <Toaster />
169→    </>
170→  );
171→}
