}
```

#### 4d. Update `buildAgentList` to accept optional workspace filter

```typescript
function buildAgentList(workspaceId?: string | null): AgentInfo[] {
  return Array.from(agents.values())
    .filter((a) => workspaceId === undefined || workspaceId === null || a.workspaceId === workspaceId)
    .map((a) => ({
      agentId: a.agentId,
      status: a.status,
      tmuxSession: a.tmuxSession,
      label: a.label,
      createdAt: a.createdAt,
      workspaceId: a.workspaceId,
    }));
}
```

#### 4e. Update `buildTaskList` to accept optional workspace filter

```typescript
function buildTaskList(workspaceId?: string | null): Task[] {
  return Array.from(tasks.values())
    .filter((t) => workspaceId === undefined || workspaceId === null || t.workspaceId === workspaceId)
    .sort((a, b) => b.createdAt - a.createdAt);
}
```

#### 4f. Update broadcast functions to respect per-browser workspace scope

```typescript
function broadcastAgentList() {
  for (const ws of browserSockets) {
    if (ws.readyState !== WebSocket.OPEN) continue;
    const scope = browserWorkspaceScope.get(ws) ?? null;
    ws.send(JSON.stringify({
      type: "agent_list",
      agents: buildAgentList(scope),
    }));
  }
}

function broadcastTaskList() {
  for (const ws of browserSockets) {
    if (ws.readyState !== WebSocket.OPEN) continue;
    const scope = browserWorkspaceScope.get(ws) ?? null;
    ws.send(JSON.stringify({
      type: "task_list",
      tasks: buildTaskList(scope),
    }));
  }
}

function broadcastWorkspaceList() {
  const payload = JSON.stringify({
    type: "workspace_list",
    workspaces: Array.from(workspaces.values()),
  });
  for (const ws of browserSockets) {
    if (ws.readyState === WebSocket.OPEN) ws.send(payload);
