/**
 * Standalone WebSocket relay server for the thos dashboard.
 *
 * Runs on port 9900 alongside Next.js (started via `concurrently` in the
 * `dev` script). It cannot be a Next.js API route because API routes don't
 * support persistent WebSocket connections.
 *
 * ## Architecture
 *
 * Two WebSocket path families:
 * - `/browser`          — the React dashboard connects here (supports multiple tabs).
 * - `/claude/:agentId`  — each Claude CLI connects here (passed as `--sdk-url`).
 *
 * The server supports multiple concurrent agents, each tracked in the
 * `agents` Map keyed by a short random ID.
 *
 * ## Connection flow (browser)
 *
 * On browser connect, the server sends two small messages:
 * 1. `agent_list`  — metadata for all agents (sidebar).
 * 2. `task_list`   — all tasks.
 *
 * Message histories are NOT sent eagerly. They are loaded lazily: the
 * browser sends `{ type: "request_history", agentId }` when the user
 * selects an agent, and the server responds with `message_history` for
 * that single agent. This avoids sending megabytes of JSON on connect,
 * which caused multi-minute loading times on mobile networks.
 *
 * Live messages for active agents are still broadcast to all browsers
 * via `relay` messages in real time.
 *
 * ## Message flow (spawning)
 *
 * 1. Browser sends `{ type: "spawn", prompt }`.
 * 2. Server creates agent entry, spawns `claude --sdk-url ws://localhost:9900/claude/<agentId>`.
 * 3. CLI connects on `/claude/<agentId>`.
 * 4. Server immediately sends the pending prompt as a `user` message.
 * 5. CLI sends `system/init`, then `assistant` messages, then `result`.
 * 6. All CLI messages are relayed to the browser as `{ type: "relay", agentId, message }`.
 * 7. `control_request` messages (tool approval) are relayed to the browser;
 *    the browser's `control_response` (with `agentId`) is forwarded back to the right CLI.
 *
 * Note: CLI 2.1.41 sent `hook_started`/`hook_response` before `init`; CLI 2.1.42+
 * waits for the server to send the first user message. The `hook_response` handler
 * is kept as a fallback for older CLI versions.
 *
 * ## Resilience features
 *
 * - **Server-side message history** — every relay message is stored per-agent.
 * - **File persistence** — agent state + history persisted to disk, survives restarts.
 * - **Multi-browser** — multiple tabs can connect simultaneously.
 * - **tmux survival** — tmux sessions are NOT killed on server restart; CLI processes
 *   can reconnect to the new server if they retry their WebSocket connection.
 * - **Message queuing** — messages sent while CLI is disconnected are queued and flushed on reconnect.
 * - **Disconnect notifications** — browser is notified of CLI disconnect/reconnect.
 * - **Lazy history** — message histories loaded on demand per agent, not on connect.
 */
import { WebSocketServer, WebSocket } from "ws";
import { execSync, spawn } from "child_process";
import { randomBytes } from "crypto";
import type { IncomingMessage } from "http";
import type {
  BrowserMessage,
  ClaudeMessage,
  ServerMessage,
  AgentStatus,
  AgentInfo,
  Task,
  Workspace,
} from "../lib/types";
import { SessionStore, type PersistedAgent } from "./session-store";
import { TaskStore } from "./task-store";
import { WorkspaceStore } from "./workspace-store";

const PORT = 9900;
const TMUX_SESSION_PREFIX = "thos-agent";

/** Check if an IP is localhost or in the Tailscale CGNAT range (100.64.0.0/10). */
function isAllowedIP(ip: string | undefined): boolean {
  if (!ip) return false;
  // Strip IPv6-mapped IPv4 prefix
  const addr = ip.startsWith("::ffff:") ? ip.slice(7) : ip;
  if (addr === "127.0.0.1" || addr === "::1" || addr === "localhost") return true;
  // Tailscale CGNAT: 100.64.0.0/10 → 100.64.0.0 – 100.127.255.255
  const parts = addr.split(".");
  if (parts.length !== 4) return false;
  const first = parseInt(parts[0], 10);
  const second = parseInt(parts[1], 10);
  return first === 100 && second >= 64 && second <= 127;
}

const wss = new WebSocketServer({
  port: PORT,
  verifyClient: (info) => {
    const ip = info.req.socket.remoteAddress;
    const allowed = isAllowedIP(ip);
    if (!allowed) console.log(`[ws] rejected connection from ${ip}`);
    return allowed;
  },
});
const store = new SessionStore();

// ── Multi-agent state ──────────────────────────────────────────────────────

interface AgentState {
  agentId: string;
  claudeSocket: WebSocket | null;
  tmuxSession: string | null;
  pendingPrompt: string | null;
  status: AgentStatus;
  label: string;
  createdAt: number;
  /** Captured from system/init, used in subsequent user messages. */
  sessionId: string | null;
  /** Workspace this agent belongs to. */
  workspaceId: string | null;
  /** Stores control_request inputs keyed by request_id, for building control_responses. */
  pendingControlRequests: Map<string, Record<string, unknown>>;
  /** All messages sent to the browser for this agent (source of truth). */
  messageHistory: ServerMessage[];
  /** Messages queued while CLI is disconnected, flushed on reconnect. */
  pendingMessages: string[];
}

const agents = new Map<string, AgentState>();
const taskStore = new TaskStore();
const tasks = new Map<string, Task>();
const workspaceStore = new WorkspaceStore();
const workspaces = new Map<string, Workspace>();

/** All active browser connections (supports multiple tabs). */
const browserSockets = new Set<WebSocket>();

/** Per-browser workspace scope (null = all workspaces). */
const browserWorkspaceScope = new Map<WebSocket, string | null>();

/** Generate a short random agent ID. */
function newAgentId(): string {
  return randomBytes(4).toString("hex");
}

// ── tmux helpers ───────────────────────────────────────────────────────────

/** Return the set of currently alive tmux session names matching the thos prefix. */
function listAliveTmuxSessions(): Set<string> {
  try {
    const output = execSync("tmux list-sessions -F '#{session_name}'", {
      encoding: "utf-8",
    }).trim();
    if (!output) return new Set();
    return new Set(output.split("\n").filter((s) => s.startsWith(TMUX_SESSION_PREFIX)));
  } catch {
    return new Set();
  }
}

// ── Persistence helpers ────────────────────────────────────────────────────

/** Build a PersistedAgent snapshot from live state. */
function toPersistedAgent(agent: AgentState): PersistedAgent {
  return {
    id: agent.agentId,
    state: {
      agentId: agent.agentId,
      status: agent.status,
      tmuxSession: agent.tmuxSession,
      label: agent.label,
      createdAt: agent.createdAt,
      sessionId: agent.sessionId,
      workspaceId: agent.workspaceId,
    },
    messageHistory: agent.messageHistory,
  };
}

/**
 * Compact a message history by deduplicating cumulative snapshots.
 * Keeps only the last version of each assistant/user message ID.
 * Called on restore to shrink legacy bloated histories.
 */
function compactHistory(history: ServerMessage[]): ServerMessage[] {
  // Build a map of msgId → last index
  const lastIndex = new Map<string, number>();
  for (let i = 0; i < history.length; i++) {
    const id = getRelayMessageId(history[i]);
    if (id) lastIndex.set(id, i);
  }
  // Keep only messages that are either non-deduplicable or the last occurrence
  return history.filter((msg, i) => {
    const id = getRelayMessageId(msg);
    if (!id) return true; // non-relay or no message ID — always keep
    return lastIndex.get(id) === i;
  });
}

/** Persist agent state (debounced — use for streaming events). */
function persistAgent(agent: AgentState) {
  store.save(toPersistedAgent(agent));
}

/** Persist agent state immediately (use for critical state changes). */
function persistAgentSync(agent: AgentState) {
  store.saveSync(toPersistedAgent(agent));
}

// ── Restore from disk on startup ───────────────────────────────────────────

function restoreAgents() {
  const persisted = store.loadAll();
  const aliveSessions = listAliveTmuxSessions();

  for (const p of persisted) {
    const agent: AgentState = {
      agentId: p.state.agentId,
      claudeSocket: null,
      tmuxSession: p.state.tmuxSession,
      pendingPrompt: null,
      status: p.state.status,
      label: p.state.label,
      createdAt: p.state.createdAt,
      sessionId: p.state.sessionId,
      workspaceId: p.state.workspaceId ?? null,
      pendingControlRequests: new Map(),
      messageHistory: compactHistory(p.messageHistory),
      pendingMessages: [],
    };

    // Determine status for agents that were active when the server last ran
    if (agent.status !== "done" && agent.status !== "error") {
      const tmuxAlive = agent.tmuxSession ? aliveSessions.has(agent.tmuxSession) : false;
      if (tmuxAlive) {
        // tmux session still alive — CLI may reconnect to this server
        agent.status = "disconnected";
        console.log(`[restore] agent ${agent.agentId} — tmux alive, waiting for CLI reconnect`);
      } else {
        // tmux session gone — agent is archived
        agent.status = "done";
        console.log(`[restore] agent ${agent.agentId} — tmux dead, archived`);
      }
    }

    agents.set(agent.agentId, agent);
    const originalCount = p.messageHistory.length;
    const compactedCount = agent.messageHistory.length;
    const saved = originalCount - compactedCount;
    console.log(`[restore] agent ${agent.agentId} (status=${agent.status}, ${compactedCount} messages${saved > 0 ? `, compacted from ${originalCount} (−${saved})` : ""})`);

    // Persist compacted history back to disk
    if (saved > 0) {
      persistAgentSync(agent);
    }
  }
  console.log(`[restore] loaded ${persisted.length} agents from disk`);
}

// ── Workspace restore ───────────────────────────────────────────────────

function restoreWorkspaces() {
  const persisted = workspaceStore.loadAll();
  for (const w of persisted) {
    workspaces.set(w.id, w);
  }
  console.log(`[restore] loaded ${persisted.length} workspaces from disk`);
}

restoreWorkspaces();
restoreAgents();

// ── Task restore + helpers ────────────────────────────────────────────────

function restoreTasks() {
  const persisted = taskStore.loadAll();
  for (const t of persisted) {
    tasks.set(t.id, t);
  }
  console.log(`[restore] loaded ${persisted.length} tasks from disk`);
}

restoreTasks();

// ── Default workspace migration ────────────────────────────────────────────

/** Create a default workspace from process.cwd() and assign all unscoped agents/tasks. */
function migrateDefaultWorkspace() {
  if (workspaces.size > 0) return;

  const cwd = process.cwd();
  const name = cwd.split("/").pop() ?? "default";
  const id = randomBytes(4).toString("hex");
  const workspace: Workspace = { id, name, cwd, createdAt: Date.now() };
  workspaces.set(id, workspace);

  let migratedAgents = 0;
  for (const agent of agents.values()) {
    if (!agent.workspaceId) {
      agent.workspaceId = id;
      persistAgentSync(agent);
      migratedAgents++;
    }
  }

  let migratedTasks = 0;
  for (const task of tasks.values()) {
    if (!task.workspaceId) {
      task.workspaceId = id;
      migratedTasks++;
    }
  }
  if (migratedTasks > 0) persistTasks();

  workspaceStore.saveSync(Array.from(workspaces.values()));
  console.log(`[migrate] created default workspace "${name}" (${id}) — ${migratedAgents} agents, ${migratedTasks} tasks`);
}

migrateDefaultWorkspace();

/** Build the task list sorted by creation time (newest first), optionally filtered by workspace. */
function buildTaskList(workspaceId?: string | null): Task[] {
  return Array.from(tasks.values())
    .filter((t) => workspaceId === undefined || workspaceId === null || t.workspaceId === workspaceId)
    .sort((a, b) => b.createdAt - a.createdAt);
}

/** Send the workspace-scoped task list to all browsers. */
function broadcastTaskList() {
  for (const ws of browserSockets) {
    if (ws.readyState !== WebSocket.OPEN) continue;
    const scope = browserWorkspaceScope.get(ws) ?? null;
    ws.send(JSON.stringify({ type: "task_list", tasks: buildTaskList(scope) }));
  }
}

/** Send the full workspace list to all browsers. */
function broadcastWorkspaceList() {
  const payload = JSON.stringify({
    type: "workspace_list",
    workspaces: Array.from(workspaces.values()),
  });
  for (const ws of browserSockets) {
    if (ws.readyState === WebSocket.OPEN) ws.send(payload);
  }
}

/** Persist all tasks to disk (sync). */
function persistTasks() {
  taskStore.saveSync(Array.from(tasks.values()));
}

// ── Helpers ────────────────────────────────────────────────────────────────

/** Send a JSON message to all connected browsers. */
function sendToBrowser(msg: ServerMessage) {
  const payload = JSON.stringify(msg);
  for (const ws of browserSockets) {
    if (ws.readyState === WebSocket.OPEN) {
      ws.send(payload);
    }
  }
}

/** Build a snapshot of agents for the sidebar, optionally filtered by workspace. */
function buildAgentList(workspaceId?: string | null): AgentInfo[] {
  return Array.from(agents.values())
    .filter((a) => workspaceId === undefined || workspaceId === null || a.workspaceId === workspaceId)
    .map((a) => ({
      agentId: a.agentId,
      status: a.status,
      tmuxSession: a.tmuxSession,
      label: a.label,
      createdAt: a.createdAt,
      workspaceId: a.workspaceId,
    }));
}

/** Send the workspace-scoped agent list to all browsers. */
function broadcastAgentList() {
  for (const ws of browserSockets) {
    if (ws.readyState !== WebSocket.OPEN) continue;
    const scope = browserWorkspaceScope.get(ws) ?? null;
    ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList(scope) }));
  }
}

/** Update an agent's status, notify browsers, broadcast list, and persist. */
function setAgentStatus(agentId: string, status: AgentStatus) {
  const agent = agents.get(agentId);
  if (!agent) return;
  agent.status = status;
  sendToBrowser({ type: "status", agentId, status });
  broadcastAgentList();
  persistAgentSync(agent);
}

/**
 * Extract a stable dedup key from a relay message, if present.
 *
 * Claude NDJSON sends cumulative snapshots for two message types:
 * - `assistant` — keyed by `message.id` (e.g. `msg_01VE1P7c...`)
 * - `user` (tool_result) — keyed by top-level `uuid` (e.g. `b217b852-...`)
 *
 * We deduplicate by replacing the previous snapshot in `messageHistory`
 * instead of appending, reducing storage from O(n²) to O(n).
 */
function getRelayMessageId(msg: ServerMessage): string | null {
  if (msg.type !== "relay") return null;
  const inner = msg.message;
  if (inner.type === "assistant") {
    return (inner as { message?: { id?: string } }).message?.id ?? null;
  }
  if (inner.type === "user") {
    return (inner as { uuid?: string }).uuid ?? null;
  }
  return null;
}

/**
 * Record a message in the agent's history and send to all browsers.
 *
 * For cumulative snapshot messages (assistant, user/tool_result), replaces the
 * previous snapshot with the same message ID instead of appending. This keeps
 * only the final version of each message, dramatically reducing file sizes
 * (e.g. 38 MB → ~1 MB for a typical session).
 */
function recordAndSend(agentId: string, msg: ServerMessage) {
  const agent = agents.get(agentId);
  if (agent) {
    const msgId = getRelayMessageId(msg);
    if (msgId) {
      // Replace previous snapshot with same message ID (search from end for speed)
      let replaced = false;
      for (let i = agent.messageHistory.length - 1; i >= 0; i--) {
        if (getRelayMessageId(agent.messageHistory[i]) === msgId) {
          agent.messageHistory[i] = msg;
          replaced = true;
          break;
        }
      }
      if (!replaced) {
        agent.messageHistory.push(msg);
      }
    } else {
      agent.messageHistory.push(msg);
    }
    persistAgent(agent); // debounced — streaming messages come fast
  }
  sendToBrowser(msg);
}

// ── Agent lifecycle ────────────────────────────────────────────────────────

/**
 * Stop a running agent by killing its tmux session and closing the CLI socket.
 * The agent remains in the Map (status set to "done") so it can be viewed/deleted later.
 */
function stopAgent(agentId: string) {
  const agent = agents.get(agentId);
  if (!agent) return;

  if (agent.tmuxSession) {
    try {
      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
      console.log(`[tmux] killed session ${agent.tmuxSession}`);
    } catch {
      // Session may already be dead
    }
  }
  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
    agent.claudeSocket.close();
  }
  agent.claudeSocket = null;
  setAgentStatus(agentId, "done");
}

/**
 * Permanently delete an agent: stop it, remove from Map, remove from disk.
 */
function deleteAgent(agentId: string) {
  const agent = agents.get(agentId);
  if (!agent) return;

  if (agent.tmuxSession) {
    try {
      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
    } catch {}
  }
  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
    agent.claudeSocket.close();
  }
  agents.delete(agentId);
  store.remove(agentId);
  broadcastAgentList();
}

/**
 * Spawn a new Claude CLI process inside a tmux session.
 *
 * Creates a new agent entry, spawns the CLI with `--sdk-url` pointing to
 * `/claude/<agentId>`, and sends a `spawned` message to the browser.
 */
function spawnClaude(prompt: string, workspaceId?: string): string {
  const agentId = newAgentId();
  const sessionName = `${TMUX_SESSION_PREFIX}-${agentId}`;
  const label = prompt.length > 60 ? prompt.slice(0, 57) + "..." : prompt;

  const agent: AgentState = {
    agentId,
    claudeSocket: null,
    tmuxSession: null,
    pendingPrompt: prompt,
    status: "spawning",
    label,
    createdAt: Date.now(),
    sessionId: null,
    workspaceId: workspaceId ?? null,
    pendingControlRequests: new Map(),
    messageHistory: [],
    pendingMessages: [],
  };
  agents.set(agentId, agent);

  // Notify browsers
  sendToBrowser({ type: "spawned", agentId });
  broadcastAgentList();
  persistAgentSync(agent);

  // Resolve workspace cwd for tmux starting directory
  const workspace = workspaceId ? workspaces.get(workspaceId) : null;
  const agentCwd = workspace?.cwd ?? process.cwd();

  // Build the claude command with CLAUDECODE unset to bypass nesting protection.
  // tmux new-session runs detached (-d) so spawn() returns immediately.
  const claudeCmd = `unset CLAUDECODE; exec claude --dangerously-skip-permissions --sdk-url ws://localhost:${PORT}/claude/${agentId}`;

  const tmux = spawn("tmux", ["new-session", "-d", "-s", sessionName, "-c", agentCwd, "bash", "-c", claudeCmd], {
    stdio: "ignore",
  });

  tmux.on("error", (err) => {
    console.error("[tmux spawn error]", err);
    setAgentStatus(agentId, "error");
    recordAndSend(agentId, { type: "error", agentId, error: `tmux error: ${err.message}` });
  });

  tmux.on("exit", (code) => {
    if (code !== 0) {
      console.error(`[tmux] new-session exited with code ${code}`);
      setAgentStatus(agentId, "error");
      recordAndSend(agentId, { type: "error", agentId, error: `tmux exited with code ${code}` });
      return;
    }
    console.log(`[tmux] session ${sessionName} created — attach with: tmux attach -t ${sessionName}`);
    agent.tmuxSession = sessionName;
    broadcastAgentList();
    persistAgentSync(agent);
  });

  return agentId;
}

// ── Message handlers ───────────────────────────────────────────────────────

/**
 * Process an incoming NDJSON message from a specific Claude CLI.
 *
 * Status flow matches the Companion protocol:
 * - hook_response → send pending prompt → "thinking"
 * - system/init   → "connected" + capture session_id
 * - assistant      → "thinking"
 * - result         → "connected" (CLI stays alive for multi-turn)
 * - CLI disconnect → "done" (handled in connection close handler)
 */
function handleClaudeMessage(agentId: string, raw: string) {
  const agent = agents.get(agentId);
  if (!agent) return;

  let msg: ClaudeMessage;
  try {
    msg = JSON.parse(raw);
  } catch {
    console.error(`[claude:${agentId}] invalid JSON:`, raw);
    return;
  }

  // Silently ignore keep_alive messages
  if (msg.type === "keep_alive") return;

  console.log(`[claude:${agentId} →]`, msg.type, (msg as { subtype?: string }).subtype ?? "");

  // After hook_response, send the pending prompt
  if (
    msg.type === "system" &&
    (msg as { subtype?: string }).subtype === "hook_response" &&
    agent.pendingPrompt &&
    agent.claudeSocket?.readyState === WebSocket.OPEN
  ) {
    const userMsg = JSON.stringify({
      type: "user",
      message: { role: "user", content: agent.pendingPrompt },
      parent_tool_use_id: null,
      session_id: agent.sessionId ?? "",
    });
    console.log(`[server → claude:${agentId}]`, userMsg);
    agent.claudeSocket.send(userMsg + "\n");

    // Record the initial user message in history so it appears in chat
    recordAndSend(agentId, {
      type: "relay",
      agentId,
      message: { type: "user", message: { role: "user", content: agent.pendingPrompt } },
    } as ServerMessage);

    agent.pendingPrompt = null;
    setAgentStatus(agentId, "thinking");
  }

  // Track status based on message type
  if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
    // Capture session_id for subsequent user messages
    const isFirstInit = agent.sessionId === null;
    agent.sessionId = (msg as { session_id?: string }).session_id ?? null;

    // Auto-assign workspace from cwd if not already set
    if (!agent.workspaceId) {
      const initCwd = (msg as { cwd?: string }).cwd;
      if (initCwd) {
        const existing = Array.from(workspaces.values()).find((w) => w.cwd === initCwd);
        if (existing) {
          agent.workspaceId = existing.id;
          persistAgentSync(agent);
          broadcastAgentList();
        }
      }
    }

    setAgentStatus(agentId, "connected");

    // Only relay the first system/init — subsequent ones are redundant
    // (CLI re-sends init on every turn)
    if (!isFirstInit) return;
  } else if (msg.type === "assistant") {
    setAgentStatus(agentId, "thinking");
  } else if (msg.type === "result") {
    // CLI stays alive after result — ready for the next turn.
    // Status only goes to "done" when the CLI WebSocket actually closes.
    setAgentStatus(agentId, "connected");
  }

  // Store control_request inputs for building proper responses later
  if (msg.type === "control_request") {
    const cr = msg as { request_id?: string; request?: { input?: Record<string, unknown> } };
    if (cr.request_id && cr.request?.input) {
      agent.pendingControlRequests.set(cr.request_id, cr.request.input);
    }
  }

  // Record in history and relay to browsers
  recordAndSend(agentId, { type: "relay", agentId, message: msg });
}

/**
 * Process an incoming JSON message from the browser.
 * - `spawn`: create a new agent (does NOT kill others).
 * - `send_message`: forward a follow-up user message to the specified agent.
 * - `control_response`: forward a tool allow/deny decision to the specified agent.
 * - `kill_agent`: stop the CLI and tmux session.
 * - `delete_agent`: permanently remove an agent.
 * - `rename_agent`: update an agent's label.
 * - `clear_history`: wipe an agent's message history.
 * - `request_history`: send message history for a single agent (lazy loading).
 * - `create_task` / `update_task` / `delete_task` / `delegate_task`: task CRUD.
 */
function handleBrowserMessage(raw: string, senderWs: WebSocket) {
  let msg: BrowserMessage;
  try {
    msg = JSON.parse(raw);
  } catch {
    console.error("[browser] invalid JSON:", raw);
    return;
  }

  console.log("[browser →]", msg.type);

  switch (msg.type) {
    case "spawn":
      spawnClaude(msg.prompt, msg.workspaceId ?? browserWorkspaceScope.get(senderWs) ?? undefined);
      break;

    case "send_message": {
      const agent = agents.get(msg.agentId);
      if (!agent) {
        sendToBrowser({ type: "error", agentId: msg.agentId, error: "Unknown agent" });
        break;
      }

      // Record the user message in history so it persists across reloads.
      // Do NOT broadcast — the sending browser already has it optimistically,
      // and other browsers will get it when they request_history.
      agent.messageHistory.push({
        type: "relay",
        agentId: msg.agentId,
        message: { type: "user", message: { role: "user", content: msg.content } },
      } as ServerMessage);
      persistAgent(agent);

      if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
        const userMsg = JSON.stringify({
          type: "user",
          message: { role: "user", content: msg.content },
          parent_tool_use_id: null,
          session_id: agent.sessionId ?? "",
        });
        agent.claudeSocket.send(userMsg + "\n");
        setAgentStatus(msg.agentId, "thinking");
      } else {
        // Queue message for delivery when CLI reconnects
        const userMsg = JSON.stringify({
          type: "user",
          message: { role: "user", content: msg.content },
          parent_tool_use_id: null,
          session_id: agent.sessionId ?? "",
        });
        agent.pendingMessages.push(userMsg);
        console.log(`[queue] queued message for agent ${msg.agentId} (${agent.pendingMessages.length} pending)`);
        persistAgentSync(agent);
      }
      break;
    }

    case "control_response": {
      const agent = agents.get(msg.agentId);
      if (agent?.claudeSocket?.readyState === WebSocket.OPEN) {
        // Retrieve the original tool input to include as updatedInput (required by protocol)
        const originalInput = agent.pendingControlRequests.get(msg.request_id) ?? {};
        agent.pendingControlRequests.delete(msg.request_id);

        // If the browser sent answers (from AskUserQuestion), merge them into the input
        const answers = (msg as { answers?: Record<string, string> }).answers;
        const updatedInput = answers
          ? { ...originalInput, answers }
          : originalInput;

        const response = JSON.stringify({
          type: "control_response",
          response: {
            subtype: "success",
            request_id: msg.request_id,
            response: msg.allow
              ? { behavior: "allow", updatedInput }
              : { behavior: "deny", message: "Denied by user" },
          },
        });
        agent.claudeSocket.send(response + "\n");
      }
      break;
    }

    case "kill_agent":
      stopAgent(msg.agentId);
      break;

    case "delete_agent":
      deleteAgent(msg.agentId);
      break;

    case "rename_agent": {
      const agent = agents.get(msg.agentId);
      if (!agent) break;
      agent.label = msg.label;
      broadcastAgentList();
      persistAgentSync(agent);
      break;
    }

    case "clear_history": {
      const agent = agents.get(msg.agentId);
      if (!agent) break;
      agent.messageHistory = [];
      persistAgentSync(agent);
      sendToBrowser({ type: "history_cleared", agentId: msg.agentId });
      break;
    }

    case "request_history": {
      console.log(`[browser] request_history for ${msg.agentId}`);
      sendHistoryToSocket(senderWs, msg.agentId);
      break;
    }

    case "create_task": {
      const taskId = randomBytes(4).toString("hex");
      const task: Task = {
        id: taskId,
        title: msg.title,
        description: msg.description,
        status: "todo",
        priority: msg.priority,
        agentId: null,
        workspaceId: browserWorkspaceScope.get(senderWs) ?? null,
        createdAt: Date.now(),
        updatedAt: Date.now(),
      };
      tasks.set(taskId, task);
      persistTasks();
      broadcastTaskList();
      break;
    }

    case "update_task": {
      const task = tasks.get(msg.taskId);
      if (!task) break;
      Object.assign(task, msg.updates, { updatedAt: Date.now() });
      persistTasks();
      broadcastTaskList();

      // Archive the linked agent when a task is marked as done
      if (task.status === "done" && task.agentId) {
        const linkedAgent = agents.get(task.agentId);
        if (linkedAgent && linkedAgent.status !== "done" && linkedAgent.status !== "error") {
          stopAgent(task.agentId);
        }
      }
      break;
    }

    case "delete_task": {
      tasks.delete(msg.taskId);
      persistTasks();
      broadcastTaskList();
      break;
    }

    case "delegate_task": {
      const task = tasks.get(msg.taskId);
      if (!task) break;
      const prompt = `Task: ${task.title}\n\n${task.description}`;
      const agentId = spawnClaude(prompt, task.workspaceId ?? undefined);
      task.agentId = agentId;
      task.status = "in-progress";
      task.updatedAt = Date.now();
      persistTasks();
      broadcastTaskList();
      break;
    }

    case "set_workspace": {
      browserWorkspaceScope.set(senderWs, msg.workspaceId);
      sendFullStateToSocket(senderWs);
      break;
    }

    case "create_workspace": {
      const wsId = randomBytes(4).toString("hex");
      const ws: Workspace = {
        id: wsId,
        name: msg.name,
        cwd: msg.cwd,
        createdAt: Date.now(),
      };
      workspaces.set(wsId, ws);
      workspaceStore.saveSync(Array.from(workspaces.values()));
      broadcastWorkspaceList();
      break;
    }

    case "rename_workspace": {
      const ws = workspaces.get(msg.workspaceId);
      if (!ws) break;
      ws.name = msg.name;
      workspaceStore.saveSync(Array.from(workspaces.values()));
      broadcastWorkspaceList();
      break;
    }

    case "delete_workspace": {
      workspaces.delete(msg.workspaceId);
      workspaceStore.saveSync(Array.from(workspaces.values()));
      // Unscope agents and tasks from the deleted workspace
      for (const agent of agents.values()) {
        if (agent.workspaceId === msg.workspaceId) {
          agent.workspaceId = null;
          persistAgentSync(agent);
        }
      }
      for (const task of tasks.values()) {
        if (task.workspaceId === msg.workspaceId) {
          task.workspaceId = null;
        }
      }
      persistTasks();
      broadcastWorkspaceList();
      broadcastAgentList();
      broadcastTaskList();
      break;
    }
  }
}

// ── Send message history to a single browser socket ────────────────────────

/** Send initial state (workspaces + agent list + tasks) to a newly connected browser. */
function sendFullStateToSocket(ws: WebSocket) {
  if (ws.readyState !== WebSocket.OPEN) return;
  const scope = browserWorkspaceScope.get(ws) ?? null;

  // Workspace list
  ws.send(JSON.stringify({ type: "workspace_list", workspaces: Array.from(workspaces.values()) }));

  // Agent list (sidebar metadata) — message histories are loaded lazily on demand
  ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList(scope) }));

  // Task list
  ws.send(JSON.stringify({ type: "task_list", tasks: buildTaskList(scope) }));
}

/** Send message history for a single agent to a specific browser socket. */
function sendHistoryToSocket(ws: WebSocket, agentId: string) {
  const agent = agents.get(agentId);
  if (!agent || ws.readyState !== WebSocket.OPEN) return;
  ws.send(
    JSON.stringify({
      type: "message_history",
      agentId: agent.agentId,
      messages: agent.messageHistory,
    })
  );
}

// ── Connection handler — route by URL path ────────────────────────────────
wss.on("connection", (ws: WebSocket, req: IncomingMessage) => {
  const path = req.url ?? "/";
  console.log(`[ws connected] path=${path}`);

  if (path === "/browser") {
    // Send full state BEFORE adding to browserSockets so that live
    // relay broadcasts don't interleave with the history replay.
    sendFullStateToSocket(ws);
    browserSockets.add(ws);

    ws.on("message", (data) => {
      handleBrowserMessage(data.toString(), ws);
    });

    ws.on("close", () => {
      console.log("[browser disconnected]");
      browserSockets.delete(ws);
      browserWorkspaceScope.delete(ws);
      // Do NOT kill agents — keep them alive for reconnect
    });
  } else if (path.startsWith("/claude/")) {
    // Parse agentId from /claude/<agentId>
    const agentId = path.slice("/claude/".length);
    const agent = agents.get(agentId);

    if (!agent) {
      console.log(`[ws] unknown agentId: ${agentId}, closing`);
      ws.close();
      return;
    }

    agent.claudeSocket = ws;
    console.log(`[claude:${agentId} CLI connected via WebSocket]`);

    // Notify browsers that CLI is connected
    sendToBrowser({ type: "cli_connected", agentId });

    // Flush any pending messages queued while CLI was disconnected
    if (agent.pendingMessages.length > 0) {
      console.log(`[flush] sending ${agent.pendingMessages.length} queued messages to agent ${agentId}`);
      for (const queued of agent.pendingMessages) {
        ws.send(queued + "\n");
      }
      agent.pendingMessages = [];
      persistAgentSync(agent);
    }

    // Send the pending prompt immediately — CLI 2.1.42+ waits for the
    // server to send the first user message rather than emitting
    // hook_started/hook_response on connect.
    if (agent.pendingPrompt && ws.readyState === WebSocket.OPEN) {
      const userMsg = JSON.stringify({
        type: "user",
        message: { role: "user", content: agent.pendingPrompt },
        parent_tool_use_id: null,
        session_id: agent.sessionId ?? "",
      });
      console.log(`[server → claude:${agentId}] sending pending prompt`);
      ws.send(userMsg + "\n");

      // Record the initial user message in history so it appears in chat
      recordAndSend(agentId, {
        type: "relay",
        agentId,
        message: { type: "user", message: { role: "user", content: agent.pendingPrompt } },
      } as ServerMessage);

      agent.pendingPrompt = null;
      setAgentStatus(agentId, "thinking");
    }

    ws.on("message", (data) => {
      handleClaudeMessage(agentId, data.toString());
    });

    ws.on("close", () => {
      console.log(`[claude:${agentId} CLI disconnected]`);
      if (agent.claudeSocket === ws) {
        agent.claudeSocket = null;
        if (agent.status !== "error") {
          setAgentStatus(agentId, "done");
          sendToBrowser({ type: "cli_disconnected", agentId });

          // Auto-complete any task linked to this agent
          for (const task of tasks.values()) {
            if (task.agentId === agentId && task.status !== "done") {
              task.status = "done";
              task.updatedAt = Date.now();
              persistTasks();
              broadcastTaskList();
              break;
            }
          }
        }
      }
    });
  } else {
    console.log(`[ws] unknown path: ${path}, closing`);
    ws.close();
  }
});

// ── Graceful shutdown ─────────────────────────────────────────────────────

function shutdown() {
  console.log("[ws server] shutting down...");

  // Persist all agents synchronously before exit — do NOT kill tmux sessions
  // so CLI processes can reconnect if the server restarts.
  const allPersisted = Array.from(agents.values()).map(toPersistedAgent);
  store.flushAll(allPersisted);
  console.log(`[ws server] saved ${allPersisted.length} agents to disk (tmux sessions preserved)`);

  taskStore.flush(Array.from(tasks.values()));
  console.log(`[ws server] saved ${tasks.size} tasks to disk`);

  wss.close();
  process.exit(0);
}

process.on("SIGTERM", shutdown);
process.on("SIGINT", shutdown);

console.log(`[ws server] listening on port ${PORT}`);

"use client";

/**
 * React hook that manages the WebSocket connection to the thos relay server.
 *
 * Supports multiple concurrent agents. Each agent has its own status,
 * message history, label, and tmux session name tracked in a Map keyed
 * by agent ID. The `activeAgentId` determines which agent's chat is shown.
 *
 * ## Connection lifecycle
 *
 * 1. Connect to `ws://<host>:9900/browser`.
 * 2. Server sends `agent_list` (sidebar metadata) + `task_list`. No
 *    message histories are sent eagerly — this keeps the initial
 *    payload small for fast loading on mobile networks.
 * 3. `initialLoadDone` becomes true after `agent_list` arrives.
 * 4. No agent is auto-selected — the user stays on the new-agent
 *    creation screen until they explicitly pick or spawn an agent.
 *
 * ## Lazy history loading
 *
 * Message histories are loaded on demand. When `activeAgentId` changes
 * and the agent hasn't been loaded yet, the hook sends
 * `{ type: "request_history", agentId }` and sets `historyLoading = true`.
 * When the server responds with `message_history`, the agent's messages
 * are populated and `historyLoading` becomes false.
 *
 * The `loadedAgents` Set tracks which agents have been fetched so that
 * switching back to a previously viewed agent is instant.
 *
 * ## Resilience features
 *
 * - Handles `message_history` replay from server on demand.
 * - Handles `cli_disconnected` / `cli_connected` events.
 * - Deduplicates messages using a per-agent processed count.
 * - Robust reconnection guard (clears previous timer before scheduling).
 * - Strict mode safe (closingRef prevents spurious reconnects on unmount).
 *
 * ## Logging
 *
 * All WS events are logged with the `[thos-ws]` prefix. Filter by this
 * in the browser console to debug connection and message delivery issues.
 */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type {
  AgentInfo,
  AgentStatus,
  ChatMessage,
  ClaudeAssistant,
  ClaudeControlRequest,
  ClaudeMessage,
  ClaudeResult,
  ClaudeSystemInit,
  ServerMessage,
  ServerMessageHistory,
  ServerTaskList,
  ServerTaskUpdated,
  ServerTaskDeleted,
  Task,
  TaskPriority,
  ToolCallInfo,
  UserQuestion,
} from "@/lib/types";

/** Connect to the WS server on the same host the page was loaded from. */
const WS_URL =
  typeof window !== "undefined"
    ? `ws://${window.location.hostname}:9900/browser`
    : "ws://localhost:9900/browser";

/** Per-agent client state. */
export interface AgentClientState {
  status: AgentStatus;
  messages: ChatMessage[];
  /** Raw Claude NDJSON messages for debug view. */
  rawMessages: ClaudeMessage[];
  label: string;
  tmuxSession: string | null;
  createdAt: number;
}

/**
 * Extract displayable text from a Claude assistant message.
 * Content blocks may be text, tool_use, or tool_result — each is
 * handled defensively since the array structure can vary.
 */
function extractText(msg: ClaudeAssistant): string {
  const blocks = msg.message?.content;
  if (!blocks || !Array.isArray(blocks)) return "";
  return blocks
    .map((b) => {
      if (b.type === "text") return b.text;
      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
      if (b.type === "tool_result") {
        const c = (b as { content?: unknown }).content;
        return `[tool_result: ${typeof c === "string" ? c : JSON.stringify(c)}]`;
      }
      return "";
    })
    .filter(Boolean)
    .join("\n");
}

/** Module-level counter for generating unique message IDs. */
let msgCounter = 0;
function nextId() {
  return `msg-${Date.now()}-${++msgCounter}`;
}

/**
 * Extract a stable dedup key from a relay message, if present.
 *
 * Claude NDJSON sends cumulative snapshots for two message types:
 * - `assistant` — keyed by `message.id` (e.g. `msg_01VE1P7c...`)
 * - `user` (tool_result) — keyed by top-level `uuid` (e.g. `b217b852-...`)
 *
 * Returns the key or null for non-deduplicable messages.
 */
function getRelayDedupKey(relayMsg: ServerMessage): string | null {
  if (relayMsg.type !== "relay") return null;
  const inner = relayMsg.message;
  if (inner.type === "assistant") {
    return (inner as { message?: { id?: string } }).message?.id ?? null;
  }
  if (inner.type === "user") {
    return (inner as { uuid?: string }).uuid ?? null;
  }
  return null;
}

/**
 * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
 * Used both for live messages and for replaying message_history.
 *
 * When a relay message has a stable dedup key (assistant message.id or user uuid),
 * that key is used as the ChatMessage `id` so that cumulative snapshots produce
 * ChatMessages with the same identity — enabling in-place replacement.
 */
function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
  if (relayMsg.type === "relay") {
    const msg = relayMsg.message;
    const dedupKey = getRelayDedupKey(relayMsg);

    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
      const init = msg as ClaudeSystemInit;
      return {
        id: `dedup-init-${init.session_id}`,
        role: "system",
        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
        timestamp: Date.now(),
      };
    }

    if (msg.type === "user") {
      const rawContent = (msg as { message?: { content?: unknown } }).message?.content ?? "";
      // Only render human-typed user messages (string content).
      // CLI tool_result messages have array content — these are internal
      // protocol messages and are only visible in the raw message viewer.
      if (typeof rawContent !== "string") return null;
      if (!rawContent.trim()) return null;
      return {
        id: dedupKey ? `dedup-${dedupKey}` : nextId(),
        role: "user",
        content: rawContent,
        timestamp: Date.now(),
      };
    }

    if (msg.type === "assistant") {
      const assistant = msg as ClaudeAssistant;
      const text = extractText(assistant);
      if (!text) return null;

      const blocks = assistant.message?.content ?? [];
      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());

      // Build a map of tool_use_id → truncated result content
      const resultMap = new Map<string, string>();
      for (const b of blocks) {
        if (b.type === "tool_result" && b.tool_use_id) {
          const raw = b.content;
          const text = typeof raw === "string" ? raw : JSON.stringify(raw);
          // First line, truncated to 120 chars
          const firstLine = text.split("\n")[0];
          resultMap.set(b.tool_use_id, firstLine.length > 120 ? firstLine.slice(0, 120) + "..." : firstLine);
        }
      }

      const toolCalls: ToolCallInfo[] = blocks
        .filter((b) => b.type === "tool_use")
        .map((b) => ({
          name: (b as { name: string }).name,
          toolUseId: (b as { id: string }).id,
          resultPreview: resultMap.get((b as { id: string }).id),
        }));
      const isToolOnly = !hasText && toolCalls.length > 0;

      return {
        id: dedupKey ? `dedup-${dedupKey}` : nextId(),
        role: "assistant",
        content: text,
        timestamp: Date.now(),
        toolCalls,
        isToolOnly,
      };
    }

    if (msg.type === "result") {
      const result = msg as ClaudeResult;
      const cost = result.total_cost_usd ?? result.cost_usd ?? 0;
      const summary = result.is_error
        ? `Error: ${result.error}`
        : `Done — ${result.num_turns ?? "?"} turns, $${cost.toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
      return {
        id: nextId(),
        role: "system",
        content: summary,
        timestamp: Date.now(),
      };
    }

    if (msg.type === "control_request") {
      const cr = msg as ClaudeControlRequest;

      // AskUserQuestion gets its own UI instead of generic Allow/Deny
      if (cr.request.tool_name === "AskUserQuestion") {
        const input = cr.request.input as { questions?: UserQuestion[] };
        const questions = Array.isArray(input.questions) ? input.questions : [];
        return {
          id: nextId(),
          role: "system",
          content: "Question from Claude",
          timestamp: Date.now(),
          userQuestion: {
            requestId: cr.request_id,
            questions,
          },
        };
      }

      return {
        id: nextId(),
        role: "system",
        content: `Tool approval requested: ${cr.request.tool_name}`,
        timestamp: Date.now(),
        controlRequest: {
          id: cr.request_id,
          tool_name: cr.request.tool_name,
          input: cr.request.input,
          description: cr.request.description,
        },
      };
    }
  }

  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
    return {
      id: nextId(),
      role: "system",
      content: `Error: ${relayMsg.error}`,
      timestamp: Date.now(),
    };
  }

  return null;
}

/**
 * Find the index of an existing raw message that should be replaced by this relay.
 * Searches from the end for speed (cumulative snapshots arrive sequentially).
 */
function findLastRawIndex(rawMessages: ClaudeMessage[], relay: ServerMessage): number {
  if (relay.type !== "relay") return -1;
  const inner = relay.message;
  if (inner.type === "assistant") {
    const id = (inner as { message?: { id?: string } }).message?.id;
    if (!id) return -1;
    for (let i = rawMessages.length - 1; i >= 0; i--) {
      const r = rawMessages[i];
      if (r.type === "assistant" && (r as { message?: { id?: string } }).message?.id === id) return i;
    }
  }
  if (inner.type === "user") {
    const uuid = (inner as { uuid?: string }).uuid;
    if (!uuid) return -1;
    for (let i = rawMessages.length - 1; i >= 0; i--) {
      const r = rawMessages[i];
      if (r.type === "user" && (r as { uuid?: string }).uuid === uuid) return i;
    }
  }
  return -1;
}

/** Console logger with [thos] prefix for easy filtering. */
function log(...args: unknown[]) {
  console.log("[thos-ws]", ...args);
}

export function useWebSocket() {
  const wsRef = useRef<WebSocket | null>(null);
  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
  const closingRef = useRef(false);
  const [connected, setConnected] = useState(false);
  /** True once we've received the initial agent_list from the server. */
  const [initialLoadDone, setInitialLoadDone] = useState(false);

  // Multi-agent state
  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
  const [agentOrder, setAgentOrder] = useState<string[]>([]);
  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);

  // Task state
  const [tasks, setTasks] = useState<Task[]>([]);

  // Per-agent deduplication: track count of processed messages per agent
  // to avoid duplicating messages already in local state during history replay.
  const processedCountRef = useRef<Map<string, number>>(new Map());

  // Track which agents have had their history loaded (lazy loading).
  const [loadedAgents, setLoadedAgents] = useState<Set<string>>(new Set());

  /** Immutably update a single agent's state in the Map. */
  const updateAgent = useCallback(
    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
      setAgents((prev) => {
        const existing = prev.get(agentId);
        if (!existing) return prev;
        const next = new Map(prev);
        next.set(agentId, updater(existing));
        return next;
      });
    },
    []
  );

  const connect = useCallback(() => {
    if (wsRef.current?.readyState === WebSocket.OPEN) return;
    if (wsRef.current) {
      wsRef.current.close();
      wsRef.current = null;
    }

    // Reset dedup counts on new connection — server will send fresh history
    processedCountRef.current.clear();
    setInitialLoadDone(false);
    setLoadedAgents(new Set());

    log("connecting to", WS_URL);
    const ws = new WebSocket(WS_URL);
    wsRef.current = ws;

    ws.onopen = () => {
      log("connected");
      setConnected(true);
    };

    ws.onclose = () => {
      log("disconnected, closingRef =", closingRef.current);
      setConnected(false);
      wsRef.current = null;
      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
      if (closingRef.current) return;
      // Reconnection guard: clear any existing timer before scheduling
      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
      log("scheduling reconnect in 2s");
      reconnectTimer.current = setTimeout(() => connect(), 2000);
    };

    ws.onerror = (e) => {
      log("error", e);
      // onclose will fire after onerror, which triggers reconnect
    };

    ws.onmessage = (event) => {
      let data: ServerMessage;
      try {
        data = JSON.parse(event.data as string);
      } catch {
        return;
      }

      log("←", data.type, "agentId" in data ? (data as { agentId: string }).agentId : "");

      // ── task_list: full task list from server ──
      if (data.type === "task_list") {
        log("task_list:", (data as ServerTaskList).tasks.length, "tasks");
        setTasks((data as ServerTaskList).tasks);
        return;
      }

      // ── task_updated: single task changed ──
      if (data.type === "task_updated") {
        const updated = (data as ServerTaskUpdated).task;
        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
        return;
      }

      // ── task_deleted: remove task ──
      if (data.type === "task_deleted") {
        const deletedId = (data as ServerTaskDeleted).taskId;
        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
        return;
      }

      // ── message_history: replay full history from server ──
      if (data.type === "message_history") {
        const historyMsg = data as ServerMessageHistory;
        const agentId = historyMsg.agentId;
        const serverMessages = historyMsg.messages;
        log("message_history:", agentId, serverMessages.length, "raw msgs");

        // Convert all server messages to ChatMessages + extract raw Claude messages
        const chatMessages: ChatMessage[] = [];
        const rawMessages: ClaudeMessage[] = [];
        for (const sm of serverMessages) {
          if (sm.type === "relay") {
            rawMessages.push(sm.message);
          }
          const cm = relayChatMessage(agentId, sm);
          if (cm) chatMessages.push(cm);
        }
        log("message_history:", agentId, "→", chatMessages.length, "chat msgs,", rawMessages.length, "raw");

        // Always replace local messages with server history (source of truth).
        setAgents((prev) => {
          const existing = prev.get(agentId);
          if (!existing) {
            log("message_history:", agentId, "agent not in map yet, creating");
            const next = new Map(prev);
            next.set(agentId, {
              status: "idle",
              messages: chatMessages,
              rawMessages,
              label: "",
              tmuxSession: null,
              createdAt: 0,
            });
            return next;
          }
          const next = new Map(prev);
          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
          return next;
        });

        processedCountRef.current.set(agentId, chatMessages.length);
        setLoadedAgents((prev) => {
          if (prev.has(agentId)) return prev;
          const next = new Set(prev);
          next.add(agentId);
          return next;
        });
        return;
      }

      // ── history_cleared: wipe local messages for this agent ──
      if (data.type === "history_cleared") {
        updateAgent(data.agentId, (prev) => ({
          ...prev,
          messages: [],
          rawMessages: [],
        }));
        processedCountRef.current.set(data.agentId, 0);
        return;
      }

      // ── cli_disconnected: show system message ──
      if (data.type === "cli_disconnected") {
        updateAgent(data.agentId, (prev) => ({
          ...prev,
          messages: [
            ...prev.messages,
            {
              id: nextId(),
              role: "system",
              content: "CLI session ended",
              timestamp: Date.now(),
            },
          ],
        }));
        return;
      }

      // ── cli_connected: show system message ──
      if (data.type === "cli_connected") {
        updateAgent(data.agentId, (prev) => {
          const isReconnect = prev.messages.length > 0;
          return {
            ...prev,
            messages: [
              ...prev.messages,
              {
                id: nextId(),
                role: "system",
                content: isReconnect ? "CLI reconnected" : "CLI connected",
                timestamp: Date.now(),
              },
            ],
          };
        });
        return;
      }

      // ── agent_list: reconcile sidebar state from server ──
      if (data.type === "agent_list") {
        const serverAgents = data.agents as AgentInfo[];
        log("agent_list:", serverAgents.length, "agents:", serverAgents.map((a) => `${a.agentId}(${a.status})`).join(", "));
        setAgents((prev) => {
          const next = new Map(prev);
          const serverIds = new Set(serverAgents.map((a) => a.agentId));

          // Update or add agents from server
          for (const info of serverAgents) {
            const existing = next.get(info.agentId);
            if (existing) {
              next.set(info.agentId, {
                ...existing,
                status: info.status,
                tmuxSession: info.tmuxSession,
                label: info.label,
              });
            } else {
              next.set(info.agentId, {
                status: info.status,
                messages: [],
                rawMessages: [],
                label: info.label,
                tmuxSession: info.tmuxSession,
                createdAt: info.createdAt,
              });
            }
          }

          // Remove agents no longer on the server
          for (const id of next.keys()) {
            if (!serverIds.has(id)) {
              next.delete(id);
            }
          }

          return next;
        });
        setAgentOrder(serverAgents.map((a) => a.agentId));
        setInitialLoadDone(true);

        // No auto-select: leave user on the new-agent creation screen
        // until they explicitly pick an agent or spawn a new one.
        return;
      }

      // ── spawned: auto-select the newly created agent ──
      if (data.type === "spawned") {
        setActiveAgentId(data.agentId);
        return;
      }

      // ── status: update a specific agent's status ──
      if (data.type === "status") {
        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
        return;
      }

      // ── error: append to agent's message list ──
      if (data.type === "error") {
        updateAgent(data.agentId, (prev) => ({
          ...prev,
          messages: [
            ...prev.messages,
            {
              id: nextId(),
              role: "system",
              content: `Error: ${data.error}`,
              timestamp: Date.now(),
            },
          ],
        }));
        // Track processed count for dedup
        processedCountRef.current.set(
          data.agentId,
          (processedCountRef.current.get(data.agentId) ?? 0) + 1
        );
        return;
      }

      // ── relay: append or replace claude message in agent's history ──
      if (data.type === "relay") {
        const agentId = data.agentId;
        const rawMsg = data.message;
        const chatMsg = relayChatMessage(agentId, data);
        const dedupKey = getRelayDedupKey(data);

        updateAgent(agentId, (prev) => {
          // Dedup raw messages: replace previous snapshot with same dedup key
          let nextRaw: ClaudeMessage[];
          if (dedupKey) {
            const existingIdx = findLastRawIndex(prev.rawMessages, data);
            if (existingIdx >= 0) {
              nextRaw = [...prev.rawMessages];
              nextRaw[existingIdx] = rawMsg;
            } else {
              nextRaw = [...prev.rawMessages, rawMsg];
            }
          } else {
            nextRaw = [...prev.rawMessages, rawMsg];
          }

          if (!chatMsg) return { ...prev, rawMessages: nextRaw };

          // Dedup chat messages: if this relay has a stable dedup key,
          // replace the existing ChatMessage with the same id instead of appending.
          let nextMessages: ChatMessage[];
          if (chatMsg.id.startsWith("dedup-")) {
            const existingIdx = prev.messages.findIndex((m) => m.id === chatMsg.id);
            if (existingIdx >= 0) {
              nextMessages = [...prev.messages];
              nextMessages[existingIdx] = chatMsg;
            } else {
              nextMessages = [...prev.messages, chatMsg];
            }
          } else {
            nextMessages = [...prev.messages, chatMsg];
          }

          return { ...prev, rawMessages: nextRaw, messages: nextMessages };
        });
        if (chatMsg) {
          // Track processed count for dedup
          processedCountRef.current.set(
            agentId,
            (processedCountRef.current.get(agentId) ?? 0) + 1
          );
        }
        return;
      }
    };
  }, [updateAgent]);

  useEffect(() => {
    closingRef.current = false;
    connect();
    return () => {
      closingRef.current = true;
      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
      wsRef.current?.close();
    };
  }, [connect]);

  const send = useCallback((data: object) => {
    if (wsRef.current?.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify(data));
    }
  }, []);

  // Request history for the active agent if not already loaded.
  useEffect(() => {
    if (!activeAgentId || loadedAgents.has(activeAgentId)) return;
    log("requesting history for", activeAgentId);
    send({ type: "request_history", agentId: activeAgentId });
  }, [activeAgentId, loadedAgents, send]);

  const spawnAgent = useCallback(
    (prompt: string) => {
      send({ type: "spawn", prompt });
    },
    [send]
  );

  const sendMessage = useCallback(
    (content: string) => {
      if (!activeAgentId) return;
      // Optimistically add user message to local state
      updateAgent(activeAgentId, (prev) => ({
        ...prev,
        messages: [
          ...prev.messages,
          {
            id: nextId(),
            role: "user",
            content,
            timestamp: Date.now(),
          },
        ],
      }));
      send({ type: "send_message", agentId: activeAgentId, content });
    },
    [send, activeAgentId, updateAgent]
  );

  const respondToControl = useCallback(
    (requestId: string, allow: boolean) => {
      if (!activeAgentId) return;
      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
      updateAgent(activeAgentId, (prev) => ({
        ...prev,
        messages: prev.messages.map((m) =>
          m.controlRequest?.id === requestId
            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true } }
            : m
        ),
      }));
    },
    [send, activeAgentId, updateAgent]
  );

  /** Respond to an AskUserQuestion control request with the user's selections. */
  const respondToUserQuestion = useCallback(
    (requestId: string, answers: Record<string, string>) => {
      if (!activeAgentId) return;
      send({
        type: "control_response",
        agentId: activeAgentId,
        request_id: requestId,
        allow: true,
        answers,
      });
      updateAgent(activeAgentId, (prev) => ({
        ...prev,
        messages: prev.messages.map((m) =>
          m.userQuestion?.requestId === requestId
            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
            : m
        ),
      }));
    },
    [send, activeAgentId, updateAgent]
  );

  // ── Agent management actions ──────────────────────────────────────────────

  const killAgent = useCallback(
    (agentId: string) => {
      send({ type: "kill_agent", agentId });
    },
    [send]
  );

  const deleteAgent = useCallback(
    (agentId: string) => {
      send({ type: "delete_agent", agentId });
      // Deselect if we just deleted the active agent
      setActiveAgentId((prev) => (prev === agentId ? null : prev));
    },
    [send]
  );

  const renameAgent = useCallback(
    (agentId: string, label: string) => {
      send({ type: "rename_agent", agentId, label });
    },
    [send]
  );

  const clearHistory = useCallback(
    (agentId: string) => {
      send({ type: "clear_history", agentId });
    },
    [send]
  );

  // ── Task actions ──────────────────────────────────────────────────────────

  const createTask = useCallback(
    (title: string, description: string, priority: TaskPriority) => {
      send({ type: "create_task", title, description, priority });
    },
    [send]
  );

  const updateTask = useCallback(
    (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => {
      send({ type: "update_task", taskId, updates });
    },
    [send]
  );

  const deleteTask = useCallback(
    (taskId: string) => {
      send({ type: "delete_task", taskId });
    },
    [send]
  );

  const delegateTask = useCallback(
    (taskId: string) => {
      send({ type: "delegate_task", taskId });
    },
    [send]
  );

  // Derived values for the active agent
  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
  const activeStatus = useMemo<AgentStatus>(
    () => activeAgent?.status ?? "idle",
    [activeAgent?.status]
  );
  const activeMessages = useMemo<ChatMessage[]>(
    () => activeAgent?.messages ?? [],
    [activeAgent?.messages]
  );
  const activeRawMessages = useMemo<ClaudeMessage[]>(
    () => activeAgent?.rawMessages ?? [],
    [activeAgent?.rawMessages]
  );
  const historyLoading = activeAgentId !== null && !loadedAgents.has(activeAgentId);

  return {
    connected,
    initialLoadDone,
    historyLoading,
    agents,
    agentOrder,
    activeAgentId,
    setActiveAgentId,
    activeStatus,
    activeMessages,
    activeRawMessages,
    spawnAgent,
    sendMessage,
    respondToControl,
    respondToUserQuestion,
    killAgent,
    deleteAgent,
    renameAgent,
    clearHistory,
    tasks,
    createTask,
    updateTask,
    deleteTask,
    delegateTask,
  };
}

