  1→/**
  2→ * Shared type definitions for the thos dashboard.
  3→ *
  4→ * Three categories:
  5→ * 1. **Claude NDJSON protocol** — messages the Claude CLI sends over its
  6→ *    `--sdk-url` WebSocket connection (CLI → WS server).
  7→ * 2. **Browser ↔ Server** — messages exchanged between the React client
  8→ *    and the standalone WS relay server.
  9→ * 3. **UI state** — view-model types consumed by React components.
 10→ *
 11→ * ## Key architecture notes
 12→ *
 13→ * - On browser connect, the server sends `agent_list` + `task_list` only.
 14→ * - Message histories are loaded lazily: the browser sends
 15→ *   `request_history` when selecting an agent, and the server responds
 16→ *   with `message_history` for that single agent.
 17→ * - Live messages for active agents are broadcast via `relay` in real time.
 18→ * - See `server/ws.ts` and `hooks/use-websocket.ts` for implementation.
 19→ */
 20→
 21→// ── Claude NDJSON protocol messages (CLI → server) ────────────────────────
 22→
 23→/**
 24→ * Sent once after the first user prompt is received. Contains session
 25→ * metadata like the model name, working directory, and available tools.
 26→ */
 27→export interface ClaudeSystemInit {
 28→  type: "system";
 29→  subtype: "init";
 30→  session_id: string;
 31→  tools: unknown[];
 32→  mcp_servers: unknown[];
 33→  model: string;
 34→  cwd: string;
 35→}
 36→
 37→/**
 38→ * An assistant turn. `message.content` is an array of content blocks
 39→ * (text, tool_use, tool_result) that may arrive incrementally — each
 40→ * NDJSON line is a complete snapshot of the message so far.
 41→ */
 42→export interface ClaudeAssistant {
 43→  type: "assistant";
 44→  message: {
 45→    id: string;
 46→    role: "assistant";
 47→    content: AssistantContentBlock[];
 48→    model: string;
 49→    stop_reason: string | null;
 50→  };
 51→  session_id: string;
 52→}
 53→
 54→/** A single content block inside an assistant message. */
 55→export type AssistantContentBlock =
 56→  | { type: "text"; text: string }
 57→  | { type: "tool_use"; id: string; name: string; input: Record<string, unknown> }
 58→  | { type: "tool_result"; tool_use_id: string; content: string };
 59→
 60→/**
 61→ * Terminal message for a session. Includes cost/duration metrics.
 62→ * `is_error` is true when `subtype` is `"error"`.
 63→ */
 64→export interface ClaudeResult {
 65→  type: "result";
 66→  subtype: "success" | "error";
 67→  result?: string;
 68→  error?: string;
 69→  session_id: string;
 70→  cost_usd: number;
 71→  duration_ms: number;
 72→  duration_api_ms: number;
 73→  is_error: boolean;
 74→  num_turns: number;
 75→}
 76→
 77→/**
 78→ * Claude is requesting permission to execute a tool. The dashboard must
 79→ * reply with a `control_response` (allow / deny) before the CLI proceeds.
 80→ *
 81→ * Wire format uses a nested `request` object with `request_id` at the
 82→ * top level for correlation (matches Companion protocol docs).
 83→ */
 84→export interface ClaudeControlRequest {
 85→  type: "control_request";
 86→  request_id: string;
 87→  request: {
 88→    subtype: "can_use_tool";
 89→    tool_name: string;
 90→    input: Record<string, unknown>;
 91→    tool_use_id?: string;
 92→    description?: string;
 93→  };
 94→  session_id?: string;
 95→}
 96→
 97→/**
 98→ * Hook lifecycle events emitted during CLI startup. `hook_response` is
 99→ * the signal that the CLI is ready to receive the first user prompt.
100→ */
101→export interface ClaudeSystemHook {
102→  type: "system";
103→  subtype: "hook_started" | "hook_response";
104→  session_id?: string;
105→}
106→
107→/** Discriminated union of all known Claude NDJSON message shapes. */
108→export type ClaudeMessage =
109→  | ClaudeSystemInit
110→  | ClaudeAssistant
111→  | ClaudeResult
112→  | ClaudeControlRequest
113→  | ClaudeSystemHook
114→  | { type: string; subtype?: string; [key: string]: unknown };
115→
116→// ── Browser ↔ Server messages ─────────────────────────────────────────────
117→
118→/** Browser asks the server to spawn a new Claude CLI process. */
119→export interface BrowserSpawn {
120→  type: "spawn";
121→  prompt: string;
122→}
123→
124→/** Browser sends a follow-up message to an already-running Claude session. */
125→export interface BrowserSendMessage {
126→  type: "send_message";
127→  agentId: string;
128→  content: string;
129→}
130→
131→/** Browser responds to a tool approval request (allow or deny). */
132→export interface BrowserControlResponse {
133→  type: "control_response";
134→  agentId: string;
135→  request_id: string;
136→  allow: boolean;
137→}
138→
139→/** Browser asks the server to kill a running agent's tmux session + CLI. */
140→export interface BrowserKillAgent {
141→  type: "kill_agent";
142→  agentId: string;
143→}
144→
145→/** Browser asks the server to permanently delete an agent. */
146→export interface BrowserDeleteAgent {
147→  type: "delete_agent";
148→  agentId: string;
149→}
150→
151→/** Browser asks the server to rename an agent. */
152→export interface BrowserRenameAgent {
153→  type: "rename_agent";
154→  agentId: string;
155→  label: string;
156→}
157→
158→/** Browser asks the server to clear an agent's message history. */
159→export interface BrowserClearHistory {
160→  type: "clear_history";
161→  agentId: string;
162→}
163→
164→/** Browser requests message history for a specific agent (lazy loading). */
165→export interface BrowserRequestHistory {
166→  type: "request_history";
167→  agentId: string;
168→}
169→
170→/** Browser asks the server to create a new task. */
171→export interface BrowserCreateTask {
172→  type: "create_task";
173→  title: string;
174→  description: string;
175→  priority: TaskPriority;
176→}
177→
178→/** Browser asks to update a task's fields. */
179→export interface BrowserUpdateTask {
180→  type: "update_task";
181→  taskId: string;
182→  updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>;
183→}
184→
185→/** Browser asks to delete a task. */
186→export interface BrowserDeleteTask {
187→  type: "delete_task";
188→  taskId: string;
189→}
190→
191→/** Browser asks to delegate a task to a new Claude agent. */
192→export interface BrowserDelegateTask {
193→  type: "delegate_task";
194→  taskId: string;
195→}
196→
197→/** Union of all messages the browser can send to the WS server. */
198→export type BrowserMessage =
199→  | BrowserSpawn
200→  | BrowserSendMessage
201→  | BrowserControlResponse
202→  | BrowserKillAgent
203→  | BrowserDeleteAgent
204→  | BrowserRenameAgent
205→  | BrowserClearHistory
206→  | BrowserRequestHistory
207→  | BrowserCreateTask
208→  | BrowserUpdateTask
209→  | BrowserDeleteTask
210→  | BrowserDelegateTask;
211→
212→/** Server relays a raw Claude NDJSON message to the browser. */
213→export interface ServerRelay {
214→  type: "relay";
215→  agentId: string;
216→  message: ClaudeMessage;
217→}
218→
219→/** Server notifies the browser of an agent status change. */
220→export interface ServerStatus {
221→  type: "status";
222→  agentId: string;
223→  status: AgentStatus;
224→}
225→
226→/** Server reports an error (e.g. no active session, process crash). */
227→export interface ServerError {
228→  type: "error";
229→  agentId: string;
230→  error: string;
231→}
232→
233→/** Summary of an agent for the sidebar. */
234→export interface AgentInfo {
235→  agentId: string;
236→  status: AgentStatus;
237→  tmuxSession: string | null;
238→  label: string;
239→  createdAt: number;
240→}
241→
242→/** Server sends the full list of agents after every state change. */
243→export interface ServerAgentList {
244→  type: "agent_list";
245→  agents: AgentInfo[];
246→}
247→
248→/** Server confirms a new agent was spawned and assigns its ID. */
249→export interface ServerSpawned {
250→  type: "spawned";
251→  agentId: string;
252→}
253→
254→/** Server sends full message history for an agent (in response to `request_history`). */
255→export interface ServerMessageHistory {
256→  type: "message_history";
257→  agentId: string;
258→  messages: ServerMessage[];
259→}
260→
261→/** CLI WebSocket disconnected (process may have crashed or exited). */
262→export interface ServerCliDisconnected {
263→  type: "cli_disconnected";
264→  agentId: string;
265→}
266→
267→/** CLI WebSocket reconnected (e.g. after relaunch with --resume). */
268→export interface ServerCliConnected {
269→  type: "cli_connected";
270→  agentId: string;
271→}
272→
273→/** Server confirms message history was cleared for an agent. */
274→export interface ServerHistoryCleared {
275→  type: "history_cleared";
276→  agentId: string;
277→}
278→
279→/** Server sends the full task list to the browser. */
280→export interface ServerTaskList {
281→  type: "task_list";
282→  tasks: Task[];
283→}
284→
285→/** Server confirms a task was updated. */
286→export interface ServerTaskUpdated {
287→  type: "task_updated";
288→  task: Task;
289→}
290→
291→/** Server confirms a task was deleted. */
292→export interface ServerTaskDeleted {
293→  type: "task_deleted";
294→  taskId: string;
295→}
296→
297→/** Union of all messages the WS server can send to the browser. */
298→export type ServerMessage =
299→  | ServerRelay
300→  | ServerStatus
301→  | ServerError
302→  | ServerAgentList
303→  | ServerSpawned
304→  | ServerMessageHistory
305→  | ServerCliDisconnected
306→  | ServerCliConnected
307→  | ServerHistoryCleared
308→  | ServerTaskList
309→  | ServerTaskUpdated
310→  | ServerTaskDeleted;
311→
312→// ── UI state ──────────────────────────────────────────────────────────────
313→
314→/**
315→ * Lifecycle states of the Claude agent process:
316→ * - `idle`      — no process running, ready to spawn
317→ * - `spawning`  — process launched, waiting for CLI to connect via WS
318→ * - `connected` — CLI connected and `system/init` received
319→ * - `thinking`  — waiting for assistant response
320→ * - `done`      — `result` message received, process finished
321→ * - `error`     — process crashed or unexpected failure
322→ */
323→export type AgentStatus = "idle" | "spawning" | "connected" | "thinking" | "done" | "disconnected" | "error";
324→
325→export type ChatMessageRole = "user" | "assistant" | "system";
326→
327→/**
328→ * A single entry in the chat message list. System messages include
329→ * session init info and result summaries. Messages with a `controlRequest`
330→ * are rendered as tool-approval cards instead of plain bubbles.
331→ */
332→/** A single option in an AskUserQuestion question. */
333→export interface UserQuestionOption {
334→  label: string;
335→  description?: string;
336→}
337→
338→/** A single question from AskUserQuestion. */
339→export interface UserQuestion {
340→  question: string;
341→  header?: string;
342→  options: UserQuestionOption[];
343→  multiSelect: boolean;
344→}
345→
346→/** Info about a single tool_use block in an assistant message. */
347→export interface ToolCallInfo {
348→  name: string;
349→  toolUseId?: string;
350→}
351→
352→export interface ChatMessage {
353→  id: string;
354→  role: ChatMessageRole;
355→  content: string;
356→  timestamp: number;
357→  /** Present when this message represents a tool approval request. */
358→  controlRequest?: {
359→    id: string;
360→    tool_name: string;
361→    input: Record<string, unknown>;
362→    /** Set to true after the user allows or denies. */
363→    resolved?: boolean;
364→  };
365→  /** Present when this message is an AskUserQuestion control request. */
366→  userQuestion?: {
367→    requestId: string;
368→    questions: UserQuestion[];
369→    resolved?: boolean;
370→  };
371→  /** Tool calls found in this assistant message. */
372→  toolCalls?: ToolCallInfo[];
373→  /** True when this message has only tool_use/tool_result blocks and no text. */
374→  isToolOnly?: boolean;
375→}
376→
377→// ── Task system ──────────────────────────────────────────────────────────
378→
379→export type TaskStatus = "todo" | "in-progress" | "done";
380→export type TaskPriority = "low" | "medium" | "high" | "urgent";
381→
382→/** A user-created task, optionally linked to a Claude agent. */
383→export interface Task {
384→  id: string;
385→  title: string;
386→  description: string;
387→  status: TaskStatus;
388→  priority: TaskPriority;
389→  /** If delegated, the agentId of the spawned Claude agent. */
390→  agentId: string | null;
391→  createdAt: number;
392→  updatedAt: number;
393→}
394→

  1→/**
  2→ * Standalone WebSocket relay server for the thos dashboard.
  3→ *
  4→ * Runs on port 9900 alongside Next.js (started via `concurrently` in the
  5→ * `dev` script). It cannot be a Next.js API route because API routes don't
  6→ * support persistent WebSocket connections.
  7→ *
  8→ * ## Architecture
  9→ *
 10→ * Two WebSocket path families:
 11→ * - `/browser`          — the React dashboard connects here (supports multiple tabs).
 12→ * - `/claude/:agentId`  — each Claude CLI connects here (passed as `--sdk-url`).
 13→ *
 14→ * The server supports multiple concurrent agents, each tracked in the
 15→ * `agents` Map keyed by a short random ID.
 16→ *
 17→ * ## Connection flow (browser)
 18→ *
 19→ * On browser connect, the server sends two small messages:
 20→ * 1. `agent_list`  — metadata for all agents (sidebar).
 21→ * 2. `task_list`   — all tasks.
 22→ *
 23→ * Message histories are NOT sent eagerly. They are loaded lazily: the
 24→ * browser sends `{ type: "request_history", agentId }` when the user
 25→ * selects an agent, and the server responds with `message_history` for
 26→ * that single agent. This avoids sending megabytes of JSON on connect,
 27→ * which caused multi-minute loading times on mobile networks.
 28→ *
 29→ * Live messages for active agents are still broadcast to all browsers
 30→ * via `relay` messages in real time.
 31→ *
 32→ * ## Message flow (spawning)
 33→ *
 34→ * 1. Browser sends `{ type: "spawn", prompt }`.
 35→ * 2. Server creates agent entry, spawns `claude --sdk-url ws://localhost:9900/claude/<agentId>`.
 36→ * 3. CLI connects on `/claude/<agentId>`, sends `system/hook_started` then `system/hook_response`.
 37→ * 4. On `hook_response`, server forwards the pending prompt to the CLI.
 38→ * 5. CLI sends `system/init`, then `assistant` messages, then `result`.
 39→ * 6. All CLI messages are relayed to the browser as `{ type: "relay", agentId, message }`.
 40→ * 7. `control_request` messages (tool approval) are relayed to the browser;
 41→ *    the browser's `control_response` (with `agentId`) is forwarded back to the right CLI.
 42→ *
 43→ * ## Resilience features
 44→ *
 45→ * - **Server-side message history** — every relay message is stored per-agent.
 46→ * - **File persistence** — agent state + history persisted to disk, survives restarts.
 47→ * - **Multi-browser** — multiple tabs can connect simultaneously.
 48→ * - **tmux survival** — tmux sessions are NOT killed on server restart; CLI processes
 49→ *   can reconnect to the new server if they retry their WebSocket connection.
 50→ * - **Message queuing** — messages sent while CLI is disconnected are queued and flushed on reconnect.
 51→ * - **Disconnect notifications** — browser is notified of CLI disconnect/reconnect.
 52→ * - **Lazy history** — message histories loaded on demand per agent, not on connect.
 53→ */
 54→import { WebSocketServer, WebSocket } from "ws";
 55→import { execSync, spawn } from "child_process";
 56→import { randomBytes } from "crypto";
 57→import type { IncomingMessage } from "http";
 58→import type {
 59→  BrowserMessage,
 60→  ClaudeMessage,
 61→  ServerMessage,
 62→  AgentStatus,
 63→  AgentInfo,
 64→  Task,
 65→} from "../lib/types";
 66→import { SessionStore, type PersistedAgent } from "./session-store";
 67→import { TaskStore } from "./task-store";
 68→
 69→const PORT = 9900;
 70→const TMUX_SESSION_PREFIX = "thos-agent";
 71→
 72→/** Check if an IP is localhost or in the Tailscale CGNAT range (100.64.0.0/10). */
 73→function isAllowedIP(ip: string | undefined): boolean {
 74→  if (!ip) return false;
 75→  // Strip IPv6-mapped IPv4 prefix
 76→  const addr = ip.startsWith("::ffff:") ? ip.slice(7) : ip;
 77→  if (addr === "127.0.0.1" || addr === "::1" || addr === "localhost") return true;
 78→  // Tailscale CGNAT: 100.64.0.0/10 → 100.64.0.0 – 100.127.255.255
 79→  const parts = addr.split(".");
 80→  if (parts.length !== 4) return false;
 81→  const first = parseInt(parts[0], 10);
 82→  const second = parseInt(parts[1], 10);
 83→  return first === 100 && second >= 64 && second <= 127;
 84→}
 85→
 86→const wss = new WebSocketServer({
 87→  port: PORT,
 88→  verifyClient: (info) => {
 89→    const ip = info.req.socket.remoteAddress;
 90→    const allowed = isAllowedIP(ip);
 91→    if (!allowed) console.log(`[ws] rejected connection from ${ip}`);
 92→    return allowed;
 93→  },
 94→});
 95→const store = new SessionStore();
 96→
 97→// ── Multi-agent state ──────────────────────────────────────────────────────
 98→
 99→interface AgentState {
100→  agentId: string;
101→  claudeSocket: WebSocket | null;
102→  tmuxSession: string | null;
103→  pendingPrompt: string | null;
104→  status: AgentStatus;
105→  label: string;
106→  createdAt: number;
107→  /** Captured from system/init, used in subsequent user messages. */
108→  sessionId: string | null;
109→  /** Stores control_request inputs keyed by request_id, for building control_responses. */
110→  pendingControlRequests: Map<string, Record<string, unknown>>;
111→  /** All messages sent to the browser for this agent (source of truth). */
112→  messageHistory: ServerMessage[];
113→  /** Messages queued while CLI is disconnected, flushed on reconnect. */
114→  pendingMessages: string[];
115→}
116→
117→const agents = new Map<string, AgentState>();
118→const taskStore = new TaskStore();
119→const tasks = new Map<string, Task>();
120→
121→/** All active browser connections (supports multiple tabs). */
122→const browserSockets = new Set<WebSocket>();
123→
124→/** Generate a short random agent ID. */
125→function newAgentId(): string {
126→  return randomBytes(4).toString("hex");
127→}
128→
129→// ── tmux helpers ───────────────────────────────────────────────────────────
130→
131→/** Return the set of currently alive tmux session names matching the thos prefix. */
132→function listAliveTmuxSessions(): Set<string> {
133→  try {
134→    const output = execSync("tmux list-sessions -F '#{session_name}'", {
135→      encoding: "utf-8",
136→    }).trim();
137→    if (!output) return new Set();
138→    return new Set(output.split("\n").filter((s) => s.startsWith(TMUX_SESSION_PREFIX)));
139→  } catch {
140→    return new Set();
141→  }
142→}
143→
144→// ── Persistence helpers ────────────────────────────────────────────────────
145→
146→/** Build a PersistedAgent snapshot from live state. */
147→function toPersistedAgent(agent: AgentState): PersistedAgent {
148→  return {
149→    id: agent.agentId,
150→    state: {
151→      agentId: agent.agentId,
152→      status: agent.status,
153→      tmuxSession: agent.tmuxSession,
154→      label: agent.label,
155→      createdAt: agent.createdAt,
156→      sessionId: agent.sessionId,
157→    },
158→    messageHistory: agent.messageHistory,
159→  };
160→}
161→
162→/**
163→ * Compact a message history by deduplicating cumulative snapshots.
164→ * Keeps only the last version of each assistant/user message ID.
165→ * Called on restore to shrink legacy bloated histories.
166→ */
167→function compactHistory(history: ServerMessage[]): ServerMessage[] {
168→  // Build a map of msgId → last index
169→  const lastIndex = new Map<string, number>();
170→  for (let i = 0; i < history.length; i++) {
171→    const id = getRelayMessageId(history[i]);
172→    if (id) lastIndex.set(id, i);
173→  }
174→  // Keep only messages that are either non-deduplicable or the last occurrence
175→  return history.filter((msg, i) => {
176→    const id = getRelayMessageId(msg);
177→    if (!id) return true; // non-relay or no message ID — always keep
178→    return lastIndex.get(id) === i;
179→  });
180→}
181→
182→/** Persist agent state (debounced — use for streaming events). */
183→function persistAgent(agent: AgentState) {
184→  store.save(toPersistedAgent(agent));
185→}
186→
187→/** Persist agent state immediately (use for critical state changes). */
188→function persistAgentSync(agent: AgentState) {
189→  store.saveSync(toPersistedAgent(agent));
190→}
191→
192→// ── Restore from disk on startup ───────────────────────────────────────────
193→
194→function restoreAgents() {
195→  const persisted = store.loadAll();
196→  const aliveSessions = listAliveTmuxSessions();
197→
198→  for (const p of persisted) {
199→    const agent: AgentState = {
200→      agentId: p.state.agentId,
201→      claudeSocket: null,
202→      tmuxSession: p.state.tmuxSession,
203→      pendingPrompt: null,
204→      status: p.state.status,
205→      label: p.state.label,
206→      createdAt: p.state.createdAt,
207→      sessionId: p.state.sessionId,
208→      pendingControlRequests: new Map(),
209→      messageHistory: compactHistory(p.messageHistory),
210→      pendingMessages: [],
211→    };
212→
213→    // Determine status for agents that were active when the server last ran
214→    if (agent.status !== "done" && agent.status !== "error") {
215→      const tmuxAlive = agent.tmuxSession ? aliveSessions.has(agent.tmuxSession) : false;
216→      if (tmuxAlive) {
217→        // tmux session still alive — CLI may reconnect to this server
218→        agent.status = "disconnected";
219→        console.log(`[restore] agent ${agent.agentId} — tmux alive, waiting for CLI reconnect`);
220→      } else {
221→        // tmux session gone — agent is archived
222→        agent.status = "done";
223→        console.log(`[restore] agent ${agent.agentId} — tmux dead, archived`);
224→      }
225→    }
226→
227→    agents.set(agent.agentId, agent);
228→    const originalCount = p.messageHistory.length;
229→    const compactedCount = agent.messageHistory.length;
230→    const saved = originalCount - compactedCount;
231→    console.log(`[restore] agent ${agent.agentId} (status=${agent.status}, ${compactedCount} messages${saved > 0 ? `, compacted from ${originalCount} (−${saved})` : ""})`);
232→
233→    // Persist compacted history back to disk
234→    if (saved > 0) {
235→      persistAgentSync(agent);
236→    }
237→  }
238→  console.log(`[restore] loaded ${persisted.length} agents from disk`);
239→}
240→
241→restoreAgents();
242→
243→// ── Task restore + helpers ────────────────────────────────────────────────
244→
245→function restoreTasks() {
246→  const persisted = taskStore.loadAll();
247→  for (const t of persisted) {
248→    tasks.set(t.id, t);
249→  }
250→  console.log(`[restore] loaded ${persisted.length} tasks from disk`);
251→}
252→
253→restoreTasks();
254→
255→/** Build the full task list sorted by creation time (newest first). */
256→function buildTaskList(): Task[] {
257→  return Array.from(tasks.values()).sort((a, b) => b.createdAt - a.createdAt);
258→}
259→
260→/** Send the full task list to all browsers. */
261→function broadcastTaskList() {
262→  const payload = JSON.stringify({ type: "task_list", tasks: buildTaskList() });
263→  for (const ws of browserSockets) {
264→    if (ws.readyState === WebSocket.OPEN) {
265→      ws.send(payload);
266→    }
267→  }
268→}
269→
270→/** Persist all tasks to disk (sync). */
271→function persistTasks() {
272→  taskStore.saveSync(Array.from(tasks.values()));
273→}
274→
275→// ── Helpers ────────────────────────────────────────────────────────────────
276→
277→/** Send a JSON message to all connected browsers. */
278→function sendToBrowser(msg: ServerMessage) {
279→  const payload = JSON.stringify(msg);
280→  for (const ws of browserSockets) {
281→    if (ws.readyState === WebSocket.OPEN) {
282→      ws.send(payload);
283→    }
284→  }
285→}
286→
287→/** Build a snapshot of all agents for the sidebar. */
288→function buildAgentList(): AgentInfo[] {
289→  return Array.from(agents.values()).map((a) => ({
290→    agentId: a.agentId,
291→    status: a.status,
292→    tmuxSession: a.tmuxSession,
293→    label: a.label,
294→    createdAt: a.createdAt,
295→  }));
296→}
297→
298→/** Send the full agent list to all browsers. */
299→function broadcastAgentList() {
300→  sendToBrowser({ type: "agent_list", agents: buildAgentList() });
301→}
302→
303→/** Update an agent's status, notify browsers, broadcast list, and persist. */
304→function setAgentStatus(agentId: string, status: AgentStatus) {
305→  const agent = agents.get(agentId);
306→  if (!agent) return;
307→  agent.status = status;
308→  sendToBrowser({ type: "status", agentId, status });
309→  broadcastAgentList();
310→  persistAgentSync(agent);
311→}
312→
313→/**
314→ * Extract a stable dedup key from a relay message, if present.
315→ *
316→ * Claude NDJSON sends cumulative snapshots for two message types:
317→ * - `assistant` — keyed by `message.id` (e.g. `msg_01VE1P7c...`)
318→ * - `user` (tool_result) — keyed by top-level `uuid` (e.g. `b217b852-...`)
319→ *
320→ * We deduplicate by replacing the previous snapshot in `messageHistory`
321→ * instead of appending, reducing storage from O(n²) to O(n).
322→ */
323→function getRelayMessageId(msg: ServerMessage): string | null {
324→  if (msg.type !== "relay") return null;
325→  const inner = msg.message;
326→  if (inner.type === "assistant") {
327→    return (inner as { message?: { id?: string } }).message?.id ?? null;
328→  }
329→  if (inner.type === "user") {
330→    return (inner as { uuid?: string }).uuid ?? null;
331→  }
332→  // Dedup system/init and result by session_id so they don't stack on reload
333→  if (inner.type === "system" && (inner as { subtype?: string }).subtype === "init") {
334→    const sid = (inner as { session_id?: string }).session_id;
335→    return sid ? `init:${sid}` : null;
336→  }
337→  if (inner.type === "result") {
338→    const sid = (inner as { session_id?: string }).session_id;
339→    return sid ? `result:${sid}` : null;
340→  }
341→  return null;
342→}
343→
344→/**
345→ * Record a message in the agent's history and send to all browsers.
346→ *
347→ * For cumulative snapshot messages (assistant, user/tool_result), replaces the
348→ * previous snapshot with the same message ID instead of appending. This keeps
349→ * only the final version of each message, dramatically reducing file sizes
350→ * (e.g. 38 MB → ~1 MB for a typical session).
351→ */
352→function recordAndSend(agentId: string, msg: ServerMessage) {
353→  const agent = agents.get(agentId);
354→  if (agent) {
355→    const msgId = getRelayMessageId(msg);
356→    if (msgId) {
357→      // Replace previous snapshot with same message ID (search from end for speed)
358→      let replaced = false;
359→      for (let i = agent.messageHistory.length - 1; i >= 0; i--) {
360→        if (getRelayMessageId(agent.messageHistory[i]) === msgId) {
361→          agent.messageHistory[i] = msg;
362→          replaced = true;
363→          break;
364→        }
365→      }
366→      if (!replaced) {
367→        agent.messageHistory.push(msg);
368→      }
369→    } else {
370→      agent.messageHistory.push(msg);
371→    }
372→    persistAgent(agent); // debounced — streaming messages come fast
373→  }
374→  sendToBrowser(msg);
375→}
376→
377→// ── Agent lifecycle ────────────────────────────────────────────────────────
378→
379→/**
380→ * Stop a running agent by killing its tmux session and closing the CLI socket.
381→ * The agent remains in the Map (status set to "done") so it can be viewed/deleted later.
382→ */
383→function stopAgent(agentId: string) {
384→  const agent = agents.get(agentId);
385→  if (!agent) return;
386→
387→  if (agent.tmuxSession) {
388→    try {
389→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
390→      console.log(`[tmux] killed session ${agent.tmuxSession}`);
391→    } catch {
392→      // Session may already be dead
393→    }
394→  }
395→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
396→    agent.claudeSocket.close();
397→  }
398→  agent.claudeSocket = null;
399→  setAgentStatus(agentId, "done");
400→}
401→
402→/**
403→ * Permanently delete an agent: stop it, remove from Map, remove from disk.
404→ */
405→function deleteAgent(agentId: string) {
406→  const agent = agents.get(agentId);
407→  if (!agent) return;
408→
409→  if (agent.tmuxSession) {
410→    try {
411→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
412→    } catch {}
413→  }
414→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
415→    agent.claudeSocket.close();
416→  }
417→  agents.delete(agentId);
418→  store.remove(agentId);
419→  broadcastAgentList();
420→}
421→
422→/**
423→ * Spawn a new Claude CLI process inside a tmux session.
424→ *
425→ * Creates a new agent entry, spawns the CLI with `--sdk-url` pointing to
426→ * `/claude/<agentId>`, and sends a `spawned` message to the browser.
427→ */
428→function spawnClaude(prompt: string): string {
429→  const agentId = newAgentId();
430→  const sessionName = `${TMUX_SESSION_PREFIX}-${agentId}`;
431→  const label = prompt.length > 60 ? prompt.slice(0, 57) + "..." : prompt;
432→
433→  const agent: AgentState = {
434→    agentId,
435→    claudeSocket: null,
436→    tmuxSession: null,
437→    pendingPrompt: prompt,
438→    status: "spawning",
439→    label,
440→    createdAt: Date.now(),
441→    sessionId: null,
442→    pendingControlRequests: new Map(),
443→    messageHistory: [],
444→    pendingMessages: [],
445→  };
446→  agents.set(agentId, agent);
447→
448→  // Notify browsers
449→  sendToBrowser({ type: "spawned", agentId });
450→  broadcastAgentList();
451→  persistAgentSync(agent);
452→
453→  // Build the claude command with CLAUDECODE unset to bypass nesting protection.
454→  // tmux new-session runs detached (-d) so spawn() returns immediately.
455→  const claudeCmd = `unset CLAUDECODE; exec claude --dangerously-skip-permissions --sdk-url ws://localhost:${PORT}/claude/${agentId}`;
456→
457→  const tmux = spawn("tmux", ["new-session", "-d", "-s", sessionName, "bash", "-c", claudeCmd], {
458→    stdio: "ignore",
459→  });
460→
461→  tmux.on("error", (err) => {
462→    console.error("[tmux spawn error]", err);
463→    setAgentStatus(agentId, "error");
464→    recordAndSend(agentId, { type: "error", agentId, error: `tmux error: ${err.message}` });
465→  });
466→
467→  tmux.on("exit", (code) => {
468→    if (code !== 0) {
469→      console.error(`[tmux] new-session exited with code ${code}`);
470→      setAgentStatus(agentId, "error");
471→      recordAndSend(agentId, { type: "error", agentId, error: `tmux exited with code ${code}` });
472→      return;
473→    }
474→    console.log(`[tmux] session ${sessionName} created — attach with: tmux attach -t ${sessionName}`);
475→    agent.tmuxSession = sessionName;
476→    broadcastAgentList();
477→    persistAgentSync(agent);
478→  });
479→
480→  return agentId;
481→}
482→
483→// ── Message handlers ───────────────────────────────────────────────────────
484→
485→/**
486→ * Process an incoming NDJSON message from a specific Claude CLI.
487→ *
488→ * Status flow matches the Companion protocol:
489→ * - hook_response → send pending prompt → "thinking"
490→ * - system/init   → "connected" + capture session_id
491→ * - assistant      → "thinking"
492→ * - result         → "connected" (CLI stays alive for multi-turn)
493→ * - CLI disconnect → "done" (handled in connection close handler)
494→ */
495→function handleClaudeMessage(agentId: string, raw: string) {
496→  const agent = agents.get(agentId);
497→  if (!agent) return;
498→
499→  let msg: ClaudeMessage;
500→  try {
501→    msg = JSON.parse(raw);
502→  } catch {
503→    console.error(`[claude:${agentId}] invalid JSON:`, raw);
504→    return;
505→  }
506→
507→  // Silently ignore keep_alive messages
508→  if (msg.type === "keep_alive") return;
509→
510→  console.log(`[claude:${agentId} →]`, msg.type, (msg as { subtype?: string }).subtype ?? "");
511→
512→  // After hook_response, send the pending prompt
513→  if (
514→    msg.type === "system" &&
515→    (msg as { subtype?: string }).subtype === "hook_response" &&
516→    agent.pendingPrompt &&
517→    agent.claudeSocket?.readyState === WebSocket.OPEN
518→  ) {
519→    const userMsg = JSON.stringify({
520→      type: "user",
521→      message: { role: "user", content: agent.pendingPrompt },
522→      parent_tool_use_id: null,
523→      session_id: agent.sessionId ?? "",
524→    });
525→    console.log(`[server → claude:${agentId}]`, userMsg);
526→    agent.claudeSocket.send(userMsg + "\n");
527→    agent.pendingPrompt = null;
528→    setAgentStatus(agentId, "thinking");
529→  }
530→
531→  // Track status based on message type
532→  if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
533→    // Capture session_id for subsequent user messages
534→    agent.sessionId = (msg as { session_id?: string }).session_id ?? null;
535→    setAgentStatus(agentId, "connected");
536→  } else if (msg.type === "assistant") {
537→    setAgentStatus(agentId, "thinking");
538→  } else if (msg.type === "result") {
539→    // CLI stays alive after result — ready for the next turn.
540→    // Status only goes to "done" when the CLI WebSocket actually closes.
541→    setAgentStatus(agentId, "connected");
542→  }
543→
544→  // Store control_request inputs for building proper responses later
545→  if (msg.type === "control_request") {
546→    const cr = msg as { request_id?: string; request?: { input?: Record<string, unknown> } };
547→    if (cr.request_id && cr.request?.input) {
548→      agent.pendingControlRequests.set(cr.request_id, cr.request.input);
549→    }
550→  }
551→
552→  // Record in history and relay to browsers
553→  recordAndSend(agentId, { type: "relay", agentId, message: msg });
554→}
555→
556→/**
557→ * Process an incoming JSON message from the browser.
558→ * - `spawn`: create a new agent (does NOT kill others).
559→ * - `send_message`: forward a follow-up user message to the specified agent.
560→ * - `control_response`: forward a tool allow/deny decision to the specified agent.
561→ * - `kill_agent`: stop the CLI and tmux session.
562→ * - `delete_agent`: permanently remove an agent.
563→ * - `rename_agent`: update an agent's label.
564→ * - `clear_history`: wipe an agent's message history.
565→ * - `request_history`: send message history for a single agent (lazy loading).
566→ * - `create_task` / `update_task` / `delete_task` / `delegate_task`: task CRUD.
567→ */
568→function handleBrowserMessage(raw: string, senderWs: WebSocket) {
569→  let msg: BrowserMessage;
570→  try {
571→    msg = JSON.parse(raw);
572→  } catch {
573→    console.error("[browser] invalid JSON:", raw);
574→    return;
575→  }
576→
577→  console.log("[browser →]", msg.type);
578→
579→  switch (msg.type) {
580→    case "spawn":
581→      spawnClaude(msg.prompt);
582→      break;
583→
584→    case "send_message": {
585→      const agent = agents.get(msg.agentId);
586→      if (!agent) {
587→        sendToBrowser({ type: "error", agentId: msg.agentId, error: "Unknown agent" });
588→        break;
589→      }
590→
591→      // Record the user message in history so it persists across reloads.
592→      // Do NOT broadcast — the sending browser already has it optimistically,
593→      // and other browsers will get it when they request_history.
594→      agent.messageHistory.push({
595→        type: "relay",
596→        agentId: msg.agentId,
597→        message: { type: "user", message: { role: "user", content: msg.content } },
598→      } as ServerMessage);
599→      persistAgent(agent);
600→
601→      if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
602→        const userMsg = JSON.stringify({
603→          type: "user",
604→          message: { role: "user", content: msg.content },
605→          parent_tool_use_id: null,
606→          session_id: agent.sessionId ?? "",
607→        });
608→        agent.claudeSocket.send(userMsg + "\n");
609→        setAgentStatus(msg.agentId, "thinking");
610→      } else {
611→        // Queue message for delivery when CLI reconnects
612→        const userMsg = JSON.stringify({
613→          type: "user",
614→          message: { role: "user", content: msg.content },
615→          parent_tool_use_id: null,
616→          session_id: agent.sessionId ?? "",
617→        });
618→        agent.pendingMessages.push(userMsg);
619→        console.log(`[queue] queued message for agent ${msg.agentId} (${agent.pendingMessages.length} pending)`);
620→        persistAgentSync(agent);
621→      }
622→      break;
623→    }
624→
625→    case "control_response": {
626→      const agent = agents.get(msg.agentId);
627→      if (agent?.claudeSocket?.readyState === WebSocket.OPEN) {
628→        // Retrieve the original tool input to include as updatedInput (required by protocol)
629→        const originalInput = agent.pendingControlRequests.get(msg.request_id) ?? {};
630→        agent.pendingControlRequests.delete(msg.request_id);
631→
632→        // If the browser sent answers (from AskUserQuestion), merge them into the input
633→        const answers = (msg as { answers?: Record<string, string> }).answers;
634→        const updatedInput = answers
635→          ? { ...originalInput, answers }
636→          : originalInput;
637→
638→        const response = JSON.stringify({
639→          type: "control_response",
640→          response: {
641→            subtype: "success",
642→            request_id: msg.request_id,
643→            response: msg.allow
644→              ? { behavior: "allow", updatedInput }
645→              : { behavior: "deny", message: "Denied by user" },
646→          },
647→        });
648→        agent.claudeSocket.send(response + "\n");
649→      }
650→      break;
651→    }
652→
653→    case "kill_agent":
654→      stopAgent(msg.agentId);
655→      break;
656→
657→    case "delete_agent":
658→      deleteAgent(msg.agentId);
659→      break;
660→
661→    case "rename_agent": {
662→      const agent = agents.get(msg.agentId);
663→      if (!agent) break;
664→      agent.label = msg.label;
665→      broadcastAgentList();
666→      persistAgentSync(agent);
667→      break;
668→    }
669→
670→    case "clear_history": {
671→      const agent = agents.get(msg.agentId);
672→      if (!agent) break;
673→      agent.messageHistory = [];
674→      persistAgentSync(agent);
675→      sendToBrowser({ type: "history_cleared", agentId: msg.agentId });
676→      break;
677→    }
678→
679→    case "request_history": {
680→      console.log(`[browser] request_history for ${msg.agentId}`);
681→      sendHistoryToSocket(senderWs, msg.agentId);
682→      break;
683→    }
684→
685→    case "create_task": {
686→      const taskId = randomBytes(4).toString("hex");
687→      const task: Task = {
688→        id: taskId,
689→        title: msg.title,
690→        description: msg.description,
691→        status: "todo",
692→        priority: msg.priority,
693→        agentId: null,
694→        createdAt: Date.now(),
695→        updatedAt: Date.now(),
696→      };
697→      tasks.set(taskId, task);
698→      persistTasks();
699→      broadcastTaskList();
700→      break;
701→    }
702→
703→    case "update_task": {
704→      const task = tasks.get(msg.taskId);
705→      if (!task) break;
706→      Object.assign(task, msg.updates, { updatedAt: Date.now() });
707→      persistTasks();
708→      broadcastTaskList();
709→      break;
710→    }
711→
712→    case "delete_task": {
713→      tasks.delete(msg.taskId);
714→      persistTasks();
715→      broadcastTaskList();
716→      break;
717→    }
718→
719→    case "delegate_task": {
720→      const task = tasks.get(msg.taskId);
721→      if (!task) break;
722→      const prompt = `Task: ${task.title}\n\n${task.description}`;
723→      const agentId = spawnClaude(prompt);
724→      task.agentId = agentId;
725→      task.status = "in-progress";
726→      task.updatedAt = Date.now();
727→      persistTasks();
728→      broadcastTaskList();
729→      break;
730→    }
731→  }
732→}
733→
734→// ── Send message history to a single browser socket ────────────────────────
735→
736→/** Send initial state (agent list + tasks) to a newly connected browser. */
737→function sendFullStateToSocket(ws: WebSocket) {
738→  if (ws.readyState !== WebSocket.OPEN) return;
739→
740→  // Agent list (sidebar metadata) — message histories are loaded lazily on demand
741→  ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList() }));
742→
743→  // Task list
744→  ws.send(JSON.stringify({ type: "task_list", tasks: buildTaskList() }));
745→}
746→
747→/** Send message history for a single agent to a specific browser socket. */
748→function sendHistoryToSocket(ws: WebSocket, agentId: string) {
749→  const agent = agents.get(agentId);
750→  if (!agent || ws.readyState !== WebSocket.OPEN) return;
751→  ws.send(
752→    JSON.stringify({
753→      type: "message_history",
754→      agentId: agent.agentId,
755→      messages: agent.messageHistory,
756→    })
757→  );
758→}
759→
760→// ── Connection handler — route by URL path ────────────────────────────────
761→wss.on("connection", (ws: WebSocket, req: IncomingMessage) => {
762→  const path = req.url ?? "/";
763→  console.log(`[ws connected] path=${path}`);
764→
765→  if (path === "/browser") {
766→    // Send full state BEFORE adding to browserSockets so that live
767→    // relay broadcasts don't interleave with the history replay.
768→    sendFullStateToSocket(ws);
769→    browserSockets.add(ws);
770→
771→    ws.on("message", (data) => {
772→      handleBrowserMessage(data.toString(), ws);
773→    });
774→
775→    ws.on("close", () => {
776→      console.log("[browser disconnected]");
777→      browserSockets.delete(ws);
778→      // Do NOT kill agents — keep them alive for reconnect
779→    });
780→  } else if (path.startsWith("/claude/")) {
781→    // Parse agentId from /claude/<agentId>
782→    const agentId = path.slice("/claude/".length);
783→    const agent = agents.get(agentId);
784→
785→    if (!agent) {
786→      console.log(`[ws] unknown agentId: ${agentId}, closing`);
787→      ws.close();
788→      return;
789→    }
790→
791→    agent.claudeSocket = ws;
792→    console.log(`[claude:${agentId} CLI connected via WebSocket]`);
793→
794→    // Notify browsers that CLI is connected
795→    sendToBrowser({ type: "cli_connected", agentId });
796→
797→    // Flush any pending messages queued while CLI was disconnected
798→    if (agent.pendingMessages.length > 0) {
799→      console.log(`[flush] sending ${agent.pendingMessages.length} queued messages to agent ${agentId}`);
800→      for (const queued of agent.pendingMessages) {
801→        ws.send(queued + "\n");
802→      }
803→      agent.pendingMessages = [];
804→      persistAgentSync(agent);
805→    }
806→
807→    // Send the pending prompt immediately — CLI 2.1.42+ waits for the
808→    // server to send the first user message rather than emitting
809→    // hook_started/hook_response on connect.
810→    if (agent.pendingPrompt && ws.readyState === WebSocket.OPEN) {
811→      const userMsg = JSON.stringify({
812→        type: "user",
813→        message: { role: "user", content: agent.pendingPrompt },
814→        parent_tool_use_id: null,
815→        session_id: agent.sessionId ?? "",
816→      });
817→      console.log(`[server → claude:${agentId}] sending pending prompt`);
818→      ws.send(userMsg + "\n");
819→      agent.pendingPrompt = null;
820→      setAgentStatus(agentId, "thinking");
821→    }
822→
823→    ws.on("message", (data) => {
824→      handleClaudeMessage(agentId, data.toString());
825→    });
826→
827→    ws.on("close", () => {
828→      console.log(`[claude:${agentId} CLI disconnected]`);
829→      if (agent.claudeSocket === ws) {
830→        agent.claudeSocket = null;
831→        if (agent.status !== "error") {
832→          setAgentStatus(agentId, "done");
833→          sendToBrowser({ type: "cli_disconnected", agentId });
834→
835→          // Auto-complete any task linked to this agent
836→          for (const task of tasks.values()) {
837→            if (task.agentId === agentId && task.status !== "done") {
838→              task.status = "done";
839→              task.updatedAt = Date.now();
840→              persistTasks();
841→              broadcastTaskList();
842→              break;
843→            }
844→          }
845→        }
846→      }
847→    });
848→  } else {
849→    console.log(`[ws] unknown path: ${path}, closing`);
850→    ws.close();
851→  }
852→});
853→
854→// ── Graceful shutdown ─────────────────────────────────────────────────────
855→
856→function shutdown() {
857→  console.log("[ws server] shutting down...");
858→
859→  // Persist all agents synchronously before exit — do NOT kill tmux sessions
860→  // so CLI processes can reconnect if the server restarts.
861→  const allPersisted = Array.from(agents.values()).map(toPersistedAgent);
862→  store.flushAll(allPersisted);
863→  console.log(`[ws server] saved ${allPersisted.length} agents to disk (tmux sessions preserved)`);
864→
865→  taskStore.flush(Array.from(tasks.values()));
866→  console.log(`[ws server] saved ${tasks.size} tasks to disk`);
867→
868→  wss.close();
869→  process.exit(0);
870→}
871→
872→process.on("SIGTERM", shutdown);
873→process.on("SIGINT", shutdown);
874→
875→console.log(`[ws server] listening on port ${PORT}`);
