231→export function useWebSocket() {
232→  const wsRef = useRef<WebSocket | null>(null);
233→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
234→  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
235→  const closingRef = useRef(false);
236→  const [connected, setConnected] = useState(false);
237→  /** True once we've received the initial agent_list from the server. */
238→  const [initialLoadDone, setInitialLoadDone] = useState(false);
239→
240→  // Multi-agent state
241→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
242→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
243→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
244→
245→  // Task state
246→  const [tasks, setTasks] = useState<Task[]>([]);
247→
248→  // Per-agent deduplication: track count of processed messages per agent
249→  // to avoid duplicating messages already in local state during history replay.
250→  const processedCountRef = useRef<Map<string, number>>(new Map());
251→
252→  // Track which agents have had their history loaded (lazy loading).
253→  const [loadedAgents, setLoadedAgents] = useState<Set<string>>(new Set());
254→
255→  /** Immutably update a single agent's state in the Map. */
256→  const updateAgent = useCallback(
257→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
258→      setAgents((prev) => {
259→        const existing = prev.get(agentId);
260→        if (!existing) return prev;
261→        const next = new Map(prev);
262→        next.set(agentId, updater(existing));
263→        return next;
264→      });
265→    },
266→    []
267→  );
268→
269→  const connect = useCallback(() => {
270→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
271→    if (wsRef.current) {
272→      wsRef.current.close();
273→      wsRef.current = null;
274→    }
275→
276→    // Reset dedup counts on new connection — server will send fresh history
277→    processedCountRef.current.clear();
278→    setInitialLoadDone(false);
279→    setLoadedAgents(new Set());
280→
281→    log("connecting to", WS_URL);
282→    const ws = new WebSocket(WS_URL);
283→    wsRef.current = ws;
284→
285→    ws.onopen = () => {
286→      log("connected");
287→      setConnected(true);
288→    };
289→
290→    ws.onclose = () => {
291→      log("disconnected, closingRef =", closingRef.current);
292→      setConnected(false);
293→      wsRef.current = null;
294→      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
295→      if (closingRef.current) return;
296→      // Reconnection guard: clear any existing timer before scheduling
297→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
298→      log("scheduling reconnect in 2s");
299→      reconnectTimer.current = setTimeout(() => connect(), 2000);
300→    };
301→
302→    ws.onerror = (e) => {
303→      log("error", e);
304→      // onclose will fire after onerror, which triggers reconnect
305→    };
306→
307→    ws.onmessage = (event) => {
308→      let data: ServerMessage;
309→      try {
310→        data = JSON.parse(event.data as string);
311→      } catch {
312→        return;
313→      }
314→
315→      log("←", data.type, "agentId" in data ? (data as { agentId: string }).agentId : "");
316→
317→      // ── task_list: full task list from server ──
318→      if (data.type === "task_list") {
319→        log("task_list:", (data as ServerTaskList).tasks.length, "tasks");
320→        setTasks((data as ServerTaskList).tasks);
321→        return;
322→      }
323→
324→      // ── task_updated: single task changed ──
325→      if (data.type === "task_updated") {
326→        const updated = (data as ServerTaskUpdated).task;
327→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
328→        return;
329→      }
330→
331→      // ── task_deleted: remove task ──
332→      if (data.type === "task_deleted") {
333→        const deletedId = (data as ServerTaskDeleted).taskId;
334→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
335→        return;
336→      }
337→
338→      // ── message_history: replay full history from server ──
339→      if (data.type === "message_history") {
340→        const historyMsg = data as ServerMessageHistory;
341→        const agentId = historyMsg.agentId;
342→        const serverMessages = historyMsg.messages;
343→        log("message_history:", agentId, serverMessages.length, "raw msgs");
344→
345→        // Convert all server messages to ChatMessages + extract raw Claude messages
346→        const chatMessages: ChatMessage[] = [];
347→        const rawMessages: ClaudeMessage[] = [];
348→        for (const sm of serverMessages) {
349→          if (sm.type === "relay") {
350→            rawMessages.push(sm.message);
351→          }
352→          const cm = relayChatMessage(agentId, sm);
353→          if (cm) chatMessages.push(cm);
354→        }
355→        log("message_history:", agentId, "→", chatMessages.length, "chat msgs,", rawMessages.length, "raw");
356→
357→        // Always replace local messages with server history (source of truth).
358→        setAgents((prev) => {
359→          const existing = prev.get(agentId);
360→          if (!existing) {
361→            log("message_history:", agentId, "agent not in map yet, creating");
362→            const next = new Map(prev);
363→            next.set(agentId, {
364→              status: "idle",
365→              messages: chatMessages,
366→              rawMessages,
367→              label: "",
368→              tmuxSession: null,
369→              createdAt: 0,
370→            });
371→            return next;
372→          }
373→          const next = new Map(prev);
374→          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
375→          return next;
376→        });
377→
378→        processedCountRef.current.set(agentId, chatMessages.length);
379→        setLoadedAgents((prev) => {
380→          if (prev.has(agentId)) return prev;
381→          const next = new Set(prev);
382→          next.add(agentId);
383→          return next;
384→        });
385→        return;
386→      }
387→
388→      // ── history_cleared: wipe local messages for this agent ──
389→      if (data.type === "history_cleared") {
390→        updateAgent(data.agentId, (prev) => ({
391→          ...prev,
392→          messages: [],
393→          rawMessages: [],
394→        }));
395→        processedCountRef.current.set(data.agentId, 0);
396→        return;
397→      }
398→
399→      // ── cli_disconnected: show system message ──
400→      if (data.type === "cli_disconnected") {
401→        updateAgent(data.agentId, (prev) => ({
402→          ...prev,
403→          messages: [
404→            ...prev.messages,
405→            {
406→              id: nextId(),
407→              role: "system",
408→              content: "CLI session ended",
409→              timestamp: Date.now(),
410→            },
411→          ],
412→        }));
413→        return;
414→      }
415→
416→      // ── cli_connected: show system message ──
417→      if (data.type === "cli_connected") {
418→        updateAgent(data.agentId, (prev) => ({
419→          ...prev,
420→          messages: [
421→            ...prev.messages,
422→            {
423→              id: nextId(),
424→              role: "system",
425→              content: "CLI reconnected",
426→              timestamp: Date.now(),
427→            },
428→          ],
429→        }));
430→        return;
431→      }
432→
433→      // ── agent_list: reconcile sidebar state from server ──
434→      if (data.type === "agent_list") {
435→        const serverAgents = data.agents as AgentInfo[];
436→        log("agent_list:", serverAgents.length, "agents:", serverAgents.map((a) => `${a.agentId}(${a.status})`).join(", "));
437→        setAgents((prev) => {
438→          const next = new Map(prev);
439→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
440→
441→          // Update or add agents from server
442→          for (const info of serverAgents) {
443→            const existing = next.get(info.agentId);
444→            if (existing) {
445→              next.set(info.agentId, {
446→                ...existing,
447→                status: info.status,
448→                tmuxSession: info.tmuxSession,
449→                label: info.label,
450→              });
451→            } else {
452→              next.set(info.agentId, {
453→                status: info.status,
454→                messages: [],
455→                rawMessages: [],
456→                label: info.label,
457→                tmuxSession: info.tmuxSession,
458→                createdAt: info.createdAt,
459→              });
460→            }
461→          }
462→
463→          // Remove agents no longer on the server
464→          for (const id of next.keys()) {
465→            if (!serverIds.has(id)) {
466→              next.delete(id);
467→            }
468→          }
469→
470→          return next;
471→        });
472→        setAgentOrder(serverAgents.map((a) => a.agentId));
473→        setInitialLoadDone(true);
474→
475→        // Auto-select the first agent on initial load when nothing is selected
476→        setActiveAgentId((prev) => {
477→          if (prev !== null) return prev;
478→          if (serverAgents.length === 0) return null;
479→          return serverAgents[0].agentId;
480→        });
481→        return;
482→      }
483→
484→      // ── spawned: auto-select the newly created agent ──
485→      if (data.type === "spawned") {
486→        setActiveAgentId(data.agentId);
487→        return;
488→      }
489→
490→      // ── status: update a specific agent's status ──
491→      if (data.type === "status") {
492→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
493→        return;
494→      }
495→
496→      // ── error: append to agent's message list ──
497→      if (data.type === "error") {
498→        updateAgent(data.agentId, (prev) => ({
499→          ...prev,
500→          messages: [
501→            ...prev.messages,
502→            {
503→              id: nextId(),
504→              role: "system",
505→              content: `Error: ${data.error}`,
506→              timestamp: Date.now(),
507→            },
508→          ],
509→        }));
510→        // Track processed count for dedup
511→        processedCountRef.current.set(
512→          data.agentId,
513→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
514→        );
515→        return;
516→      }
517→
518→      // ── relay: append claude message to agent's history ──
519→      if (data.type === "relay") {
520→        const agentId = data.agentId;
521→        const rawMsg = data.message;
522→        const chatMsg = relayChatMessage(agentId, data);
523→
524→        updateAgent(agentId, (prev) => ({
525→          ...prev,
526→          rawMessages: [...prev.rawMessages, rawMsg],
527→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
528→        }));
529→        if (chatMsg) {
530→          // Track processed count for dedup
531→          processedCountRef.current.set(
532→            agentId,
533→            (processedCountRef.current.get(agentId) ?? 0) + 1
534→          );
535→        }
536→        return;
537→      }
538→    };
539→  }, [updateAgent]);
540→
541→  useEffect(() => {
542→    closingRef.current = false;
543→    connect();
544→    return () => {
545→      closingRef.current = true;
546→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
547→      wsRef.current?.close();
548→    };
549→  }, [connect]);
550→
551→  const send = useCallback((data: object) => {
552→    if (wsRef.current?.readyState === WebSocket.OPEN) {
553→      wsRef.current.send(JSON.stringify(data));
554→    }
555→  }, []);
556→
557→  // Request history for the active agent if not already loaded.
558→  useEffect(() => {
559→    if (!activeAgentId || loadedAgents.has(activeAgentId)) return;
560→    log("requesting history for", activeAgentId);
561→    send({ type: "request_history", agentId: activeAgentId });
562→  }, [activeAgentId, loadedAgents, send]);
563→
564→  const spawnAgent = useCallback(
565→    (prompt: string) => {
566→      send({ type: "spawn", prompt });
567→    },
568→    [send]
569→  );
570→
571→  const sendMessage = useCallback(
572→    (content: string) => {
573→      if (!activeAgentId) return;
574→      // Optimistically add user message to local state
575→      updateAgent(activeAgentId, (prev) => ({
576→        ...prev,
577→        messages: [
578→          ...prev.messages,
579→          {
580→            id: nextId(),
581→            role: "user",
582→            content,
583→            timestamp: Date.now(),
584→          },
585→        ],
586→      }));
587→      send({ type: "send_message", agentId: activeAgentId, content });
588→    },
589→    [send, activeAgentId, updateAgent]
590→  );
591→
592→  const respondToControl = useCallback(
593→    (requestId: string, allow: boolean) => {
594→      if (!activeAgentId) return;
595→      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
596→      updateAgent(activeAgentId, (prev) => ({
597→        ...prev,
598→        messages: prev.messages.map((m) =>
599→          m.controlRequest?.id === requestId
600→            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true } }
601→            : m
602→        ),
603→      }));
604→    },
605→    [send, activeAgentId, updateAgent]
606→  );
607→
608→  /** Respond to an AskUserQuestion control request with the user's selections. */
609→  const respondToUserQuestion = useCallback(
610→    (requestId: string, answers: Record<string, string>) => {
611→      if (!activeAgentId) return;
612→      send({
613→        type: "control_response",
614→        agentId: activeAgentId,
615→        request_id: requestId,
616→        allow: true,
617→        answers,
618→      });
619→      updateAgent(activeAgentId, (prev) => ({
620→        ...prev,
621→        messages: prev.messages.map((m) =>
622→          m.userQuestion?.requestId === requestId
623→            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
624→            : m
625→        ),
626→      }));
627→    },
628→    [send, activeAgentId, updateAgent]
629→  );
630→
631→  // ── Agent management actions ──────────────────────────────────────────────
632→
633→  const killAgent = useCallback(
634→    (agentId: string) => {
635→      send({ type: "kill_agent", agentId });
636→    },
637→    [send]
638→  );
639→
640→  const deleteAgent = useCallback(
641→    (agentId: string) => {
642→      send({ type: "delete_agent", agentId });
643→      // Deselect if we just deleted the active agent
644→      setActiveAgentId((prev) => (prev === agentId ? null : prev));
645→    },
646→    [send]
647→  );
648→
649→  const renameAgent = useCallback(
650→    (agentId: string, label: string) => {
651→      send({ type: "rename_agent", agentId, label });
652→    },
653→    [send]
654→  );
655→
656→  const clearHistory = useCallback(
657→    (agentId: string) => {
658→      send({ type: "clear_history", agentId });
659→    },
660→    [send]
661→  );
662→
663→  // ── Task actions ──────────────────────────────────────────────────────────
664→
665→  const createTask = useCallback(
666→    (title: string, description: string, priority: TaskPriority) => {
667→      send({ type: "create_task", title, description, priority });
668→    },
669→    [send]
670→  );
671→
672→  const updateTask = useCallback(
673→    (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => {
674→      send({ type: "update_task", taskId, updates });
675→    },
676→    [send]
677→  );
678→
679→  const deleteTask = useCallback(
680→    (taskId: string) => {
681→      send({ type: "delete_task", taskId });
682→    },
683→    [send]
684→  );
685→
686→  const delegateTask = useCallback(
687→    (taskId: string) => {
688→      send({ type: "delegate_task", taskId });
689→    },
690→    [send]
691→  );
692→
693→  // Derived values for the active agent
694→  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
695→  const activeStatus = useMemo<AgentStatus>(
696→    () => activeAgent?.status ?? "idle",
697→    [activeAgent?.status]
698→  );
699→  const activeMessages = useMemo<ChatMessage[]>(
700→    () => activeAgent?.messages ?? [],
701→    [activeAgent?.messages]
702→  );
703→  const activeRawMessages = useMemo<ClaudeMessage[]>(
704→    () => activeAgent?.rawMessages ?? [],
705→    [activeAgent?.rawMessages]
706→  );
707→  const historyLoading = activeAgentId !== null && !loadedAgents.has(activeAgentId);
708→
709→  return {
710→    connected,
711→    initialLoadDone,
712→    historyLoading,
713→    agents,
714→    agentOrder,
715→    activeAgentId,
716→    setActiveAgentId,
717→    activeStatus,
718→    activeMessages,
719→    activeRawMessages,
720→    spawnAgent,
721→    sendMessage,
722→    respondToControl,
723→    respondToUserQuestion,
724→    killAgent,
725→    deleteAgent,
726→    renameAgent,
727→    clearHistory,
728→    tasks,
729→    createTask,
730→    updateTask,
731→    deleteTask,
732→    delegateTask,
733→  };
734→}
