/**
 * File-based session persistence for thos agents.
 *
 * Persists agent state + message history to JSON files in
 * `.thos/sessions/<agentId>.json` so data survives server restarts.
 *
 * Uses debounced writes (150ms) for high-frequency events (streaming) and
 * synchronous writes for critical state changes (spawn, result, status).
 */

import { mkdirSync, writeFileSync, readFileSync, readdirSync, unlinkSync, existsSync } from "fs";
import { join } from "path";
import type { AgentStatus, ServerMessage } from "../lib/types";

const SESSION_DIR = join(process.cwd(), ".thos", "sessions");

/** Shape of a persisted agent on disk. */
export interface PersistedAgent {
  id: string;
  state: {
    agentId: string;
    status: AgentStatus;
    tmuxSession: string | null;
    label: string;
    createdAt: number;
    sessionId: string | null;
  };
  messageHistory: ServerMessage[];
}

export class SessionStore {
  private dir: string;
  private debounceTimers = new Map<string, ReturnType<typeof setTimeout>>();

  constructor(dir: string = SESSION_DIR) {
    this.dir = dir;
    mkdirSync(this.dir, { recursive: true });
  }

  /** File path for a given agent ID. */
  private filePath(agentId: string): string {
    return join(this.dir, `${agentId}.json`);
  }

  /** Debounced write — batches rapid stream events (150ms). */
  save(agent: PersistedAgent): void {
    const existing = this.debounceTimers.get(agent.id);
    if (existing) clearTimeout(existing);
    this.debounceTimers.set(
      agent.id,
      setTimeout(() => {
        this.debounceTimers.delete(agent.id);
        this.writeFile(agent);
      }, 150)
    );
  }

  /** Immediate write — use for critical state changes (spawn, result, status). */
  saveSync(agent: PersistedAgent): void {
    // Cancel any pending debounced write
    const existing = this.debounceTimers.get(agent.id);
    if (existing) {
      clearTimeout(existing);
      this.debounceTimers.delete(agent.id);
    }
    this.writeFile(agent);
  }

  /** Load a single agent from disk. Returns null if not found. */
  load(agentId: string): PersistedAgent | null {
    const fp = this.filePath(agentId);
    if (!existsSync(fp)) return null;
    try {
      const raw = readFileSync(fp, "utf-8");
      return JSON.parse(raw) as PersistedAgent;
    } catch (err) {
      console.error(`[session-store] failed to load ${agentId}:`, err);
      return null;
    }
  }

  /** Load all persisted agents on server startup. */
  loadAll(): PersistedAgent[] {
    try {
      const files = readdirSync(this.dir).filter((f) => f.endsWith(".json"));
      const agents: PersistedAgent[] = [];
      for (const file of files) {
        try {
          const raw = readFileSync(join(this.dir, file), "utf-8");
          agents.push(JSON.parse(raw) as PersistedAgent);
        } catch (err) {
          console.error(`[session-store] failed to parse ${file}:`, err);
        }
      }
      return agents;
    } catch {
      return [];
    }
  }

  /** Delete an agent's persisted file. */
  remove(agentId: string): void {
    const fp = this.filePath(agentId);
    try {
      if (existsSync(fp)) unlinkSync(fp);
    } catch (err) {
      console.error(`[session-store] failed to remove ${agentId}:`, err);
    }
    // Also cancel any pending debounced write
    const existing = this.debounceTimers.get(agentId);
    if (existing) {
      clearTimeout(existing);
      this.debounceTimers.delete(agentId);
    }
  }

  /** Flush all pending debounced writes synchronously (for graceful shutdown). */
  flushAll(allAgents: PersistedAgent[]): void {
    // Cancel all pending timers
    for (const [id, timer] of this.debounceTimers) {
      clearTimeout(timer);
      this.debounceTimers.delete(id);
    }
    // Write all agents
    for (const agent of allAgents) {
      this.writeFile(agent);
    }
  }

  private writeFile(agent: PersistedAgent): void {
    try {
      writeFileSync(this.filePath(agent.id), JSON.stringify(agent, null, 2));
    } catch (err) {
      console.error(`[session-store] failed to write ${agent.id}:`, err);
    }
  }
}

content.content:
  1→/**
  2→ * Standalone WebSocket relay server for the thos dashboard.
  3→ *
  4→ * Runs on port 9900 alongside Next.js (started via `concurrently` in the
  5→ * `dev` script). It cannot be a Next.js API route because API routes don't
  6→ * support persistent WebSocket connections.
  7→ *
  8→ * ## Architecture
  9→ *
 10→ * Two WebSocket path families:
 11→ * - `/browser`          — the React dashboard connects here (supports multiple tabs).
 12→ * - `/claude/:agentId`  — each Claude CLI connects here (passed as `--sdk-url`).
 13→ *
 14→ * The server supports multiple concurrent agents, each tracked in the
 15→ * `agents` Map keyed by a short random ID.
 16→ *
 17→ * ## Connection flow (browser)
 18→ *
 19→ * On browser connect, the server sends two small messages:
 20→ * 1. `agent_list`  — metadata for all agents (sidebar).
 21→ * 2. `task_list`   — all tasks.
 22→ *
 23→ * Message histories are NOT sent eagerly. They are loaded lazily: the
 24→ * browser sends `{ type: "request_history", agentId }` when the user
 25→ * selects an agent, and the server responds with `message_history` for
 26→ * that single agent. This avoids sending megabytes of JSON on connect,
 27→ * which caused multi-minute loading times on mobile networks.
 28→ *
 29→ * Live messages for active agents are still broadcast to all browsers
 30→ * via `relay` messages in real time.
 31→ *
 32→ * ## Message flow (spawning)
 33→ *
 34→ * 1. Browser sends `{ type: "spawn", prompt }`.
 35→ * 2. Server creates agent entry, spawns `claude --sdk-url ws://localhost:9900/claude/<agentId>`.
 36→ * 3. CLI connects on `/claude/<agentId>`, sends `system/hook_started` then `system/hook_response`.
 37→ * 4. On `hook_response`, server forwards the pending prompt to the CLI.
 38→ * 5. CLI sends `system/init`, then `assistant` messages, then `result`.
 39→ * 6. All CLI messages are relayed to the browser as `{ type: "relay", agentId, message }`.
 40→ * 7. `control_request` messages (tool approval) are relayed to the browser;
 41→ *    the browser's `control_response` (with `agentId`) is forwarded back to the right CLI.
 42→ *
 43→ * ## Resilience features
 44→ *
 45→ * - **Server-side message history** — every relay message is stored per-agent.
 46→ * - **File persistence** — agent state + history persisted to disk, survives restarts.
 47→ * - **Multi-browser** — multiple tabs can connect simultaneously.
 48→ * - **tmux survival** — tmux sessions are NOT killed on server restart; CLI processes
 49→ *   can reconnect to the new server if they retry their WebSocket connection.
 50→ * - **Message queuing** — messages sent while CLI is disconnected are queued and flushed on reconnect.
 51→ * - **Disconnect notifications** — browser is notified of CLI disconnect/reconnect.
 52→ * - **Lazy history** — message histories loaded on demand per agent, not on connect.
 53→ */
 54→import { WebSocketServer, WebSocket } from "ws";
 55→import { execSync, spawn } from "child_process";
 56→import { randomBytes } from "crypto";
 57→import type { IncomingMessage } from "http";
 58→import type {
 59→  BrowserMessage,
 60→  ClaudeMessage,
 61→  ServerMessage,
 62→  AgentStatus,
 63→  AgentInfo,
 64→  Task,
 65→} from "../lib/types";
 66→import { SessionStore, type PersistedAgent } from "./session-store";
 67→import { TaskStore } from "./task-store";
 68→
 69→const PORT = 9900;
 70→const TMUX_SESSION_PREFIX = "thos-agent";
 71→
 72→/** Check if an IP is localhost or in the Tailscale CGNAT range (100.64.0.0/10). */
 73→function isAllowedIP(ip: string | undefined): boolean {
 74→  if (!ip) return false;
 75→  // Strip IPv6-mapped IPv4 prefix
 76→  const addr = ip.startsWith("::ffff:") ? ip.slice(7) : ip;
 77→  if (addr === "127.0.0.1" || addr === "::1" || addr === "localhost") return true;
 78→  // Tailscale CGNAT: 100.64.0.0/10 → 100.64.0.0 – 100.127.255.255
 79→  const parts = addr.split(".");
 80→  if (parts.length !== 4) return false;
 81→  const first = parseInt(parts[0], 10);
 82→  const second = parseInt(parts[1], 10);
 83→  return first === 100 && second >= 64 && second <= 127;
 84→}
 85→
 86→const wss = new WebSocketServer({
 87→  port: PORT,
 88→  verifyClient: (info) => {
 89→    const ip = info.req.socket.remoteAddress;
 90→    const allowed = isAllowedIP(ip);
 91→    if (!allowed) console.log(`[ws] rejected connection from ${ip}`);
 92→    return allowed;
 93→  },
 94→});
 95→const store = new SessionStore();
 96→
 97→// ── Multi-agent state ──────────────────────────────────────────────────────
 98→
 99→interface AgentState {
100→  agentId: string;
101→  claudeSocket: WebSocket | null;
102→  tmuxSession: string | null;
103→  pendingPrompt: string | null;
104→  status: AgentStatus;
105→  label: string;
106→  createdAt: number;
107→  /** Captured from system/init, used in subsequent user messages. */
108→  sessionId: string | null;
109→  /** Stores control_request inputs keyed by request_id, for building control_responses. */
110→  pendingControlRequests: Map<string, Record<string, unknown>>;
111→  /** All messages sent to the browser for this agent (source of truth). */
112→  messageHistory: ServerMessage[];
113→  /** Messages queued while CLI is disconnected, flushed on reconnect. */
114→  pendingMessages: string[];
115→}
116→
117→const agents = new Map<string, AgentState>();
118→const taskStore = new TaskStore();
119→const tasks = new Map<string, Task>();
120→
121→/** All active browser connections (supports multiple tabs). */
122→const browserSockets = new Set<WebSocket>();
123→
124→/** Generate a short random agent ID. */
125→function newAgentId(): string {
126→  return randomBytes(4).toString("hex");
127→}
128→
129→// ── tmux helpers ───────────────────────────────────────────────────────────
130→
131→/** Return the set of currently alive tmux session names matching the thos prefix. */
132→function listAliveTmuxSessions(): Set<string> {
133→  try {
134→    const output = execSync("tmux list-sessions -F '#{session_name}'", {
135→      encoding: "utf-8",
136→    }).trim();
137→    if (!output) return new Set();
138→    return new Set(output.split("\n").filter((s) => s.startsWith(TMUX_SESSION_PREFIX)));
139→  } catch {
140→    return new Set();
141→  }
142→}
143→
144→// ── Persistence helpers ────────────────────────────────────────────────────
145→
146→/** Build a PersistedAgent snapshot from live state. */
147→function toPersistedAgent(agent: AgentState): PersistedAgent {
148→  return {
149→    id: agent.agentId,
150→    state: {
151→      agentId: agent.agentId,
152→      status: agent.status,
153→      tmuxSession: agent.tmuxSession,
154→      label: agent.label,
155→      createdAt: agent.createdAt,
156→      sessionId: agent.sessionId,
157→    },
158→    messageHistory: agent.messageHistory,
159→  };
160→}
161→
162→/**
163→ * Compact a message history by deduplicating cumulative snapshots.
164→ * Keeps only the last version of each assistant/user message ID.
165→ * Called on restore to shrink legacy bloated histories.
166→ */
167→function compactHistory(history: ServerMessage[]): ServerMessage[] {
168→  // Build a map of msgId → last index
169→  const lastIndex = new Map<string, number>();
170→  for (let i = 0; i < history.length; i++) {
171→    const id = getRelayMessageId(history[i]);
172→    if (id) lastIndex.set(id, i);
173→  }
174→  // Keep only messages that are either non-deduplicable or the last occurrence
175→  return history.filter((msg, i) => {
176→    const id = getRelayMessageId(msg);
177→    if (!id) return true; // non-relay or no message ID — always keep
178→    return lastIndex.get(id) === i;
179→  });
180→}
181→
182→/** Persist agent state (debounced — use for streaming events). */
183→function persistAgent(agent: AgentState) {
184→  store.save(toPersistedAgent(agent));
185→}
186→
187→/** Persist agent state immediately (use for critical state changes). */
188→function persistAgentSync(agent: AgentState) {
189→  store.saveSync(toPersistedAgent(agent));
190→}
191→
192→// ── Restore from disk on startup ───────────────────────────────────────────
193→
194→function restoreAgents() {
195→  const persisted = store.loadAll();
196→  const aliveSessions = listAliveTmuxSessions();
197→
198→  for (const p of persisted) {
199→    const agent: AgentState = {
200→      agentId: p.state.agentId,
201→      claudeSocket: null,
202→      tmuxSession: p.state.tmuxSession,
203→      pendingPrompt: null,
204→      status: p.state.status,
205→      label: p.state.label,
206→      createdAt: p.state.createdAt,
207→      sessionId: p.state.sessionId,
208→      pendingControlRequests: new Map(),
209→      messageHistory: compactHistory(p.messageHistory),
210→      pendingMessages: [],
211→    };
212→
213→    // Determine status for agents that were active when the server last ran
214→    if (agent.status !== "done" && agent.status !== "error") {
215→      const tmuxAlive = agent.tmuxSession ? aliveSessions.has(agent.tmuxSession) : false;
216→      if (tmuxAlive) {
217→        // tmux session still alive — CLI may reconnect to this server
218→        agent.status = "disconnected";
219→        console.log(`[restore] agent ${agent.agentId} — tmux alive, waiting for CLI reconnect`);
220→      } else {
221→        // tmux session gone — agent is archived
222→        agent.status = "done";
223→        console.log(`[restore] agent ${agent.agentId} — tmux dead, archived`);
224→      }
225→    }
226→
227→    agents.set(agent.agentId, agent);
228→    const originalCount = p.messageHistory.length;
229→    const compactedCount = agent.messageHistory.length;
230→    const saved = originalCount - compactedCount;
231→    console.log(`[restore] agent ${agent.agentId} (status=${agent.status}, ${compactedCount} messages${saved > 0 ? `, compacted from ${originalCount} (−${saved})` : ""})`);
232→
233→    // Persist compacted history back to disk
234→    if (saved > 0) {
235→      persistAgentSync(agent);
236→    }
237→  }
238→  console.log(`[restore] loaded ${persisted.length} agents from disk`);
239→}
240→
241→restoreAgents();
242→
243→// ── Task restore + helpers ────────────────────────────────────────────────
244→
245→function restoreTasks() {
246→  const persisted = taskStore.loadAll();
247→  for (const t of persisted) {
248→    tasks.set(t.id, t);
249→  }
250→  console.log(`[restore] loaded ${persisted.length} tasks from disk`);
251→}
252→
253→restoreTasks();
254→
255→/** Build the full task list sorted by creation time (newest first). */
256→function buildTaskList(): Task[] {
257→  return Array.from(tasks.values()).sort((a, b) => b.createdAt - a.createdAt);
258→}
259→
260→/** Send the full task list to all browsers. */
261→function broadcastTaskList() {
262→  const payload = JSON.stringify({ type: "task_list", tasks: buildTaskList() });
263→  for (const ws of browserSockets) {
264→    if (ws.readyState === WebSocket.OPEN) {
265→      ws.send(payload);
266→    }
267→  }
268→}
269→
270→/** Persist all tasks to disk (sync). */
271→function persistTasks() {
272→  taskStore.saveSync(Array.from(tasks.values()));
273→}
274→
275→// ── Helpers ────────────────────────────────────────────────────────────────
276→
277→/** Send a JSON message to all connected browsers. */
278→function sendToBrowser(msg: ServerMessage) {
279→  const payload = JSON.stringify(msg);
280→  for (const ws of browserSockets) {
281→    if (ws.readyState === WebSocket.OPEN) {
282→      ws.send(payload);
283→    }
284→  }
285→}
286→
287→/** Build a snapshot of all agents for the sidebar. */
288→function buildAgentList(): AgentInfo[] {
289→  return Array.from(agents.values()).map((a) => ({
290→    agentId: a.agentId,
291→    status: a.status,
292→    tmuxSession: a.tmuxSession,
293→    label: a.label,
294→    createdAt: a.createdAt,
295→  }));
296→}
297→
298→/** Send the full agent list to all browsers. */
299→function broadcastAgentList() {
300→  sendToBrowser({ type: "agent_list", agents: buildAgentList() });
301→}
302→
303→/** Update an agent's status, notify browsers, broadcast list, and persist. */
304→function setAgentStatus(agentId: string, status: AgentStatus) {
305→  const agent = agents.get(agentId);
306→  if (!agent) return;
307→  agent.status = status;
308→  sendToBrowser({ type: "status", agentId, status });
309→  broadcastAgentList();
310→  persistAgentSync(agent);
311→}
312→
313→/**
314→ * Extract a stable dedup key from a relay message, if present.
315→ *
316→ * Claude NDJSON sends cumulative snapshots for two message types:
317→ * - `assistant` — keyed by `message.id` (e.g. `msg_01VE1P7c...`)
318→ * - `user` (tool_result) — keyed by top-level `uuid` (e.g. `b217b852-...`)
319→ *
320→ * Additionally, one-per-session messages are deduplicated by session_id:
321→ * - `system/init` — keyed by `init:<session_id>`
322→ * - `result` — keyed by `result:<session_id>`
323→ *
324→ * We deduplicate by replacing the previous snapshot in `messageHistory`
325→ * instead of appending, reducing storage from O(n²) to O(n).
326→ */
327→function getRelayMessageId(msg: ServerMessage): string | null {
328→  if (msg.type !== "relay") return null;
329→  const inner = msg.message;
330→  if (inner.type === "assistant") {
331→    return (inner as { message?: { id?: string } }).message?.id ?? null;
332→  }
333→  if (inner.type === "user") {
334→    return (inner as { uuid?: string }).uuid ?? null;
335→  }
336→  // Dedup system/init and result by session_id so they don't stack on reload
337→  if (inner.type === "system" && (inner as { subtype?: string }).subtype === "init") {
338→    const sid = (inner as { session_id?: string }).session_id;
339→    return sid ? `init:${sid}` : null;
340→  }
341→  if (inner.type === "result") {
342→    const sid = (inner as { session_id?: string }).session_id;
343→    return sid ? `result:${sid}` : null;
344→  }
345→  return null;
346→}
347→
348→/**
349→ * Record a message in the agent's history and send to all browsers.
350→ *
351→ * For cumulative snapshot messages (assistant, user/tool_result), replaces the
352→ * previous snapshot with the same message ID instead of appending. This keeps
353→ * only the final version of each message, dramatically reducing file sizes
354→ * (e.g. 38 MB → ~1 MB for a typical session).
355→ */
356→function recordAndSend(agentId: string, msg: ServerMessage) {
357→  const agent = agents.get(agentId);
358→  if (agent) {
359→    const msgId = getRelayMessageId(msg);
360→    if (msgId) {
361→      // Replace previous snapshot with same message ID (search from end for speed)
362→      let replaced = false;
363→      for (let i = agent.messageHistory.length - 1; i >= 0; i--) {
364→        if (getRelayMessageId(agent.messageHistory[i]) === msgId) {
365→          agent.messageHistory[i] = msg;
366→          replaced = true;
367→          break;
368→        }
369→      }
370→      if (!replaced) {
371→        agent.messageHistory.push(msg);
372→      }
373→    } else {
374→      agent.messageHistory.push(msg);
375→    }
376→    persistAgent(agent); // debounced — streaming messages come fast
377→  }
378→  sendToBrowser(msg);
379→}
380→
381→// ── Agent lifecycle ────────────────────────────────────────────────────────
382→
383→/**
384→ * Stop a running agent by killing its tmux session and closing the CLI socket.
385→ * The agent remains in the Map (status set to "done") so it can be viewed/deleted later.
386→ */
387→function stopAgent(agentId: string) {
388→  const agent = agents.get(agentId);
389→  if (!agent) return;
390→
391→  if (agent.tmuxSession) {
392→    try {
393→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
394→      console.log(`[tmux] killed session ${agent.tmuxSession}`);
395→    } catch {
396→      // Session may already be dead
397→    }
398→  }
399→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
400→    agent.claudeSocket.close();
401→  }
402→  agent.claudeSocket = null;
403→  setAgentStatus(agentId, "done");
404→}
405→
406→/**
407→ * Permanently delete an agent: stop it, remove from Map, remove from disk.
408→ */
409→function deleteAgent(agentId: string) {
410→  const agent = agents.get(agentId);
411→  if (!agent) return;
412→
413→  if (agent.tmuxSession) {
414→    try {
415→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
416→    } catch {}
417→  }
418→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
419→    agent.claudeSocket.close();
420→  }
421→  agents.delete(agentId);
422→  store.remove(agentId);
423→  broadcastAgentList();
424→}
425→
426→/**
427→ * Spawn a new Claude CLI process inside a tmux session.
428→ *
429→ * Creates a new agent entry, spawns the CLI with `--sdk-url` pointing to
430→ * `/claude/<agentId>`, and sends a `spawned` message to the browser.
431→ */
432→function spawnClaude(prompt: string): string {
433→  const agentId = newAgentId();
434→  const sessionName = `${TMUX_SESSION_PREFIX}-${agentId}`;
435→  const label = prompt.length > 60 ? prompt.slice(0, 57) + "..." : prompt;
436→
437→  const agent: AgentState = {
438→    agentId,
439→    claudeSocket: null,
440→    tmuxSession: null,
441→    pendingPrompt: prompt,
442→    status: "spawning",
443→    label,
444→    createdAt: Date.now(),
445→    sessionId: null,
446→    pendingControlRequests: new Map(),
447→    messageHistory: [],
448→    pendingMessages: [],
449→  };
450→  agents.set(agentId, agent);
451→
452→  // Notify browsers
453→  sendToBrowser({ type: "spawned", agentId });
454→  broadcastAgentList();
455→  persistAgentSync(agent);
456→
457→  // Build the claude command with CLAUDECODE unset to bypass nesting protection.
458→  // tmux new-session runs detached (-d) so spawn() returns immediately.
459→  const claudeCmd = `unset CLAUDECODE; exec claude --dangerously-skip-permissions --sdk-url ws://localhost:${PORT}/claude/${agentId}`;
460→
461→  const tmux = spawn("tmux", ["new-session", "-d", "-s", sessionName, "bash", "-c", claudeCmd], {
462→    stdio: "ignore",
463→  });
464→
465→  tmux.on("error", (err) => {
466→    console.error("[tmux spawn error]", err);
467→    setAgentStatus(agentId, "error");
468→    recordAndSend(agentId, { type: "error", agentId, error: `tmux error: ${err.message}` });
469→  });
470→
471→  tmux.on("exit", (code) => {
472→    if (code !== 0) {
473→      console.error(`[tmux] new-session exited with code ${code}`);
474→      setAgentStatus(agentId, "error");
475→      recordAndSend(agentId, { type: "error", agentId, error: `tmux exited with code ${code}` });
476→      return;
477→    }
478→    console.log(`[tmux] session ${sessionName} created — attach with: tmux attach -t ${sessionName}`);
479→    agent.tmuxSession = sessionName;
480→    broadcastAgentList();
481→    persistAgentSync(agent);
482→  });
483→
484→  return agentId;
485→}
486→
487→// ── Message handlers ───────────────────────────────────────────────────────
488→
489→/**
490→ * Process an incoming NDJSON message from a specific Claude CLI.
491→ *
492→ * Status flow matches the Companion protocol:
493→ * - hook_response → send pending prompt → "thinking"
494→ * - system/init   → "connected" + capture session_id
495→ * - assistant      → "thinking"
496→ * - result         → "connected" (CLI stays alive for multi-turn)
497→ * - CLI disconnect → "done" (handled in connection close handler)
498→ */
499→function handleClaudeMessage(agentId: string, raw: string) {
500→  const agent = agents.get(agentId);
501→  if (!agent) return;
502→
503→  let msg: ClaudeMessage;
504→  try {
505→    msg = JSON.parse(raw);
506→  } catch {
507→    console.error(`[claude:${agentId}] invalid JSON:`, raw);
508→    return;
509→  }
510→
511→  // Silently ignore keep_alive messages
512→  if (msg.type === "keep_alive") return;
513→
514→  console.log(`[claude:${agentId} →]`, msg.type, (msg as { subtype?: string }).subtype ?? "");
515→
516→  // After hook_response, send the pending prompt
517→  if (
518→    msg.type === "system" &&
519→    (msg as { subtype?: string }).subtype === "hook_response" &&
520→    agent.pendingPrompt &&
521→    agent.claudeSocket?.readyState === WebSocket.OPEN
522→  ) {
523→    const userMsg = JSON.stringify({
524→      type: "user",
525→      message: { role: "user", content: agent.pendingPrompt },
526→      parent_tool_use_id: null,
527→      session_id: agent.sessionId ?? "",
528→    });
529→    console.log(`[server → claude:${agentId}]`, userMsg);
530→    agent.claudeSocket.send(userMsg + "\n");
531→    agent.pendingPrompt = null;
532→    setAgentStatus(agentId, "thinking");
533→  }
534→
535→  // Track status based on message type
536→  if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
537→    // Capture session_id for subsequent user messages
538→    agent.sessionId = (msg as { session_id?: string }).session_id ?? null;
539→    setAgentStatus(agentId, "connected");
540→  } else if (msg.type === "assistant") {
541→    setAgentStatus(agentId, "thinking");
542→  } else if (msg.type === "result") {
543→    // CLI stays alive after result — ready for the next turn.
544→    // Status only goes to "done" when the CLI WebSocket actually closes.
545→    setAgentStatus(agentId, "connected");
546→  }
547→
548→  // Store control_request inputs for building proper responses later
549→  if (msg.type === "control_request") {
550→    const cr = msg as { request_id?: string; request?: { input?: Record<string, unknown> } };
551→    if (cr.request_id && cr.request?.input) {
552→      agent.pendingControlRequests.set(cr.request_id, cr.request.input);
553→    }
554→  }
555→
556→  // Record in history and relay to browsers
557→  recordAndSend(agentId, { type: "relay", agentId, message: msg });
558→}
559→
560→/**
561→ * Process an incoming JSON message from the browser.
562→ * - `spawn`: create a new agent (does NOT kill others).
563→ * - `send_message`: forward a follow-up user message to the specified agent.
564→ * - `control_response`: forward a tool allow/deny decision to the specified agent.
565→ * - `kill_agent`: stop the CLI and tmux session.
566→ * - `delete_agent`: permanently remove an agent.
567→ * - `rename_agent`: update an agent's label.
568→ * - `clear_history`: wipe an agent's message history.
569→ * - `request_history`: send message history for a single agent (lazy loading).
570→ * - `create_task` / `update_task` / `delete_task` / `delegate_task`: task CRUD.
571→ */
572→function handleBrowserMessage(raw: string, senderWs: WebSocket) {
573→  let msg: BrowserMessage;
574→  try {
575→    msg = JSON.parse(raw);
576→  } catch {
577→    console.error("[browser] invalid JSON:", raw);
578→    return;
579→  }
580→
581→  console.log("[browser →]", msg.type);
582→
583→  switch (msg.type) {
584→    case "spawn":
585→      spawnClaude(msg.prompt);
586→      break;
587→
588→    case "send_message": {
589→      const agent = agents.get(msg.agentId);
590→      if (!agent) {
591→        sendToBrowser({ type: "error", agentId: msg.agentId, error: "Unknown agent" });
592→        break;
593→      }
594→
595→      // Record the user message in history so it persists across reloads.
596→      // Do NOT broadcast — the sending browser already has it optimistically,
597→      // and other browsers will get it when they request_history.
598→      agent.messageHistory.push({
599→        type: "relay",
600→        agentId: msg.agentId,
601→        message: { type: "user", message: { role: "user", content: msg.content } },
602→      } as ServerMessage);
603→      persistAgent(agent);
604→
605→      if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
606→        const userMsg = JSON.stringify({
607→          type: "user",
608→          message: { role: "user", content: msg.content },
609→          parent_tool_use_id: null,
610→          session_id: agent.sessionId ?? "",
611→        });
612→        agent.claudeSocket.send(userMsg + "\n");
613→        setAgentStatus(msg.agentId, "thinking");
614→      } else {
615→        // Queue message for delivery when CLI reconnects
616→        const userMsg = JSON.stringify({
617→          type: "user",
618→          message: { role: "user", content: msg.content },
619→          parent_tool_use_id: null,
620→          session_id: agent.sessionId ?? "",
621→        });
622→        agent.pendingMessages.push(userMsg);
623→        console.log(`[queue] queued message for agent ${msg.agentId} (${agent.pendingMessages.length} pending)`);
624→        persistAgentSync(agent);
625→      }
626→      break;
627→    }
628→
629→    case "control_response": {
630→      const agent = agents.get(msg.agentId);
631→      if (agent?.claudeSocket?.readyState === WebSocket.OPEN) {
632→        // Retrieve the original tool input to include as updatedInput (required by protocol)
633→        const originalInput = agent.pendingControlRequests.get(msg.request_id) ?? {};
634→        agent.pendingControlRequests.delete(msg.request_id);
635→
636→        // If the browser sent answers (from AskUserQuestion), merge them into the input
637→        const answers = (msg as { answers?: Record<string, string> }).answers;
638→        const updatedInput = answers
639→          ? { ...originalInput, answers }
640→          : originalInput;
641→
642→        const response = JSON.stringify({
643→          type: "control_response",
644→          response: {
645→            subtype: "success",
646→            request_id: msg.request_id,
647→            response: msg.allow
648→              ? { behavior: "allow", updatedInput }
649→              : { behavior: "deny", message: "Denied by user" },
650→          },
651→        });
652→        agent.claudeSocket.send(response + "\n");
653→      }
654→      break;
655→    }
656→
657→    case "kill_agent":
658→      stopAgent(msg.agentId);
659→      break;
660→
661→    case "delete_agent":
662→      deleteAgent(msg.agentId);
663→      break;
664→
665→    case "rename_agent": {
666→      const agent = agents.get(msg.agentId);
667→      if (!agent) break;
668→      agent.label = msg.label;
669→      broadcastAgentList();
670→      persistAgentSync(agent);
671→      break;
672→    }
673→
674→    case "clear_history": {
675→      const agent = agents.get(msg.agentId);
676→      if (!agent) break;
677→      agent.messageHistory = [];
678→      persistAgentSync(agent);
679→      sendToBrowser({ type: "history_cleared", agentId: msg.agentId });
680→      break;
681→    }
682→
683→    case "request_history": {
684→      console.log(`[browser] request_history for ${msg.agentId}`);
685→      sendHistoryToSocket(senderWs, msg.agentId);
686→      break;
687→    }
688→
689→    case "create_task": {
690→      const taskId = randomBytes(4).toString("hex");
691→      const task: Task = {
692→        id: taskId,
693→        title: msg.title,
694→        description: msg.description,
695→        status: "todo",
696→        priority: msg.priority,
697→        agentId: null,
698→        createdAt: Date.now(),
699→        updatedAt: Date.now(),
700→      };
701→      tasks.set(taskId, task);
702→      persistTasks();
703→      broadcastTaskList();
704→      break;
705→    }
706→
707→    case "update_task": {
708→      const task = tasks.get(msg.taskId);
709→      if (!task) break;
710→      Object.assign(task, msg.updates, { updatedAt: Date.now() });
711→      persistTasks();
712→      broadcastTaskList();
713→      break;
714→    }
715→
716→    case "delete_task": {
717→      tasks.delete(msg.taskId);
718→      persistTasks();
719→      broadcastTaskList();
720→      break;
721→    }
722→
723→    case "delegate_task": {
724→      const task = tasks.get(msg.taskId);
725→      if (!task) break;
726→      const prompt = `Task: ${task.title}\n\n${task.description}`;
727→      const agentId = spawnClaude(prompt);
728→      task.agentId = agentId;
729→      task.status = "in-progress";
730→      task.updatedAt = Date.now();
731→      persistTasks();
732→      broadcastTaskList();
733→      break;
734→    }
735→  }
736→}
737→
738→// ── Send message history to a single browser socket ────────────────────────
739→
740→/** Send initial state (agent list + tasks) to a newly connected browser. */
741→function sendFullStateToSocket(ws: WebSocket) {
742→  if (ws.readyState !== WebSocket.OPEN) return;
743→
744→  // Agent list (sidebar metadata) — message histories are loaded lazily on demand
745→  ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList() }));
746→
747→  // Task list
748→  ws.send(JSON.stringify({ type: "task_list", tasks: buildTaskList() }));
749→}
750→
751→/** Send message history for a single agent to a specific browser socket. */
752→function sendHistoryToSocket(ws: WebSocket, agentId: string) {
753→  const agent = agents.get(agentId);
754→  if (!agent || ws.readyState !== WebSocket.OPEN) return;
755→  ws.send(
756→    JSON.stringify({
757→      type: "message_history",
758→      agentId: agent.agentId,
759→      messages: agent.messageHistory,
760→    })
761→  );
762→}
763→
764→// ── Connection handler — route by URL path ────────────────────────────────
765→wss.on("connection", (ws: WebSocket, req: IncomingMessage) => {
766→  const path = req.url ?? "/";
767→  console.log(`[ws connected] path=${path}`);
768→
769→  if (path === "/browser") {
770→    // Send full state BEFORE adding to browserSockets so that live
771→    // relay broadcasts don't interleave with the history replay.
772→    sendFullStateToSocket(ws);
773→    browserSockets.add(ws);
774→
775→    ws.on("message", (data) => {
776→      handleBrowserMessage(data.toString(), ws);
777→    });
778→
779→    ws.on("close", () => {
780→      console.log("[browser disconnected]");
781→      browserSockets.delete(ws);
782→      // Do NOT kill agents — keep them alive for reconnect
783→    });
784→  } else if (path.startsWith("/claude/")) {
785→    // Parse agentId from /claude/<agentId>
786→    const agentId = path.slice("/claude/".length);
787→    const agent = agents.get(agentId);
788→
789→    if (!agent) {
790→      console.log(`[ws] unknown agentId: ${agentId}, closing`);
791→      ws.close();
792→      return;
793→    }
794→
795→    agent.claudeSocket = ws;
796→    console.log(`[claude:${agentId} CLI connected via WebSocket]`);
797→
798→    // Notify browsers that CLI is connected
799→    sendToBrowser({ type: "cli_connected", agentId });
800→
801→    // Flush any pending messages queued while CLI was disconnected
802→    if (agent.pendingMessages.length > 0) {
803→      console.log(`[flush] sending ${agent.pendingMessages.length} queued messages to agent ${agentId}`);
804→      for (const queued of agent.pendingMessages) {
805→        ws.send(queued + "\n");
806→      }
807→      agent.pendingMessages = [];
808→      persistAgentSync(agent);
809→    }
810→
811→    // Send the pending prompt immediately — CLI 2.1.42+ waits for the
812→    // server to send the first user message rather than emitting
813→    // hook_started/hook_response on connect.
814→    if (agent.pendingPrompt && ws.readyState === WebSocket.OPEN) {
815→      const userMsg = JSON.stringify({
816→        type: "user",
817→        message: { role: "user", content: agent.pendingPrompt },
818→        parent_tool_use_id: null,
819→        session_id: agent.sessionId ?? "",
820→      });
821→      console.log(`[server → claude:${agentId}] sending pending prompt`);
822→      ws.send(userMsg + "\n");
823→      agent.pendingPrompt = null;
824→      setAgentStatus(agentId, "thinking");
825→    }
826→
827→    ws.on("message", (data) => {
828→      handleClaudeMessage(agentId, data.toString());
829→    });
830→
831→    ws.on("close", () => {
832→      console.log(`[claude:${agentId} CLI disconnected]`);
833→      if (agent.claudeSocket === ws) {
834→        agent.claudeSocket = null;
835→        if (agent.status !== "error") {
836→          setAgentStatus(agentId, "done");
837→          sendToBrowser({ type: "cli_disconnected", agentId });
838→
839→          // Auto-complete any task linked to this agent
840→          for (const task of tasks.values()) {
841→            if (task.agentId === agentId && task.status !== "done") {
842→              task.status = "done";
843→              task.updatedAt = Date.now();
844→              persistTasks();
845→              broadcastTaskList();
846→              break;
847→            }
848→          }
849→        }
850→      }
851→    });
852→  } else {
853→    console.log(`[ws] unknown path: ${path}, closing`);
854→    ws.close();
855→  }
856→});
857→
858→// ── Graceful shutdown ─────────────────────────────────────────────────────
859→
860→function shutdown() {
861→  console.log("[ws server] shutting down...");
862→
863→  // Persist all agents synchronously before exit — do NOT kill tmux sessions
864→  // so CLI processes can reconnect if the server restarts.
865→  const allPersisted = Array.from(agents.values()).map(toPersistedAgent);
866→  store.flushAll(allPersisted);
867→  console.log(`[ws server] saved ${allPersisted.length} agents to disk (tmux sessions preserved)`);
868→
869→  taskStore.flush(Array.from(tasks.values()));
870→  console.log(`[ws server] saved ${tasks.size} tasks to disk`);
871→
872→  wss.close();
873→  process.exit(0);
874→}
875→
876→process.on("SIGTERM", shutdown);
877→process.on("SIGINT", shutdown);
878→
879→console.log(`[ws server] listening on port ${PORT}`);
880→

