     export class WorkspaceStore {
       constructor() {
         mkdirSync(THOS_DIR, { recursive: true });
       }
       loadAll(): Workspace[] {
         if (!existsSync(WORKSPACE_FILE)) return [];
         try {
           const raw = readFileSync(WORKSPACE_FILE, "utf-8");
