  1→/**
  2→ * Standalone WebSocket relay server for the thos dashboard.
  3→ *
  4→ * Runs on port 9900 alongside Next.js (started via `concurrently` in the
  5→ * `dev` script). It cannot be a Next.js API route because API routes don't
  6→ * support persistent WebSocket connections.
  7→ *
  8→ * ## Architecture
  9→ *
 10→ * Two WebSocket path families:
 11→ * - `/browser`          — the React dashboard connects here (supports multiple tabs).
 12→ * - `/claude/:agentId`  — each Claude CLI connects here (passed as `--sdk-url`).
 13→ *
 14→ * The server supports multiple concurrent agents, each tracked in the
 15→ * `agents` Map keyed by a short random ID.
 16→ *
 17→ * ## Connection flow (browser)
 18→ *
 19→ * On browser connect, the server sends two small messages:
 20→ * 1. `agent_list`  — metadata for all agents (sidebar).
 21→ * 2. `task_list`   — all tasks.
 22→ *
 23→ * Message histories are NOT sent eagerly. They are loaded lazily: the
 24→ * browser sends `{ type: "request_history", agentId }` when the user
 25→ * selects an agent, and the server responds with `message_history` for
 26→ * that single agent. This avoids sending megabytes of JSON on connect,
 27→ * which caused multi-minute loading times on mobile networks.
 28→ *
 29→ * Live messages for active agents are still broadcast to all browsers
 30→ * via `relay` messages in real time.
 31→ *
 32→ * ## Message flow (spawning)
 33→ *
 34→ * 1. Browser sends `{ type: "spawn", prompt }`.
 35→ * 2. Server creates agent entry, spawns `claude --sdk-url ws://localhost:9900/claude/<agentId>`.
 36→ * 3. CLI connects on `/claude/<agentId>`, sends `system/hook_started` then `system/hook_response`.
 37→ * 4. On `hook_response`, server forwards the pending prompt to the CLI.
 38→ * 5. CLI sends `system/init`, then `assistant` messages, then `result`.
 39→ * 6. All CLI messages are relayed to the browser as `{ type: "relay", agentId, message }`.
 40→ * 7. `control_request` messages (tool approval) are relayed to the browser;
 41→ *    the browser's `control_response` (with `agentId`) is forwarded back to the right CLI.
 42→ *
 43→ * ## Resilience features
 44→ *
 45→ * - **Server-side message history** — every relay message is stored per-agent.
 46→ * - **File persistence** — agent state + history persisted to disk, survives restarts.
 47→ * - **Multi-browser** — multiple tabs can connect simultaneously.
 48→ * - **tmux survival** — tmux sessions are NOT killed on server restart; CLI processes
 49→ *   can reconnect to the new server if they retry their WebSocket connection.
 50→ * - **Message queuing** — messages sent while CLI is disconnected are queued and flushed on reconnect.
 51→ * - **Disconnect notifications** — browser is notified of CLI disconnect/reconnect.
 52→ * - **Lazy history** — message histories loaded on demand per agent, not on connect.
 53→ */
 54→import { WebSocketServer, WebSocket } from "ws";
 55→import { execSync, spawn } from "child_process";
 56→import { randomBytes } from "crypto";
 57→import type { IncomingMessage } from "http";
 58→import { readdirSync, statSync, existsSync } from "fs";
 59→import { join, dirname, basename } from "path";
 60→import type {
 61→  BrowserMessage,
 62→  ClaudeMessage,
 63→  ServerMessage,
 64→  AgentStatus,
 65→  AgentInfo,
 66→  Task,
 67→  Workspace,
 68→  DirectoryEntry,
 69→} from "../lib/types";
 70→import { SessionStore, type PersistedAgent } from "./session-store";
 71→import { TaskStore } from "./task-store";
 72→import { WorkspaceStore } from "./workspace-store";
 73→
 74→const PORT = 9900;
 75→const TMUX_SESSION_PREFIX = "thos-agent";
 76→
 77→/** Check if an IP is localhost or in the Tailscale CGNAT range (100.64.0.0/10). */
 78→function isAllowedIP(ip: string | undefined): boolean {
 79→  if (!ip) return false;
 80→  // Strip IPv6-mapped IPv4 prefix
 81→  const addr = ip.startsWith("::ffff:") ? ip.slice(7) : ip;
 82→  if (addr === "127.0.0.1" || addr === "::1" || addr === "localhost") return true;
 83→  // Tailscale CGNAT: 100.64.0.0/10 → 100.64.0.0 – 100.127.255.255
 84→  const parts = addr.split(".");
 85→  if (parts.length !== 4) return false;
 86→  const first = parseInt(parts[0], 10);
 87→  const second = parseInt(parts[1], 10);
 88→  return first === 100 && second >= 64 && second <= 127;
 89→}
 90→
 91→const wss = new WebSocketServer({
 92→  port: PORT,
 93→  verifyClient: (info) => {
 94→    const ip = info.req.socket.remoteAddress;
 95→    const allowed = isAllowedIP(ip);
 96→    if (!allowed) console.log(`[ws] rejected connection from ${ip}`);
 97→    return allowed;
 98→  },
 99→});
100→const store = new SessionStore();
101→
102→// ── Multi-agent state ──────────────────────────────────────────────────────
103→
104→interface AgentState {
105→  agentId: string;
106→  claudeSocket: WebSocket | null;
107→  tmuxSession: string | null;
108→  pendingPrompt: string | null;
109→  status: AgentStatus;
110→  label: string;
111→  createdAt: number;
112→  /** Captured from system/init, used in subsequent user messages. */
113→  sessionId: string | null;
114→  /** Stores control_request inputs keyed by request_id, for building control_responses. */
115→  pendingControlRequests: Map<string, Record<string, unknown>>;
116→  /** All messages sent to the browser for this agent (source of truth). */
117→  messageHistory: ServerMessage[];
118→  /** Messages queued while CLI is disconnected, flushed on reconnect. */
119→  pendingMessages: string[];
120→}
121→
122→const agents = new Map<string, AgentState>();
123→const taskStore = new TaskStore();
124→const tasks = new Map<string, Task>();
125→
126→/** All active browser connections (supports multiple tabs). */
127→const browserSockets = new Set<WebSocket>();
128→
129→/** Generate a short random agent ID. */
130→function newAgentId(): string {
131→  return randomBytes(4).toString("hex");
132→}
133→
134→// ── tmux helpers ───────────────────────────────────────────────────────────
135→
136→/** Return the set of currently alive tmux session names matching the thos prefix. */
137→function listAliveTmuxSessions(): Set<string> {
138→  try {
139→    const output = execSync("tmux list-sessions -F '#{session_name}'", {
140→      encoding: "utf-8",
141→    }).trim();
142→    if (!output) return new Set();
143→    return new Set(output.split("\n").filter((s) => s.startsWith(TMUX_SESSION_PREFIX)));
144→  } catch {
145→    return new Set();
146→  }
147→}
148→
149→// ── Persistence helpers ────────────────────────────────────────────────────
150→
151→/** Build a PersistedAgent snapshot from live state. */
152→function toPersistedAgent(agent: AgentState): PersistedAgent {
153→  return {
154→    id: agent.agentId,
155→    state: {
156→      agentId: agent.agentId,
157→      status: agent.status,
158→      tmuxSession: agent.tmuxSession,
159→      label: agent.label,
160→      createdAt: agent.createdAt,
161→      sessionId: agent.sessionId,
162→    },
163→    messageHistory: agent.messageHistory,
164→  };
165→}
166→
167→/**
168→ * Compact a message history by deduplicating cumulative snapshots.
169→ * Keeps only the last version of each assistant/user message ID.
170→ * Called on restore to shrink legacy bloated histories.
171→ */
172→function compactHistory(history: ServerMessage[]): ServerMessage[] {
173→  // Build a map of msgId → last index
174→  const lastIndex = new Map<string, number>();
175→  for (let i = 0; i < history.length; i++) {
176→    const id = getRelayMessageId(history[i]);
177→    if (id) lastIndex.set(id, i);
178→  }
179→  // Keep only messages that are either non-deduplicable or the last occurrence
180→  return history.filter((msg, i) => {
181→    const id = getRelayMessageId(msg);
182→    if (!id) return true; // non-relay or no message ID — always keep
183→    return lastIndex.get(id) === i;
184→  });
185→}
186→
187→/** Persist agent state (debounced — use for streaming events). */
188→function persistAgent(agent: AgentState) {
189→  store.save(toPersistedAgent(agent));
190→}
191→
192→/** Persist agent state immediately (use for critical state changes). */
193→function persistAgentSync(agent: AgentState) {
194→  store.saveSync(toPersistedAgent(agent));
195→}
196→
197→// ── Restore from disk on startup ───────────────────────────────────────────
198→
199→function restoreAgents() {
200→  const persisted = store.loadAll();
201→  const aliveSessions = listAliveTmuxSessions();
202→
203→  for (const p of persisted) {
204→    const agent: AgentState = {
205→      agentId: p.state.agentId,
206→      claudeSocket: null,
207→      tmuxSession: p.state.tmuxSession,
208→      pendingPrompt: null,
209→      status: p.state.status,
210→      label: p.state.label,
211→      createdAt: p.state.createdAt,
212→      sessionId: p.state.sessionId,
213→      pendingControlRequests: new Map(),
214→      messageHistory: compactHistory(p.messageHistory),
215→      pendingMessages: [],
216→    };
217→
218→    // Determine status for agents that were active when the server last ran
219→    if (agent.status !== "done" && agent.status !== "error") {
220→      const tmuxAlive = agent.tmuxSession ? aliveSessions.has(agent.tmuxSession) : false;
221→      if (tmuxAlive) {
222→        // tmux session still alive — CLI may reconnect to this server
223→        agent.status = "disconnected";
224→        console.log(`[restore] agent ${agent.agentId} — tmux alive, waiting for CLI reconnect`);
225→      } else {
226→        // tmux session gone — agent is archived
227→        agent.status = "done";
228→        console.log(`[restore] agent ${agent.agentId} — tmux dead, archived`);
229→      }
230→    }
231→
232→    agents.set(agent.agentId, agent);
233→    const originalCount = p.messageHistory.length;
234→    const compactedCount = agent.messageHistory.length;
235→    const saved = originalCount - compactedCount;
236→    console.log(`[restore] agent ${agent.agentId} (status=${agent.status}, ${compactedCount} messages${saved > 0 ? `, compacted from ${originalCount} (−${saved})` : ""})`);
237→
238→    // Persist compacted history back to disk
239→    if (saved > 0) {
240→      persistAgentSync(agent);
241→    }
242→  }
243→  console.log(`[restore] loaded ${persisted.length} agents from disk`);
244→}
245→
246→restoreAgents();
247→
248→// ── Task restore + helpers ────────────────────────────────────────────────
249→
250→function restoreTasks() {
251→  const persisted = taskStore.loadAll();
252→  for (const t of persisted) {
253→    tasks.set(t.id, t);
254→  }
255→  console.log(`[restore] loaded ${persisted.length} tasks from disk`);
256→}
257→
258→restoreTasks();
259→
260→/** Build the full task list sorted by creation time (newest first). */
261→function buildTaskList(): Task[] {
262→  return Array.from(tasks.values()).sort((a, b) => b.createdAt - a.createdAt);
263→}
264→
265→/** Send the full task list to all browsers. */
266→function broadcastTaskList() {
267→  const payload = JSON.stringify({ type: "task_list", tasks: buildTaskList() });
268→  for (const ws of browserSockets) {
269→    if (ws.readyState === WebSocket.OPEN) {
270→      ws.send(payload);
271→    }
272→  }
273→}
274→
275→/** Persist all tasks to disk (sync). */
276→function persistTasks() {
277→  taskStore.saveSync(Array.from(tasks.values()));
278→}
279→
280→// ── Helpers ────────────────────────────────────────────────────────────────
281→
282→/** Send a JSON message to all connected browsers. */
283→function sendToBrowser(msg: ServerMessage) {
284→  const payload = JSON.stringify(msg);
285→  for (const ws of browserSockets) {
286→    if (ws.readyState === WebSocket.OPEN) {
287→      ws.send(payload);
288→    }
289→  }
290→}
291→
292→/** Build a snapshot of all agents for the sidebar. */
293→function buildAgentList(): AgentInfo[] {
294→  return Array.from(agents.values()).map((a) => ({
295→    agentId: a.agentId,
296→    status: a.status,
297→    tmuxSession: a.tmuxSession,
298→    label: a.label,
299→    createdAt: a.createdAt,
300→  }));
301→}
302→
303→/** Send the full agent list to all browsers. */
304→function broadcastAgentList() {
305→  sendToBrowser({ type: "agent_list", agents: buildAgentList() });
306→}
307→
308→/** Update an agent's status, notify browsers, broadcast list, and persist. */
309→function setAgentStatus(agentId: string, status: AgentStatus) {
310→  const agent = agents.get(agentId);
311→  if (!agent) return;
312→  agent.status = status;
313→  sendToBrowser({ type: "status", agentId, status });
314→  broadcastAgentList();
315→  persistAgentSync(agent);
316→}
317→
318→/**
319→ * Extract a stable dedup key from a relay message, if present.
320→ *
321→ * Claude NDJSON sends cumulative snapshots for two message types:
322→ * - `assistant` — keyed by `message.id` (e.g. `msg_01VE1P7c...`)
323→ * - `user` (tool_result) — keyed by top-level `uuid` (e.g. `b217b852-...`)
324→ *
325→ * Additionally, one-per-session messages are deduplicated by session_id:
326→ * - `system/init` — keyed by `init:<session_id>`
327→ * - `result` — keyed by `result:<session_id>`
328→ *
329→ * We deduplicate by replacing the previous snapshot in `messageHistory`
330→ * instead of appending, reducing storage from O(n²) to O(n).
331→ */
332→function getRelayMessageId(msg: ServerMessage): string | null {
333→  if (msg.type !== "relay") return null;
334→  const inner = msg.message;
335→  if (inner.type === "assistant") {
336→    return (inner as { message?: { id?: string } }).message?.id ?? null;
337→  }
338→  if (inner.type === "user") {
339→    return (inner as { uuid?: string }).uuid ?? null;
340→  }
341→  // Dedup system/init and result by session_id so they don't stack on reload
342→  if (inner.type === "system" && (inner as { subtype?: string }).subtype === "init") {
343→    const sid = (inner as { session_id?: string }).session_id;
344→    return sid ? `init:${sid}` : null;
345→  }
346→  if (inner.type === "result") {
347→    const sid = (inner as { session_id?: string }).session_id;
348→    return sid ? `result:${sid}` : null;
349→  }
350→  return null;
351→}
352→
353→/**
354→ * Record a message in the agent's history and send to all browsers.
355→ *
356→ * For cumulative snapshot messages (assistant, user/tool_result), replaces the
357→ * previous snapshot with the same message ID instead of appending. This keeps
358→ * only the final version of each message, dramatically reducing file sizes
359→ * (e.g. 38 MB → ~1 MB for a typical session).
360→ */
361→function recordAndSend(agentId: string, msg: ServerMessage) {
362→  const agent = agents.get(agentId);
363→  if (agent) {
364→    const msgId = getRelayMessageId(msg);
365→    if (msgId) {
366→      // Replace previous snapshot with same message ID (search from end for speed)
367→      let replaced = false;
368→      for (let i = agent.messageHistory.length - 1; i >= 0; i--) {
369→        if (getRelayMessageId(agent.messageHistory[i]) === msgId) {
370→          agent.messageHistory[i] = msg;
371→          replaced = true;
372→          break;
373→        }
374→      }
375→      if (!replaced) {
376→        agent.messageHistory.push(msg);
377→      }
378→    } else {
379→      agent.messageHistory.push(msg);
380→    }
381→    persistAgent(agent); // debounced — streaming messages come fast
382→  }
383→  sendToBrowser(msg);
384→}
385→
386→// ── Agent lifecycle ────────────────────────────────────────────────────────
387→
388→/**
389→ * Stop a running agent by killing its tmux session and closing the CLI socket.
390→ * The agent remains in the Map (status set to "done") so it can be viewed/deleted later.
391→ */
392→function stopAgent(agentId: string) {
393→  const agent = agents.get(agentId);
394→  if (!agent) return;
395→
396→  if (agent.tmuxSession) {
397→    try {
398→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
399→      console.log(`[tmux] killed session ${agent.tmuxSession}`);
400→    } catch {
401→      // Session may already be dead
402→    }
403→  }
404→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
405→    agent.claudeSocket.close();
406→  }
407→  agent.claudeSocket = null;
408→  setAgentStatus(agentId, "done");
409→}
410→
411→/**
412→ * Permanently delete an agent: stop it, remove from Map, remove from disk.
413→ */
414→function deleteAgent(agentId: string) {
415→  const agent = agents.get(agentId);
416→  if (!agent) return;
417→
418→  if (agent.tmuxSession) {
419→    try {
420→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
421→    } catch {}
422→  }
423→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
424→    agent.claudeSocket.close();
425→  }
426→  agents.delete(agentId);
427→  store.remove(agentId);
428→  broadcastAgentList();
429→}
430→
431→/**
432→ * Spawn a new Claude CLI process inside a tmux session.
433→ *
434→ * Creates a new agent entry, spawns the CLI with `--sdk-url` pointing to
435→ * `/claude/<agentId>`, and sends a `spawned` message to the browser.
436→ */
437→function spawnClaude(prompt: string): string {
438→  const agentId = newAgentId();
439→  const sessionName = `${TMUX_SESSION_PREFIX}-${agentId}`;
440→  const label = prompt.length > 60 ? prompt.slice(0, 57) + "..." : prompt;
441→
442→  const agent: AgentState = {
443→    agentId,
444→    claudeSocket: null,
445→    tmuxSession: null,
446→    pendingPrompt: prompt,
447→    status: "spawning",
448→    label,
449→    createdAt: Date.now(),
450→    sessionId: null,
451→    pendingControlRequests: new Map(),
452→    messageHistory: [],
453→    pendingMessages: [],
454→  };
455→  agents.set(agentId, agent);
456→
457→  // Notify browsers
458→  sendToBrowser({ type: "spawned", agentId });
459→  broadcastAgentList();
460→  persistAgentSync(agent);
461→
462→  // Build the claude command with CLAUDECODE unset to bypass nesting protection.
463→  // tmux new-session runs detached (-d) so spawn() returns immediately.
464→  const claudeCmd = `unset CLAUDECODE; exec claude --dangerously-skip-permissions --sdk-url ws://localhost:${PORT}/claude/${agentId}`;
465→
466→  const tmux = spawn("tmux", ["new-session", "-d", "-s", sessionName, "bash", "-c", claudeCmd], {
467→    stdio: "ignore",
468→  });
469→
470→  tmux.on("error", (err) => {
471→    console.error("[tmux spawn error]", err);
472→    setAgentStatus(agentId, "error");
473→    recordAndSend(agentId, { type: "error", agentId, error: `tmux error: ${err.message}` });
474→  });
475→
476→  tmux.on("exit", (code) => {
477→    if (code !== 0) {
478→      console.error(`[tmux] new-session exited with code ${code}`);
479→      setAgentStatus(agentId, "error");
480→      recordAndSend(agentId, { type: "error", agentId, error: `tmux exited with code ${code}` });
481→      return;
482→    }
483→    console.log(`[tmux] session ${sessionName} created — attach with: tmux attach -t ${sessionName}`);
484→    agent.tmuxSession = sessionName;
485→    broadcastAgentList();
486→    persistAgentSync(agent);
487→  });
488→
489→  return agentId;
490→}
491→
492→// ── Message handlers ───────────────────────────────────────────────────────
493→
494→/**
495→ * Process an incoming NDJSON message from a specific Claude CLI.
496→ *
497→ * Status flow matches the Companion protocol:
498→ * - hook_response → send pending prompt → "thinking"
499→ * - system/init   → "connected" + capture session_id
500→ * - assistant      → "thinking"
501→ * - result         → "connected" (CLI stays alive for multi-turn)
502→ * - CLI disconnect → "done" (handled in connection close handler)
503→ */
504→function handleClaudeMessage(agentId: string, raw: string) {
505→  const agent = agents.get(agentId);
506→  if (!agent) return;
507→
508→  let msg: ClaudeMessage;
509→  try {
510→    msg = JSON.parse(raw);
511→  } catch {
512→    console.error(`[claude:${agentId}] invalid JSON:`, raw);
513→    return;
514→  }
515→
516→  // Silently ignore keep_alive messages
517→  if (msg.type === "keep_alive") return;
518→
519→  console.log(`[claude:${agentId} →]`, msg.type, (msg as { subtype?: string }).subtype ?? "");
520→
521→  // After hook_response, send the pending prompt
522→  if (
523→    msg.type === "system" &&
524→    (msg as { subtype?: string }).subtype === "hook_response" &&
525→    agent.pendingPrompt &&
526→    agent.claudeSocket?.readyState === WebSocket.OPEN
527→  ) {
528→    const userMsg = JSON.stringify({
529→      type: "user",
530→      message: { role: "user", content: agent.pendingPrompt },
531→      parent_tool_use_id: null,
532→      session_id: agent.sessionId ?? "",
533→    });
534→    console.log(`[server → claude:${agentId}]`, userMsg);
535→    agent.claudeSocket.send(userMsg + "\n");
536→    agent.pendingPrompt = null;
537→    setAgentStatus(agentId, "thinking");
538→  }
539→
540→  // Track status based on message type
541→  if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
542→    // Capture session_id for subsequent user messages
543→    agent.sessionId = (msg as { session_id?: string }).session_id ?? null;
544→    setAgentStatus(agentId, "connected");
545→  } else if (msg.type === "assistant") {
546→    setAgentStatus(agentId, "thinking");
547→  } else if (msg.type === "result") {
548→    // CLI stays alive after result — ready for the next turn.
549→    // Status only goes to "done" when the CLI WebSocket actually closes.
550→    setAgentStatus(agentId, "connected");
551→  }
552→
553→  // Store control_request inputs for building proper responses later
554→  if (msg.type === "control_request") {
555→    const cr = msg as { request_id?: string; request?: { input?: Record<string, unknown> } };
556→    if (cr.request_id && cr.request?.input) {
557→      agent.pendingControlRequests.set(cr.request_id, cr.request.input);
558→    }
559→  }
560→
561→  // Record in history and relay to browsers
562→  recordAndSend(agentId, { type: "relay", agentId, message: msg });
563→}
564→
565→/**
566→ * Process an incoming JSON message from the browser.
567→ * - `spawn`: create a new agent (does NOT kill others).
568→ * - `send_message`: forward a follow-up user message to the specified agent.
569→ * - `control_response`: forward a tool allow/deny decision to the specified agent.
570→ * - `kill_agent`: stop the CLI and tmux session.
571→ * - `delete_agent`: permanently remove an agent.
572→ * - `rename_agent`: update an agent's label.
573→ * - `clear_history`: wipe an agent's message history.
574→ * - `request_history`: send message history for a single agent (lazy loading).
575→ * - `create_task` / `update_task` / `delete_task` / `delegate_task`: task CRUD.
576→ */
577→function handleBrowserMessage(raw: string, senderWs: WebSocket) {
578→  let msg: BrowserMessage;
579→  try {
580→    msg = JSON.parse(raw);
581→  } catch {
582→    console.error("[browser] invalid JSON:", raw);
583→    return;
584→  }
585→
586→  console.log("[browser →]", msg.type);
587→
588→  switch (msg.type) {
589→    case "spawn":
590→      spawnClaude(msg.prompt);
591→      break;
592→
593→    case "send_message": {
594→      const agent = agents.get(msg.agentId);
595→      if (!agent) {
596→        sendToBrowser({ type: "error", agentId: msg.agentId, error: "Unknown agent" });
597→        break;
598→      }
599→
600→      // Record the user message in history so it persists across reloads.
601→      // Do NOT broadcast — the sending browser already has it optimistically,
602→      // and other browsers will get it when they request_history.
603→      agent.messageHistory.push({
604→        type: "relay",
605→        agentId: msg.agentId,
606→        message: { type: "user", message: { role: "user", content: msg.content } },
607→      } as ServerMessage);
608→      persistAgent(agent);
609→
610→      if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
611→        const userMsg = JSON.stringify({
612→          type: "user",
613→          message: { role: "user", content: msg.content },
614→          parent_tool_use_id: null,
615→          session_id: agent.sessionId ?? "",
616→        });
617→        agent.claudeSocket.send(userMsg + "\n");
618→        setAgentStatus(msg.agentId, "thinking");
619→      } else {
620→        // Queue message for delivery when CLI reconnects
621→        const userMsg = JSON.stringify({
622→          type: "user",
623→          message: { role: "user", content: msg.content },
624→          parent_tool_use_id: null,
625→          session_id: agent.sessionId ?? "",
626→        });
627→        agent.pendingMessages.push(userMsg);
628→        console.log(`[queue] queued message for agent ${msg.agentId} (${agent.pendingMessages.length} pending)`);
629→        persistAgentSync(agent);
630→      }
631→      break;
632→    }
633→
634→    case "control_response": {
635→      const agent = agents.get(msg.agentId);
636→      if (agent?.claudeSocket?.readyState === WebSocket.OPEN) {
637→        // Retrieve the original tool input to include as updatedInput (required by protocol)
638→        const originalInput = agent.pendingControlRequests.get(msg.request_id) ?? {};
639→        agent.pendingControlRequests.delete(msg.request_id);
640→
641→        // If the browser sent answers (from AskUserQuestion), merge them into the input
642→        const answers = (msg as { answers?: Record<string, string> }).answers;
643→        const updatedInput = answers
644→          ? { ...originalInput, answers }
645→          : originalInput;
646→
647→        const response = JSON.stringify({
648→          type: "control_response",
649→          response: {
650→            subtype: "success",
651→            request_id: msg.request_id,
652→            response: msg.allow
653→              ? { behavior: "allow", updatedInput }
654→              : { behavior: "deny", message: "Denied by user" },
655→          },
656→        });
657→        agent.claudeSocket.send(response + "\n");
658→      }
659→      break;
660→    }
661→
662→    case "kill_agent":
663→      stopAgent(msg.agentId);
664→      break;
665→
666→    case "delete_agent":
667→      deleteAgent(msg.agentId);
668→      break;
669→
670→    case "rename_agent": {
671→      const agent = agents.get(msg.agentId);
672→      if (!agent) break;
673→      agent.label = msg.label;
674→      broadcastAgentList();
675→      persistAgentSync(agent);
676→      break;
677→    }
678→
679→    case "clear_history": {
680→      const agent = agents.get(msg.agentId);
681→      if (!agent) break;
682→      agent.messageHistory = [];
683→      persistAgentSync(agent);
684→      sendToBrowser({ type: "history_cleared", agentId: msg.agentId });
685→      break;
686→    }
687→
688→    case "request_history": {
689→      console.log(`[browser] request_history for ${msg.agentId}`);
690→      sendHistoryToSocket(senderWs, msg.agentId);
691→      break;
692→    }
693→
694→    case "create_task": {
695→      const taskId = randomBytes(4).toString("hex");
696→      const task: Task = {
697→        id: taskId,
698→        title: msg.title,
699→        description: msg.description,
700→        status: "todo",
701→        priority: msg.priority,
702→        agentId: null,
703→        createdAt: Date.now(),
704→        updatedAt: Date.now(),
705→      };
706→      tasks.set(taskId, task);
707→      persistTasks();
708→      broadcastTaskList();
709→      break;
710→    }
711→
712→    case "update_task": {
713→      const task = tasks.get(msg.taskId);
714→      if (!task) break;
715→      Object.assign(task, msg.updates, { updatedAt: Date.now() });
716→      persistTasks();
717→      broadcastTaskList();
718→      break;
719→    }
720→
721→    case "delete_task": {
722→      tasks.delete(msg.taskId);
723→      persistTasks();
724→      broadcastTaskList();
725→      break;
726→    }
727→
728→    case "delegate_task": {
729→      const task = tasks.get(msg.taskId);
730→      if (!task) break;
731→      const prompt = `Task: ${task.title}\n\n${task.description}`;
732→      const agentId = spawnClaude(prompt);
733→      task.agentId = agentId;
734→      task.status = "in-progress";
735→      task.updatedAt = Date.now();
736→      persistTasks();
737→      broadcastTaskList();
738→      break;
739→    }
740→  }
741→}
742→
743→// ── Send message history to a single browser socket ────────────────────────
744→
745→/** Send initial state (agent list + tasks) to a newly connected browser. */
746→function sendFullStateToSocket(ws: WebSocket) {
747→  if (ws.readyState !== WebSocket.OPEN) return;
748→
749→  // Agent list (sidebar metadata) — message histories are loaded lazily on demand
750→  ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList() }));
751→
752→  // Task list
753→  ws.send(JSON.stringify({ type: "task_list", tasks: buildTaskList() }));
754→}
755→
756→/** Send message history for a single agent to a specific browser socket. */
757→function sendHistoryToSocket(ws: WebSocket, agentId: string) {
758→  const agent = agents.get(agentId);
759→  if (!agent || ws.readyState !== WebSocket.OPEN) return;
760→  ws.send(
761→    JSON.stringify({
762→      type: "message_history",
763→      agentId: agent.agentId,
764→      messages: agent.messageHistory,
765→    })
766→  );
767→}
768→
769→// ── Connection handler — route by URL path ────────────────────────────────
770→wss.on("connection", (ws: WebSocket, req: IncomingMessage) => {
771→  const path = req.url ?? "/";
772→  console.log(`[ws connected] path=${path}`);
773→
774→  if (path === "/browser") {
775→    // Send full state BEFORE adding to browserSockets so that live
776→    // relay broadcasts don't interleave with the history replay.
777→    sendFullStateToSocket(ws);
778→    browserSockets.add(ws);
779→
780→    ws.on("message", (data) => {
781→      handleBrowserMessage(data.toString(), ws);
782→    });
783→
784→    ws.on("close", () => {
785→      console.log("[browser disconnected]");
786→      browserSockets.delete(ws);
787→      // Do NOT kill agents — keep them alive for reconnect
788→    });
789→  } else if (path.startsWith("/claude/")) {
790→    // Parse agentId from /claude/<agentId>
791→    const agentId = path.slice("/claude/".length);
792→    const agent = agents.get(agentId);
793→
794→    if (!agent) {
795→      console.log(`[ws] unknown agentId: ${agentId}, closing`);
796→      ws.close();
797→      return;
798→    }
799→
800→    agent.claudeSocket = ws;
801→    console.log(`[claude:${agentId} CLI connected via WebSocket]`);
802→
803→    // Notify browsers that CLI is connected
804→    sendToBrowser({ type: "cli_connected", agentId });
805→
806→    // Flush any pending messages queued while CLI was disconnected
807→    if (agent.pendingMessages.length > 0) {
808→      console.log(`[flush] sending ${agent.pendingMessages.length} queued messages to agent ${agentId}`);
809→      for (const queued of agent.pendingMessages) {
810→        ws.send(queued + "\n");
811→      }
812→      agent.pendingMessages = [];
813→      persistAgentSync(agent);
814→    }
815→
816→    // Send the pending prompt immediately — CLI 2.1.42+ waits for the
817→    // server to send the first user message rather than emitting
818→    // hook_started/hook_response on connect.
819→    if (agent.pendingPrompt && ws.readyState === WebSocket.OPEN) {
820→      const userMsg = JSON.stringify({
821→        type: "user",
822→        message: { role: "user", content: agent.pendingPrompt },
823→        parent_tool_use_id: null,
824→        session_id: agent.sessionId ?? "",
825→      });
826→      console.log(`[server → claude:${agentId}] sending pending prompt`);
827→      ws.send(userMsg + "\n");
828→      agent.pendingPrompt = null;
829→      setAgentStatus(agentId, "thinking");
830→    }
831→
832→    ws.on("message", (data) => {
833→      handleClaudeMessage(agentId, data.toString());
834→    });
835→
836→    ws.on("close", () => {
837→      console.log(`[claude:${agentId} CLI disconnected]`);
838→      if (agent.claudeSocket === ws) {
839→        agent.claudeSocket = null;
840→        if (agent.status !== "error") {
841→          setAgentStatus(agentId, "done");
842→          sendToBrowser({ type: "cli_disconnected", agentId });
843→
844→          // Auto-complete any task linked to this agent
845→          for (const task of tasks.values()) {
846→            if (task.agentId === agentId && task.status !== "done") {
847→              task.status = "done";
848→              task.updatedAt = Date.now();
849→              persistTasks();
850→              broadcastTaskList();
851→              break;
852→            }
853→          }
854→        }
855→      }
856→    });
857→  } else {
858→    console.log(`[ws] unknown path: ${path}, closing`);
859→    ws.close();
860→  }
861→});
862→
863→// ── Graceful shutdown ─────────────────────────────────────────────────────
864→
865→function shutdown() {
866→  console.log("[ws server] shutting down...");
867→
868→  // Persist all agents synchronously before exit — do NOT kill tmux sessions
869→  // so CLI processes can reconnect if the server restarts.
870→  const allPersisted = Array.from(agents.values()).map(toPersistedAgent);
871→  store.flushAll(allPersisted);
872→  console.log(`[ws server] saved ${allPersisted.length} agents to disk (tmux sessions preserved)`);
873→
874→  taskStore.flush(Array.from(tasks.values()));
875→  console.log(`[ws server] saved ${tasks.size} tasks to disk`);
876→
877→  wss.close();
878→  process.exit(0);
879→}
880→
881→process.on("SIGTERM", shutdown);
882→process.on("SIGINT", shutdown);
883→
884→console.log(`[ws server] listening on port ${PORT}`);
885→

