232→export function useWebSocket() {
233→  const wsRef = useRef<WebSocket | null>(null);
234→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
235→  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
236→  const closingRef = useRef(false);
237→  const [connected, setConnected] = useState(false);
238→  /** True once we've received the initial agent_list from the server. */
239→  const [initialLoadDone, setInitialLoadDone] = useState(false);
240→
241→  // Multi-agent state
242→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
243→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
244→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
245→
246→  // Task state
247→  const [tasks, setTasks] = useState<Task[]>([]);
248→
249→  // Per-agent deduplication: track count of processed messages per agent
250→  // to avoid duplicating messages already in local state during history replay.
251→  const processedCountRef = useRef<Map<string, number>>(new Map());
252→
253→  // Track which agents have had their history loaded (lazy loading).
254→  const [loadedAgents, setLoadedAgents] = useState<Set<string>>(new Set());
255→
256→  /** Immutably update a single agent's state in the Map. */
257→  const updateAgent = useCallback(
258→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
259→      setAgents((prev) => {
260→        const existing = prev.get(agentId);
261→        if (!existing) return prev;
262→        const next = new Map(prev);
263→        next.set(agentId, updater(existing));
264→        return next;
265→      });
266→    },
267→    []
268→  );
269→
270→  const connect = useCallback(() => {
271→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
272→    if (wsRef.current) {
273→      wsRef.current.close();
274→      wsRef.current = null;
275→    }
276→
277→    // Reset dedup counts on new connection — server will send fresh history
278→    processedCountRef.current.clear();
279→    setInitialLoadDone(false);
280→    setLoadedAgents(new Set());
281→
282→    log("connecting to", WS_URL);
283→    const ws = new WebSocket(WS_URL);
284→    wsRef.current = ws;
285→
286→    ws.onopen = () => {
287→      log("connected");
288→      setConnected(true);
289→    };
290→
291→    ws.onclose = () => {
292→      log("disconnected, closingRef =", closingRef.current);
293→      setConnected(false);
294→      wsRef.current = null;
295→      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
296→      if (closingRef.current) return;
297→      // Reconnection guard: clear any existing timer before scheduling
298→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
299→      log("scheduling reconnect in 2s");
300→      reconnectTimer.current = setTimeout(() => connect(), 2000);
301→    };
302→
303→    ws.onerror = (e) => {
304→      log("error", e);
305→      // onclose will fire after onerror, which triggers reconnect
306→    };
307→
308→    ws.onmessage = (event) => {
309→      let data: ServerMessage;
310→      try {
311→        data = JSON.parse(event.data as string);
312→      } catch {
313→        return;
314→      }
315→
316→      log("←", data.type, "agentId" in data ? (data as { agentId: string }).agentId : "");
317→
318→      // ── task_list: full task list from server ──
319→      if (data.type === "task_list") {
320→        log("task_list:", (data as ServerTaskList).tasks.length, "tasks");
321→        setTasks((data as ServerTaskList).tasks);
322→        return;
323→      }
324→
325→      // ── task_updated: single task changed ──
326→      if (data.type === "task_updated") {
327→        const updated = (data as ServerTaskUpdated).task;
328→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
329→        return;
330→      }
331→
332→      // ── task_deleted: remove task ──
333→      if (data.type === "task_deleted") {
334→        const deletedId = (data as ServerTaskDeleted).taskId;
335→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
336→        return;
337→      }
338→
339→      // ── message_history: replay full history from server ──
340→      if (data.type === "message_history") {
341→        const historyMsg = data as ServerMessageHistory;
342→        const agentId = historyMsg.agentId;
343→        const serverMessages = historyMsg.messages;
344→        log("message_history:", agentId, serverMessages.length, "raw msgs");
345→
346→        // Convert all server messages to ChatMessages + extract raw Claude messages
347→        const chatMessages: ChatMessage[] = [];
348→        const rawMessages: ClaudeMessage[] = [];
349→        for (const sm of serverMessages) {
350→          if (sm.type === "relay") {
351→            rawMessages.push(sm.message);
352→          }
353→          const cm = relayChatMessage(agentId, sm);
354→          if (cm) chatMessages.push(cm);
355→        }
356→        log("message_history:", agentId, "→", chatMessages.length, "chat msgs,", rawMessages.length, "raw");
357→
358→        // Always replace local messages with server history (source of truth).
359→        setAgents((prev) => {
360→          const existing = prev.get(agentId);
361→          if (!existing) {
362→            log("message_history:", agentId, "agent not in map yet, creating");
363→            const next = new Map(prev);
364→            next.set(agentId, {
365→              status: "idle",
366→              messages: chatMessages,
367→              rawMessages,
368→              label: "",
369→              tmuxSession: null,
370→              createdAt: 0,
371→            });
372→            return next;
373→          }
374→          const next = new Map(prev);
375→          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
376→          return next;
377→        });
378→
379→        processedCountRef.current.set(agentId, chatMessages.length);
380→        setLoadedAgents((prev) => {
381→          if (prev.has(agentId)) return prev;
382→          const next = new Set(prev);
383→          next.add(agentId);
384→          return next;
385→        });
386→        return;
387→      }
388→
389→      // ── history_cleared: wipe local messages for this agent ──
390→      if (data.type === "history_cleared") {
391→        updateAgent(data.agentId, (prev) => ({
392→          ...prev,
393→          messages: [],
394→          rawMessages: [],
395→        }));
396→        processedCountRef.current.set(data.agentId, 0);
397→        return;
398→      }
399→
400→      // ── cli_disconnected: show system message ──
401→      if (data.type === "cli_disconnected") {
402→        updateAgent(data.agentId, (prev) => ({
403→          ...prev,
404→          messages: [
405→            ...prev.messages,
406→            {
407→              id: nextId(),
408→              role: "system",
409→              content: "CLI session ended",
410→              timestamp: Date.now(),
411→            },
412→          ],
413→        }));
414→        return;
415→      }
416→
417→      // ── cli_connected: show system message ──
418→      if (data.type === "cli_connected") {
419→        updateAgent(data.agentId, (prev) => ({
420→          ...prev,
421→          messages: [
422→            ...prev.messages,
423→            {
424→              id: nextId(),
425→              role: "system",
426→              content: "CLI reconnected",
427→              timestamp: Date.now(),
428→            },
429→          ],
430→        }));
431→        return;
432→      }
433→
434→      // ── agent_list: reconcile sidebar state from server ──
435→      if (data.type === "agent_list") {
436→        const serverAgents = data.agents as AgentInfo[];
437→        log("agent_list:", serverAgents.length, "agents:", serverAgents.map((a) => `${a.agentId}(${a.status})`).join(", "));
438→        setAgents((prev) => {
439→          const next = new Map(prev);
440→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
441→
442→          // Update or add agents from server
443→          for (const info of serverAgents) {
444→            const existing = next.get(info.agentId);
445→            if (existing) {
446→              next.set(info.agentId, {
447→                ...existing,
448→                status: info.status,
449→                tmuxSession: info.tmuxSession,
450→                label: info.label,
451→              });
452→            } else {
453→              next.set(info.agentId, {
454→                status: info.status,
455→                messages: [],
456→                rawMessages: [],
457→                label: info.label,
458→                tmuxSession: info.tmuxSession,
459→                createdAt: info.createdAt,
460→              });
461→            }
462→          }
463→
464→          // Remove agents no longer on the server
465→          for (const id of next.keys()) {
466→            if (!serverIds.has(id)) {
467→              next.delete(id);
468→            }
469→          }
470→
471→          return next;
472→        });
473→        setAgentOrder(serverAgents.map((a) => a.agentId));
474→        setInitialLoadDone(true);
475→
476→        // Auto-select the first agent on initial load when nothing is selected
477→        setActiveAgentId((prev) => {
478→          if (prev !== null) return prev;
479→          if (serverAgents.length === 0) return null;
480→          return serverAgents[0].agentId;
481→        });
482→        return;
483→      }
484→
485→      // ── spawned: auto-select the newly created agent ──
486→      if (data.type === "spawned") {
487→        setActiveAgentId(data.agentId);
488→        return;
489→      }
490→
491→      // ── status: update a specific agent's status ──
492→      if (data.type === "status") {
493→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
494→        return;
495→      }
496→
497→      // ── error: append to agent's message list ──
498→      if (data.type === "error") {
499→        updateAgent(data.agentId, (prev) => ({
500→          ...prev,
501→          messages: [
502→            ...prev.messages,
503→            {
504→              id: nextId(),
505→              role: "system",
506→              content: `Error: ${data.error}`,
507→              timestamp: Date.now(),
508→            },
509→          ],
510→        }));
511→        // Track processed count for dedup
512→        processedCountRef.current.set(
513→          data.agentId,
514→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
515→        );
516→        return;
517→      }
518→
519→      // ── relay: append claude message to agent's history ──
520→      if (data.type === "relay") {
521→        const agentId = data.agentId;
522→        const rawMsg = data.message;
523→        const chatMsg = relayChatMessage(agentId, data);
524→
525→        updateAgent(agentId, (prev) => ({
526→          ...prev,
527→          rawMessages: [...prev.rawMessages, rawMsg],
528→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
529→        }));
530→        if (chatMsg) {
531→          // Track processed count for dedup
532→          processedCountRef.current.set(
533→            agentId,
534→            (processedCountRef.current.get(agentId) ?? 0) + 1
535→          );
536→        }
537→        return;
538→      }
539→    };
540→  }, [updateAgent]);
541→
542→  useEffect(() => {
543→    closingRef.current = false;
544→    connect();
545→    return () => {
546→      closingRef.current = true;
547→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
548→      wsRef.current?.close();
549→    };
550→  }, [connect]);
551→
552→  const send = useCallback((data: object) => {
553→    if (wsRef.current?.readyState === WebSocket.OPEN) {
554→      wsRef.current.send(JSON.stringify(data));
555→    }
556→  }, []);
557→
558→  // Request history for the active agent if not already loaded.
559→  useEffect(() => {
560→    if (!activeAgentId || loadedAgents.has(activeAgentId)) return;
561→    log("requesting history for", activeAgentId);
562→    send({ type: "request_history", agentId: activeAgentId });
563→  }, [activeAgentId, loadedAgents, send]);
564→
565→  const spawnAgent = useCallback(
566→    (prompt: string) => {
567→      send({ type: "spawn", prompt });
568→    },
569→    [send]
570→  );
571→
572→  const sendMessage = useCallback(
573→    (content: string) => {
574→      if (!activeAgentId) return;
575→      // Optimistically add user message to local state
576→      updateAgent(activeAgentId, (prev) => ({
577→        ...prev,
578→        messages: [
579→          ...prev.messages,
580→          {
581→            id: nextId(),
582→            role: "user",
583→            content,
584→            timestamp: Date.now(),
585→          },
586→        ],
587→      }));
588→      send({ type: "send_message", agentId: activeAgentId, content });
589→    },
590→    [send, activeAgentId, updateAgent]
591→  );
592→
593→  const respondToControl = useCallback(
594→    (requestId: string, allow: boolean) => {
595→      if (!activeAgentId) return;
596→      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
597→      updateAgent(activeAgentId, (prev) => ({
598→        ...prev,
599→        messages: prev.messages.map((m) =>
600→          m.controlRequest?.id === requestId
601→            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true, allowed: allow } }
602→            : m
603→        ),
604→      }));
605→    },
606→    [send, activeAgentId, updateAgent]
607→  );
608→
609→  /** Respond to an AskUserQuestion control request with the user's selections. */
610→  const respondToUserQuestion = useCallback(
611→    (requestId: string, answers: Record<string, string>) => {
612→      if (!activeAgentId) return;
613→      send({
614→        type: "control_response",
615→        agentId: activeAgentId,
616→        request_id: requestId,
617→        allow: true,
618→        answers,
619→      });
620→      updateAgent(activeAgentId, (prev) => ({
621→        ...prev,
622→        messages: prev.messages.map((m) =>
623→          m.userQuestion?.requestId === requestId
624→            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
625→            : m
626→        ),
627→      }));
628→    },
629→    [send, activeAgentId, updateAgent]
630→  );
631→
632→  // ── Agent management actions ──────────────────────────────────────────────
633→
634→  const killAgent = useCallback(
635→    (agentId: string) => {
636→      send({ type: "kill_agent", agentId });
637→    },
638→    [send]
639→  );
640→
641→  const deleteAgent = useCallback(
642→    (agentId: string) => {
643→      send({ type: "delete_agent", agentId });
644→      // Deselect if we just deleted the active agent
645→      setActiveAgentId((prev) => (prev === agentId ? null : prev));
646→    },
647→    [send]
648→  );
649→
650→  const renameAgent = useCallback(
651→    (agentId: string, label: string) => {
652→      send({ type: "rename_agent", agentId, label });
653→    },
654→    [send]
655→  );
656→
657→  const clearHistory = useCallback(
658→    (agentId: string) => {
659→      send({ type: "clear_history", agentId });
660→    },
661→    [send]
662→  );
663→
664→  // ── Task actions ──────────────────────────────────────────────────────────
665→
666→  const createTask = useCallback(
667→    (title: string, description: string, priority: TaskPriority) => {
668→      send({ type: "create_task", title, description, priority });
669→    },
670→    [send]
671→  );
672→
673→  const updateTask = useCallback(
674→    (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => {
675→      send({ type: "update_task", taskId, updates });
676→    },
677→    [send]
678→  );
679→
680→  const deleteTask = useCallback(
681→    (taskId: string) => {
682→      send({ type: "delete_task", taskId });
683→    },
684→    [send]
685→  );
686→
687→  const delegateTask = useCallback(
688→    (taskId: string) => {
689→      send({ type: "delegate_task", taskId });
690→    },
691→    [send]
692→  );
693→
694→  // Derived values for the active agent
695→  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
696→  const activeStatus = useMemo<AgentStatus>(
697→    () => activeAgent?.status ?? "idle",
698→    [activeAgent?.status]
699→  );
700→  const activeMessages = useMemo<ChatMessage[]>(
701→    () => activeAgent?.messages ?? [],
702→    [activeAgent?.messages]
703→  );
704→  const activeRawMessages = useMemo<ClaudeMessage[]>(
705→    () => activeAgent?.rawMessages ?? [],
706→    [activeAgent?.rawMessages]
707→  );
708→  const historyLoading = activeAgentId !== null && !loadedAgents.has(activeAgentId);
709→
710→  return {
711→    connected,
712→    initialLoadDone,
713→    historyLoading,
714→    agents,
715→    agentOrder,
716→    activeAgentId,
717→    setActiveAgentId,
718→    activeStatus,
719→    activeMessages,
720→    activeRawMessages,
721→    spawnAgent,
722→    sendMessage,
723→    respondToControl,
724→    respondToUserQuestion,
725→    killAgent,
726→    deleteAgent,
727→    renameAgent,
728→    clearHistory,
729→    tasks,
730→    createTask,
731→    updateTask,
732→    deleteTask,
733→    delegateTask,
734→  };
735→}
736→

