      {/* Branding */}
      <div className="flex items-center gap-2 border-b px-3 py-2">
        <span className="text-primary font-bold text-sm tracking-tight">thos</span>
        <span className="text-muted-foreground text-[10px]">orchestrator</span>
      </div>

