        />
      )}

      {/* Task panel drawer */}
      {taskView !== "hidden" && (
        <div
          className={cn(
            "fixed inset-y-0 right-0 z-50 border-l bg-background flex flex-col md:relative md:z-auto",
            taskView === "board"
              ? "w-full max-w-none"
              : "w-80 max-w-[calc(100vw-3rem)] md:max-w-none"
          )}
        >
          <TaskPanel
            tasks={tasks}
            mode={taskView === "hidden" ? "list" : taskView}
